INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u3-C1','sci',6,1,'u3',1,'다섯 고개 놀이 — 화단의 한 구역을 정해 식물을 살펴봄 → 스마트 기기나 식물도감으로 이름을 확인 → 모둠이 문제로 낼 식물을 정해 사진을 찍음 → 다른 모둠에 사진의 일부분을 보여 줌 → 다른 모둠은 다섯 가지 질문을 한 뒤 이름을 맞힘 → 순서를 바꿔 함 · 다섯 고개 질문은 식물의 생김새나 구조에 관한 것만(키, 꽃잎 수, 잎 모양, 줄기의 가시, 열매 크기)',ARRAY['[6과11-03] 여러 가지 식물의 특징을 설명하는 자료를 만들어 공유할 수 있다.']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u3-C2','sci',6,1,'u3',1,'식물의 기관과 다양한 생김새 — 식물은 뿌리·줄기·잎·꽃 등으로 이루어져 있고 각각의 모양이 매우 다양함 · 소나무는 줄기가 적갈색이고 바늘 모양 잎이 두 개씩 모여 달림 · 애기똥풀은 꽃이 노란색 · 무궁화는 꽃잎이 다섯 장 · 뿌리는 땅속에 있어 사진에 잘 보이지 않음',ARRAY['[6과11-03] 여러 가지 식물의 특징을 설명하는 자료를 만들어 공유할 수 있다.']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u3-C3','sci',6,1,'u3',1,'식물 관찰의 안전과 정보 확인 — 앨러지가 있으면 식물을 직접 만지지 않고 꽃가루 앨러지는 마스크 · 나무에 올라가거나 위험한 장소에 가지 않음 · 식물을 훼손하지 않고 얼굴이나 몸이 긁히지 않게 · 애플리케이션으로 알아본 이름은 식물도감으로 정확한지 확인 · 수업과 관련 있는 자료 말고는 검색하거나 열어 보지 않음 · 생명을 소중히 여기는 마음으로 살펴봄',ARRAY['[6과11-03] 여러 가지 식물의 특징을 설명하는 자료를 만들어 공유할 수 있다.']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u3-C4','sci',6,1,'u3',2,'생물을 이루는 기본 단위 세포 — 첨성대가 돌을 쌓아 만들어졌어도 전체 모양은 돌 모양과 다르듯, 생물은 크기와 생김새가 달라도 모두 세포라는 기본 단위로 이루어짐 · 하나의 생물을 이루는 세포는 종류에 따라 크기와 모양이 다양함',ARRAY['[6과11-01] 생물을 이루고 있는 기본 단위인 세포를 현미경으로 관찰할 수 있다.']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u3-C5','sci',6,1,'u3',2,'식물 세포의 구조 — 세포는 세포막으로 둘러싸여 있고 그 안에 둥근 핵이 있음 · 식물 세포는 세포벽이 세포막의 바깥쪽을 둘러쌈 · 식물 세포는 각진 모양으로 서로 붙어 있고 세포벽이 있어 세포의 경계(가장자리)가 뚜렷함 · 핵은 세포마다 하나씩 보임',ARRAY['[6과11-01] 생물을 이루고 있는 기본 단위인 세포를 현미경으로 관찰할 수 있다.']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u3-C6','sci',6,1,'u3',2,'세포의 크기 — 대부분의 세포는 크기가 매우 작아 현미경을 사용해야 관찰할 수 있음 · 그러나 달걀이나 타조 알 같은 알은 하나의 세포이면서 영양물질을 저장하고 있어 맨눈으로 볼 수 있을 만큼 큼',ARRAY['[6과11-01] 생물을 이루고 있는 기본 단위인 세포를 현미경으로 관찰할 수 있다.']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u3-C7','sci',6,1,'u3',2,'식물 세포 현미경표본 — 사철나무잎 뒷면에 투명 매니큐어를 얇게 바름 → 완전히 마르면 셀로판테이프를 붙여 문지름 → 떼어 받침 유리에 붙임 · 빛이 통과하도록 얇게 만들어야 잘 보임 · 관찰한 모습을 그림과 글로 나타냄 · 매니큐어 냄새를 맡지 않고 창문을 열어 환기 · 받침 유리 모서리에 손을 다치지 않게, 표본이 깨지지 않게',ARRAY['[6과11-01] 생물을 이루고 있는 기본 단위인 세포를 현미경으로 관찰할 수 있다.']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u3-C8','sci',6,1,'u3',3,'뿌리의 생김새 — 뿌리는 주로 땅속으로 자람 · 백합·강아지풀·파처럼 굵기가 비슷한 가는 뿌리가 수염처럼 난 식물도 있고, 민들레·사과나무처럼 굵고 곧은 뿌리에 가는 뿌리가 여러 개 난 식물도 있음 · 뿌리에는 솜털처럼 가는 뿌리털이 있음',ARRAY['[6과11-02] 식물의 각 기관의 구조를 관찰하고, 기능을 알아보는 실험을 수행하여 식물 각 기관의 구조와 기능을 설명할 수 있다.']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u3-C9','sci',6,1,'u3',3,'뿌리의 물 흡수 실험 — 비슷한 크기의 파 두 개 가운데 하나는 잎과 뿌리를, 하나는 잎만 자름 → 탈지면으로 감싸 같은 양의 물이 든 눈금실린더에 넣고 물 높이를 표시 → 햇빛이 잘 드는 곳에 3일 → 뿌리를 자르지 않은 파 쪽 물이 더 많이 줄어듦 → 뿌리가 물을 흡수함 · 다르게 할 조건은 뿌리가 있는지, 같게 할 조건은 물의 양·놓아두는 곳 등 · 뿌리를 자른 파 쪽 물도 조금 줄어듦 · 결과를 함부로 바꾸어 기록하지 않음',ARRAY['[6과11-02] 식물의 각 기관의 구조를 관찰하고, 기능을 알아보는 실험을 수행하여 식물 각 기관의 구조와 기능을 설명할 수 있다.']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u3-C10','sci',6,1,'u3',3,'뿌리가 하는 일 — 식물에 필요한 물을 흡수함(뿌리털이 있어 물을 잘 흡수함) · 땅속 깊이 뻗어 식물이 쓰러지지 않도록 지지함(뿌리 깊은 나무는 바람에 흔들리지 않는다) · 당근·고구마처럼 뿌리에 양분을 저장하는 식물도 있음 · 우리가 먹는 당근은 식물의 뿌리',ARRAY['[6과11-02] 식물의 각 기관의 구조를 관찰하고, 기능을 알아보는 실험을 수행하여 식물 각 기관의 구조와 기능을 설명할 수 있다.']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u3-C11','sci',6,1,'u3',4,'줄기에서 물의 이동 실험 — 백합 줄기를 붉은색 색소를 녹인 물에 넣어 햇빛이 잘 드는 곳에 둠 → 하루 뒤 꽃과 잎이 붉은빛을 띰 → 줄기를 가로로 자른 단면에는 붉은 점들이 퍼져 있고, 세로로 자른 단면에는 붉은 선들이 보임 → 붉게 변한 부분은 물이 이동한 통로 · 줄기를 자를 때 칼에 손을 다치지 않게',ARRAY['[6과11-02] 식물의 각 기관의 구조를 관찰하고, 기능을 알아보는 실험을 수행하여 식물 각 기관의 구조와 기능을 설명할 수 있다.']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u3-C12','sci',6,1,'u3',4,'줄기가 하는 일 — 줄기에는 물이 이동하는 통로가 있어 뿌리에서 흡수한 물이 잎이나 꽃 등 식물의 각 기관으로 이동함 · 줄기는 뿌리와 잎, 꽃 등을 연결함 · 대부분의 식물 줄기는 곧게 서서 식물을 지지함 · 감자처럼 줄기에 양분을 저장하는 식물도 있음',ARRAY['[6과11-02] 식물의 각 기관의 구조를 관찰하고, 기능을 알아보는 실험을 수행하여 식물 각 기관의 구조와 기능을 설명할 수 있다.']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u3-C13','sci',6,1,'u3',4,'여러 가지 줄기 — 봉선화·은행나무처럼 곧게 서는 줄기, 나팔꽃·등나무처럼 다른 식물이나 물체를 감고 올라가는 줄기, 딸기처럼 땅 위를 기듯이 뻗는 줄기, 감자처럼 양분을 저장하는 줄기 · 감자는 뿌리가 아니라 줄기(고구마는 뿌리) · 식물의 종류에 따라 줄기의 생김새와 하는 일이 다양함',ARRAY['[6과11-02] 식물의 각 기관의 구조를 관찰하고, 기능을 알아보는 실험을 수행하여 식물 각 기관의 구조와 기능을 설명할 수 있다.']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u3-C14','sci',6,1,'u3',5,'잎의 생김새 — 식물의 잎은 대부분 잎몸과 잎자루로 이루어져 있음 · 잎몸은 넓적한 부분, 잎자루는 잎몸을 줄기에 붙어 있게 하는 자루 · 잎몸에는 잎맥이 있음 · 잎의 색깔은 대부분 초록색 · 이것은 가장 흔한 모습이고 다른 모습의 잎도 있음',ARRAY['[6과11-02] 식물의 각 기관의 구조를 관찰하고, 기능을 알아보는 실험을 수행하여 식물 각 기관의 구조와 기능을 설명할 수 있다.']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u3-C15','sci',6,1,'u3',5,'광합성 — 식물이 빛을 이용해 이산화 탄소와 물로 양분을 만드는 것 · 광합성은 주로 잎에서 가장 활발하게 일어나지만 잎에서만 일어나는 것은 아니고 초록색을 띠는 다른 부분에서도 일어날 수 있음 · 식물이 양분을 만들려면 빛이 필요함 · 식물마다 알맞은 빛의 양이 달라 햇빛이 무조건 많을수록 좋은 것은 아님',ARRAY['[6과11-02] 식물의 각 기관의 구조를 관찰하고, 기능을 알아보는 실험을 수행하여 식물 각 기관의 구조와 기능을 설명할 수 있다.']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u3-C16','sci',6,1,'u3',5,'광합성으로 만든 양분 확인 — 잎 하나에 알루미늄 포일을 씌워 빛을 막고 화분을 햇빛이 잘 드는 곳에 둠 → 하루 뒤 두 잎을 따서 뜨거운 물에 담갔다가 에탄올로 초록색을 뺌 → 헹군 뒤 녹말을 만나면 색이 변하는 용액을 떨어뜨림 → 포일을 씌우지 않은 잎만 청람색으로 변함 → 햇빛을 받은 잎에서 녹말과 같은 양분이 만들어짐 · 다르게 한 조건은 빛 · 에탄올 기체를 마시지 않고 환기, 뜨거운 물에 화상 입지 않게',ARRAY['[6과11-02] 식물의 각 기관의 구조를 관찰하고, 기능을 알아보는 실험을 수행하여 식물 각 기관의 구조와 기능을 설명할 수 있다.']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u3-C17','sci',6,1,'u3',5,'양분의 이동과 넓은 잎 — 잎에서 만든 양분은 줄기를 통해 식물 전체로 이동해 각 기관에서 쓰이고 남은 양분은 저장됨 · 많은 식물의 잎이 납작하고 넓은 것은 빛을 받는 면이 넓어 광합성이 잘 일어나기 때문',ARRAY['[6과11-02] 식물의 각 기관의 구조를 관찰하고, 기능을 알아보는 실험을 수행하여 식물 각 기관의 구조와 기능을 설명할 수 있다.']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u3-C18','sci',6,1,'u3',6,'증산 작용 — 뿌리에서 흡수한 물은 줄기를 거쳐 잎에 도달하고, 잎에 도달한 물의 일부가 수증기가 되어 식물 밖으로 빠져나가는 것 · 식물이 많은 온실 안이 바깥보다 습한 것도 이 때문 · 증산 작용으로 공기 중의 수증기가 식물 안으로 들어오는 것이 아님',ARRAY['[6과11-02] 식물의 각 기관의 구조를 관찰하고, 기능을 알아보는 실험을 수행하여 식물 각 기관의 구조와 기능을 설명할 수 있다.']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u3-C19','sci',6,1,'u3',6,'증산 작용 확인 실험 — 푸른색 염화 코발트 종이는 물을 흡수하면 붉은색으로 변함 · 한 장은 페트리 접시에, 한 장은 잎 뒷면에 셀로판테이프로 붙여 햇빛이 잘 드는 곳에 둠(페트리 접시의 종이는 견주기 위한 것) → 10분 뒤 잎 뒷면의 종이만 붉게 변함 → 잎을 통해 물이 식물 밖으로 빠져나감 · 종이는 핀셋으로 집고, 실험 뒤 잎이 다치지 않게 떼어 내고 식물을 기름',ARRAY['[6과11-02] 식물의 각 기관의 구조를 관찰하고, 기능을 알아보는 실험을 수행하여 식물 각 기관의 구조와 기능을 설명할 수 있다.']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u3-C20','sci',6,1,'u3',6,'기공 — 잎의 표면을 현미경으로 보면 강낭콩 모양의 세포 두 개 사이에 아주 작은 구멍이 있는데 이것이 기공 · 잎에 도달한 물의 일부는 기공을 통해 식물 밖으로 빠져나감 · 기공은 대부분 잎의 뒷면에 있어 증산 작용은 주로 잎의 뒷면에서 일어남',ARRAY['[6과11-02] 식물의 각 기관의 구조를 관찰하고, 기능을 알아보는 실험을 수행하여 식물 각 기관의 구조와 기능을 설명할 수 있다.']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u3-C21','sci',6,1,'u3',6,'증산 작용이 하는 일 — 뿌리에서 흡수한 물이 잎까지 도달하게 함 · 식물의 온도를 조절함 · 물이 부족한 사막의 식물은 잎이 좁아 증산 작용으로 물을 덜 잃는 것이 살아가기에 유리함 · 증발과 증산 작용은 물이 수증기가 되는 점에서 같은 현상이고, 증산 작용은 그것이 식물의 잎(기공)에서 일어나는 것',ARRAY['[6과11-02] 식물의 각 기관의 구조를 관찰하고, 기능을 알아보는 실험을 수행하여 식물 각 기관의 구조와 기능을 설명할 수 있다.']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u3-C22','sci',6,1,'u3',7,'꽃의 구조 — 꽃은 식물의 종류에 따라 색깔·크기·모양이 다양하지만 공통된 부분이 있음 · 꽃은 암술·수술·꽃잎·꽃받침으로 이루어져 있고 종류에 따라 일부가 없는 꽃도 있음 · 암술 주변을 수술이 둘러싸고, 그 바깥에 꽃잎, 꽃잎 아래쪽에 꽃받침이 있음 · 달맞이꽃 관찰: 암술은 윗부분이 네 갈래, 수술은 노란색, 꽃잎은 각각 떨어져 있고, 꽃받침은 뒤로 젖혀짐',ARRAY['[6과11-02] 식물의 각 기관의 구조를 관찰하고, 기능을 알아보는 실험을 수행하여 식물 각 기관의 구조와 기능을 설명할 수 있다.']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u3-C23','sci',6,1,'u3',7,'꽃이 하는 일 — 꽃은 씨를 만듦 · 수술에 있는 꽃가루가 곤충·새·바람·물 등의 도움으로 암술에 옮겨 붙는 과정이 꽃가루받이 · 꽃가루받이가 이루어지면 암술 속에 씨가 만들어짐 · 꽃잎의 색이 화려하면 벌이나 나비를 끌어들이기 좋아 꽃가루받이가 될 가능성이 높아짐',ARRAY['[6과11-02] 식물의 각 기관의 구조를 관찰하고, 기능을 알아보는 실험을 수행하여 식물 각 기관의 구조와 기능을 설명할 수 있다.']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u3-C24','sci',6,1,'u3',7,'열매 — 꽃가루받이 → 암술 속에 씨가 생김 → 씨가 자라면서 씨를 둘러싼 부분도 함께 자라 열매가 됨(복숭아꽃) · 열매는 씨를 보호하고 씨가 익으면 멀리 퍼지게 함 · 꽃은 씨를 만들고 열매는 씨를 지키고 퍼뜨리며 식물은 대를 이어 감',ARRAY['[6과11-02] 식물의 각 기관의 구조를 관찰하고, 기능을 알아보는 실험을 수행하여 식물 각 기관의 구조와 기능을 설명할 수 있다.']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u3-C25','sci',6,1,'u3',7,'꽃 관찰의 안전과 씨앗도서관 — 꽃가루 앨러지가 있으면 보안경과 마스크를 씀 · 꽃을 맛보지 않음 · 생명을 소중히 여기는 마음으로 관찰 · 씨앗도서관은 책처럼 씨를 빌려주는 곳으로, 빌린 씨로 식물을 길러 씨를 거두어 돌려주고, 기르며 관찰 일지를 쓸 수 있으며, 여러 씨를 보관·전시하고 토종 씨를 지킴',ARRAY['[6과11-02] 식물의 각 기관의 구조를 관찰하고, 기능을 알아보는 실험을 수행하여 식물 각 기관의 구조와 기능을 설명할 수 있다.']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u3-C26','sci',6,1,'u3',8,'식물의 각 기관이 하는 일 — 뿌리는 물을 흡수(지지·양분 저장) · 줄기는 물과 양분이 이동하는 통로(지지) · 잎은 광합성으로 양분을 만들고 증산 작용으로 물을 식물 밖으로 내보냄 · 꽃에서는 꽃가루받이가 이루어지고 씨를 만듦 · 열매는 씨를 보호하고 멀리 퍼뜨림',ARRAY['[6과11-02] 식물의 각 기관의 구조를 관찰하고, 기능을 알아보는 실험을 수행하여 식물 각 기관의 구조와 기능을 설명할 수 있다.']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u3-C27','sci',6,1,'u3',8,'식물에서 물의 이동 — 뿌리에서 흡수한 물은 줄기를 통해 식물 전체로 이동해 생명활동에 쓰임 · 잎에 도달한 물의 일부는 기공을 통해 식물 밖으로 빠져나감 · 물은 뿌리에서 출발함',ARRAY['[6과11-02] 식물의 각 기관의 구조를 관찰하고, 기능을 알아보는 실험을 수행하여 식물 각 기관의 구조와 기능을 설명할 수 있다.']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u3-C28','sci',6,1,'u3',8,'식물에서 양분의 이동 — 잎에서 광합성으로 만든 양분은 줄기를 통해 식물 전체로 이동해 생명활동에 쓰임 · 쓰고 남은 양분은 뿌리·줄기·열매 등에 저장됨 · 양분은 잎에서 출발함',ARRAY['[6과11-02] 식물의 각 기관의 구조를 관찰하고, 기능을 알아보는 실험을 수행하여 식물 각 기관의 구조와 기능을 설명할 수 있다.']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u3-C29','sci',6,1,'u3',8,'각 기관의 연결성 — 식물의 각 기관은 생김새와 하는 일이 서로 다르지만 밀접한 영향을 주고받으며 연결되어 있음 · 시계의 톱니바퀴 하나가 빠지면 시계가 멈추듯 한 기관에 문제가 생기면 식물 전체의 생명활동에 문제가 생길 수 있음 · 물과 양분 이동 놀이는 승부보다 이동 경로와 기관의 연결을 생각하며 함',ARRAY['[6과11-02] 식물의 각 기관의 구조를 관찰하고, 기능을 알아보는 실험을 수행하여 식물 각 기관의 구조와 기능을 설명할 수 있다.']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u3-C30','sci',6,1,'u3',9,'우리 반 식물도감 — 알아보고 싶은 식물을 이야기해 ㄱㄴㄷ 순으로 정리 → 친구와 의논해 서로 다른 식물을 하나씩 정함 → 뿌리·줄기·잎·꽃 등 구조와 기능의 특징을 조사(다른 식물과 견주어 특이한 점) → 사진이나 그림을 넣어 소개 자료를 만듦 → 공유 플랫폼에 올려 식물도감을 완성 → 소개하고 새로 알게 된 점 나누기 · 예: 토끼풀은 줄기가 땅 위를 기듯이 자라고 잎이 세 갈래, 여러 송이 꽃이 모여 한 송이처럼 보임 · 애기똥풀은 줄기나 잎을 자르면 노란 즙',ARRAY['[6과11-03] 여러 가지 식물의 특징을 설명하는 자료를 만들어 공유할 수 있다.']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u3-C31','sci',6,1,'u3',9,'조사하고 공유하는 태도 — 스마트 기기로 조사할 때 올바른 정보인지 확인하고 출처를 반드시 밝힘 · 수업과 관련 있는 자료만 찾고 유해한 누리집에 들어가지 않음 · 스마트 기기에서 냄새가 나거나 열이 나면 바로 사용을 멈추고 선생님께 알림 · 친구의 발표는 바른 자세로 들음',ARRAY['[6과11-03] 여러 가지 식물의 특징을 설명하는 자료를 만들어 공유할 수 있다.']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u3-C32','sci',6,1,'u3',9,'꽃가루의 특징과 쓰임 — 꽃가루는 크기가 매우 작고 식물의 종류에 따라 모양이 모두 다르며 모양이 잘 변하지 않고 안정적임 · 해바라기 꽃가루로 3D 프린터 잉크 재료를 만드는 기술(구하기 쉽고 독성이 없어 의료용으로도) · 사건 증거품에서 찾은 꽃가루로 현장이나 범인을 찾음 · 오래된 땅속 꽃가루로 그때 자란 식물과 기후를 알아냄 · 꽃가루를 앨러지를 일으키는 것으로만 여기지 않음',ARRAY['[6과11-03] 여러 가지 식물의 특징을 설명하는 자료를 만들어 공유할 수 있다.']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-1-u3-C33','sci',6,1,'u3',9,'식물의 구조와 기능 정리 — 생물을 이루는 기본 단위는 세포 · 뿌리(흡수·지지·저장)·줄기(통로·지지·저장)·잎(광합성·증산 작용)·꽃(꽃가루받이·씨) · 기관은 서로 연결 · 여러 가지 식물은 서로 다른 특징이 있지만 뿌리·줄기·잎·꽃 등의 기관으로 이루어진 점은 비슷함 · 식물을 소중히 여기는 마음',ARRAY['[6과11-03] 여러 가지 식물의 특징을 설명하는 자료를 만들어 공유할 수 있다.']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X01','sci',6,'u3',ARRAY['SC6-1-u3-C1']::text[],'다섯 고개 질문을 생김새나 구조가 아닌 것(값, 맛, 좋아하는 사람)으로 한다','생김새·구조만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X02','sci',6,'u3',ARRAY['SC6-1-u3-C1']::text[],'다섯 고개 놀이의 차례를 뒤섞는다(사진 전체를 보여 주거나 이름부터 알려 줌)','일부분만 보여 줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X03','sci',6,'u3',ARRAY['SC6-1-u3-C2']::text[],'식물은 뿌리·줄기·잎·꽃의 생김새가 모두 같다고 여긴다','모양이 매우 다양해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X04','sci',6,'u3',ARRAY['SC6-1-u3-C3']::text[],'앨러지가 있어도 식물을 만지거나, 나무에 오르거나, 식물을 꺾는다','안전하게 · 훼손하지 않게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X05','sci',6,'u3',ARRAY['SC6-1-u3-C3']::text[],'애플리케이션 결과를 확인 없이 믿거나 수업과 상관없는 자료를 연다','도감으로 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X06','sci',6,'u3',ARRAY['SC6-1-u3-C4']::text[],'생물마다 기본 단위가 다르다거나 생물 전체의 모양이 세포 모양과 같다고 여긴다','모두 세포 · 첨성대와 돌') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X07','sci',6,'u3',ARRAY['SC6-1-u3-C4']::text[],'한 생물을 이루는 세포는 크기와 모양이 모두 같다고 여긴다','종류에 따라 다양') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X08','sci',6,'u3',ARRAY['SC6-1-u3-C5']::text[],'세포막·핵·세포벽의 자리를 바꾸어 안다(세포벽이 안쪽, 핵이 바깥)','핵 → 세포막 → 세포벽') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X09','sci',6,'u3',ARRAY['SC6-1-u3-C5']::text[],'식물 세포에는 세포막이 없거나 핵이 없다고 여긴다','세포막도 핵도 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X10','sci',6,'u3',ARRAY['SC6-1-u3-C6']::text[],'모든 세포는 맨눈으로 볼 수 없다고 여긴다','달걀은 하나의 세포') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X11','sci',6,'u3',ARRAY['SC6-1-u3-C6']::text[],'대부분의 세포가 커서 맨눈으로 잘 보인다고 여긴다','대부분은 현미경으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X12','sci',6,'u3',ARRAY['SC6-1-u3-C7']::text[],'표본을 두껍게 만들거나 매니큐어가 마르기 전에 테이프를 붙여도 된다고 여긴다','얇게 · 완전히 마른 뒤') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X13','sci',6,'u3',ARRAY['SC6-1-u3-C7']::text[],'매니큐어 냄새를 맡거나 받침 유리·표본을 함부로 다룬다','환기 · 조심') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X14','sci',6,'u3',ARRAY['SC6-1-u3-C8']::text[],'모든 식물의 뿌리 생김새가 같다고 여긴다','수염처럼 · 굵고 곧은') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X15','sci',6,'u3',ARRAY['SC6-1-u3-C8']::text[],'뿌리털은 하는 일이 없거나 양분을 만든다고 여긴다','물을 잘 흡수하게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X16','sci',6,'u3',ARRAY['SC6-1-u3-C9']::text[],'뿌리를 자른 파 쪽 물이 더 많이 줄거나 두 쪽이 똑같이 준다고 여긴다','뿌리가 있는 쪽') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X17','sci',6,'u3',ARRAY['SC6-1-u3-C9']::text[],'다르게 할 조건과 같게 할 조건을 뒤섞는다','뿌리만 다르게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X18','sci',6,'u3',ARRAY['SC6-1-u3-C9']::text[],'예상과 다른 결과를 예상에 맞추어 바꾸어 기록한다','있는 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X19','sci',6,'u3',ARRAY['SC6-1-u3-C10']::text[],'뿌리가 양분을 만든다고 여긴다','양분은 잎에서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X20','sci',6,'u3',ARRAY['SC6-1-u3-C10']::text[],'뿌리에는 양분을 저장할 수 없다거나 당근을 줄기로 여긴다','당근·고구마는 뿌리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X21','sci',6,'u3',ARRAY['SC6-1-u3-C10']::text[],'뿌리가 식물을 지지하는 일을 놓친다','쓰러지지 않게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X22','sci',6,'u3',ARRAY['SC6-1-u3-C12']::text[],'줄기가 물을 흡수한다고 여긴다','흡수는 뿌리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X23','sci',6,'u3',ARRAY['SC6-1-u3-C11']::text[],'붉게 물든 부분을 양분이 저장된 곳이나 원래 붉은 곳으로 여긴다','물이 이동한 통로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X24','sci',6,'u3',ARRAY['SC6-1-u3-C11']::text[],'색소 물이 줄기에만 머물고 잎과 꽃까지는 가지 않는다고 여긴다','잎과 꽃도 붉게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X25','sci',6,'u3',ARRAY['SC6-1-u3-C13']::text[],'고구마가 뿌리이니 감자도 뿌리라고 여긴다','감자는 줄기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X26','sci',6,'u3',ARRAY['SC6-1-u3-C13']::text[],'모든 줄기는 곧게 서 있다고 여긴다','감고 · 기고') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X27','sci',6,'u3',ARRAY['SC6-1-u3-C12']::text[],'줄기가 양분을 만든다고 여긴다','줄기는 통로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X28','sci',6,'u3',ARRAY['SC6-1-u3-C14']::text[],'잎몸·잎자루·잎맥의 자리를 바꾸어 안다','잎몸에 잎맥') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X29','sci',6,'u3',ARRAY['SC6-1-u3-C15']::text[],'광합성은 식물의 잎에서만 일어난다고 여긴다','주로 잎 · 초록색 부분') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X30','sci',6,'u3',ARRAY['SC6-1-u3-C15']::text[],'광합성에 빛이 필요 없다거나 재료와 만드는 것을 바꾸어 안다(물을 만든다, 산소로 만든다)','빛 · 이산화 탄소와 물 → 양분') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X31','sci',6,'u3',ARRAY['SC6-1-u3-C16']::text[],'포일을 씌운 잎에서 색이 변한다고 여기거나 결과를 거꾸로 읽는다','햇빛 받은 잎이 청람색') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X32','sci',6,'u3',ARRAY['SC6-1-u3-C16']::text[],'알루미늄 포일을 씌우는 까닭(빛을 다르게 함)을 모른다','빛을 막아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X33','sci',6,'u3',ARRAY['SC6-1-u3-C16']::text[],'에탄올이나 뜨거운 물을 함부로 다룬다','환기 · 화상 조심') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X34','sci',6,'u3',ARRAY['SC6-1-u3-C15']::text[],'식물은 햇빛을 무조건 많이 받을수록 좋다고 여긴다','식물마다 알맞게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X35','sci',6,'u3',ARRAY['SC6-1-u3-C17']::text[],'잎에서 만든 양분은 잎에서만 쓰인다고 여긴다','줄기 타고 식물 전체로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X36','sci',6,'u3',ARRAY['SC6-1-u3-C17']::text[],'잎이 납작하고 넓은 것이 하는 일과 상관없다고 여긴다','빛을 넓게 받아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X37','sci',6,'u3',ARRAY['SC6-1-u3-C18']::text[],'증산 작용으로 공기 중의 수증기가 식물 안으로 들어오거나 기공으로 물을 흡수한다고 여긴다','밖으로 빠져나가요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X38','sci',6,'u3',ARRAY['SC6-1-u3-C20']::text[],'증산 작용이 주로 줄기나 잎 앞면에서 일어난다고 여긴다','기공은 대부분 뒷면') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X39','sci',6,'u3',ARRAY['SC6-1-u3-C19']::text[],'페트리 접시의 종이가 붉어진다고 여기거나 견주려고 붙인 종이의 쓰임을 모른다','견주기용 종이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X40','sci',6,'u3',ARRAY['SC6-1-u3-C21']::text[],'증발과 증산 작용은 전혀 다른 현상이라고 여긴다','물이 수증기로 · 잎에서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X41','sci',6,'u3',ARRAY['SC6-1-u3-C21']::text[],'증산 작용은 쓸모없이 물을 버리는 일이라 여기거나 사막 식물은 잎이 넓어야 유리하다고 여긴다','물을 끌어올리고 온도 조절') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X42','sci',6,'u3',ARRAY['SC6-1-u3-C22']::text[],'모든 꽃이 암술·수술·꽃잎·꽃받침을 다 가진다고 여긴다','일부가 없는 꽃도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X43','sci',6,'u3',ARRAY['SC6-1-u3-C22']::text[],'암술과 수술, 꽃잎과 꽃받침의 자리를 바꾸어 안다','가운데 암술 · 아래 꽃받침') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X44','sci',6,'u3',ARRAY['SC6-1-u3-C23']::text[],'꽃가루받이의 방향이나 차례를 바꾸어 안다(암술 → 수술, 열매가 먼저)','수술 → 암술 → 씨') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X45','sci',6,'u3',ARRAY['SC6-1-u3-C23']::text[],'꽃이 양분을 만든다거나 꽃이 화려한 까닭이 양분 때문이라고 여긴다','씨를 만들어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X46','sci',6,'u3',ARRAY['SC6-1-u3-C24']::text[],'열매가 씨를 만든다거나 열매는 하는 일이 없다고 여긴다','보호하고 퍼뜨려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X47','sci',6,'u3',ARRAY['SC6-1-u3-C25']::text[],'꽃을 맛보거나 꺾는 등 생명을 함부로 다루고 빌린 씨를 돌려주지 않는다','소중히 · 돌려주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X48','sci',6,'u3',ARRAY['SC6-1-u3-C29']::text[],'식물의 각 기관은 따로따로 일하며 서로 상관없다고 여긴다','톱니바퀴처럼 연결') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X49','sci',6,'u3',ARRAY['SC6-1-u3-C27','SC6-1-u3-C28']::text[],'물과 양분의 출발점을 바꾸어 안다(물은 잎에서, 양분은 뿌리에서)','물은 뿌리 · 양분은 잎') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X50','sci',6,'u3',ARRAY['SC6-1-u3-C28']::text[],'쓰고 남은 양분은 저장되지 않고 모두 버려진다고 여긴다','뿌리·줄기·열매에 저장') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X51','sci',6,'u3',ARRAY['SC6-1-u3-C29']::text[],'이동 놀이에서 경로는 생각하지 않고 이기는 데만 매달린다','경로를 따라가요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X52','sci',6,'u3',ARRAY['SC6-1-u3-C30']::text[],'식물도감에 생김새 사진만 넣고 구조와 기능을 빼거나 모두 같은 식물을 조사한다','구조와 기능 · 서로 다른 식물') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X53','sci',6,'u3',ARRAY['SC6-1-u3-C31']::text[],'조사한 자료를 확인 없이, 출처 없이 옮긴다','확인 · 출처') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X54','sci',6,'u3',ARRAY['SC6-1-u3-C32']::text[],'꽃가루는 앨러지만 일으키는 쓸모없는 것이라고 여긴다','쓰임이 많아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X55','sci',6,'u3',ARRAY['SC6-1-u3-C32']::text[],'꽃가루는 크고 모양이 모두 같거나 쉽게 변한다고 여긴다','작고 다르고 안정적') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-1-u3-X56','sci',6,'u3',ARRAY['SC6-1-u3-C33']::text[],'식물마다 특징이 다르니 기관도 전혀 다르다고 여긴다','뿌리·줄기·잎·꽃은 같이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L01_basic#1','sci',6,1,'u3','L01','g6_1_sci_u3_L01_basic','lesson_basic','SC6-1-u3-C2',1,'mc','auto','우리 주변의 식물은 대개 무엇으로 이루어져 있나요?',ARRAY['SC6-1-u3-X03']::text[],false,'{"seq":1,"concept":"SC6-1-u3-C2","difficulty":1,"kind":"mc","stem":"우리 주변의 식물은 대개 무엇으로 이루어져 있나요?","options":[{"t":"뿌리, 줄기, 잎, 꽃 등","correct":true},{"t":"흙, 물, 햇빛 등","mis":"SC6-1-u3-X03"},{"t":"돌, 모래, 바람 등","mis":"SC6-1-u3-X03"},{"t":"사진, 이름표, 화분 등","mis":"SC6-1-u3-X03"}],"explanation":["식물을 떠올려요.","뿌리·줄기·잎·꽃이 있어요.","식물은 이것들로 이루어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L01_basic#2','sci',6,1,'u3','L01','g6_1_sci_u3_L01_basic','lesson_basic','SC6-1-u3-C1',1,'ox','auto','다섯 고개 놀이에서는 식물의 생김새나 구조에 관한 질문만 할 수 있어요.',ARRAY['SC6-1-u3-X01']::text[],false,'{"seq":2,"concept":"SC6-1-u3-C1","difficulty":1,"kind":"ox","stem":"다섯 고개 놀이에서는 식물의 생김새나 구조에 관한 질문만 할 수 있어요.","answer":"O","reason_options":[{"t":"질문을 식물의 생김새나 구조에 관한 것으로 정해 두었기 때문에","correct":true},{"t":"어떤 질문이든 마음대로 해도 되기 때문에","mis":"SC6-1-u3-X01"}],"mis":"SC6-1-u3-X01","explanation":["질문에 약속이 있어요.","생김새나 구조만 물어요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L01_basic#3','sci',6,1,'u3','L01','g6_1_sci_u3_L01_basic','lesson_basic','SC6-1-u3-C3',1,'mc','auto','식물에 앨러지가 있는 친구가 식물을 살펴볼 때 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X04']::text[],false,'{"seq":3,"concept":"SC6-1-u3-C3","difficulty":1,"kind":"mc","stem":"식물에 앨러지가 있는 친구가 식물을 살펴볼 때 알맞은 것은 어느 것인가요?","options":[{"t":"식물을 직접 만지지 않고 눈으로 살펴본다","correct":true},{"t":"잎을 따서 냄새를 맡아 본다","mis":"SC6-1-u3-X04"},{"t":"꽃을 꺾어 교실로 가져간다","mis":"SC6-1-u3-X04"},{"t":"나무에 올라가 가까이 본다","mis":"SC6-1-u3-X04"}],"explanation":["앨러지가 있어요.","직접 만지지 않아요.","눈으로 살펴봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L01_basic#4','sci',6,1,'u3','L01','g6_1_sci_u3_L01_basic','lesson_basic','SC6-1-u3-C2',1,'sa','auto','식물에서 주로 땅속에 있어 사진에 잘 보이지 않는 부분의 이름을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC6-1-u3-C2","difficulty":1,"kind":"sa","stem":"식물에서 주로 땅속에 있어 사진에 잘 보이지 않는 부분의 이름을 두 글자로 쓰세요.","answer":["뿌리"],"explanation":["땅속에 있어요.","두 글자예요.","뿌리예요."],"mis":"SC6-1-u3-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L01_basic#5','sci',6,1,'u3','L01','g6_1_sci_u3_L01_basic','lesson_basic','SC6-1-u3-C1',2,'mc','auto','다섯 고개 놀이에서 다른 모둠에게 식물 사진을 보여 주는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X02','SC6-1-u3-X04']::text[],false,'{"seq":5,"concept":"SC6-1-u3-C1","difficulty":2,"kind":"mc","stem":"다섯 고개 놀이에서 다른 모둠에게 식물 사진을 보여 주는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"사진의 일부분만 보여 준다","correct":true},{"t":"사진 전체와 식물 이름을 함께 보여 준다","mis":"SC6-1-u3-X02"},{"t":"사진은 보여 주지 않고 이름만 알려 준다","mis":"SC6-1-u3-X02"},{"t":"식물을 뽑아서 통째로 보여 준다","mis":"SC6-1-u3-X04"}],"explanation":["맞혀야 하는 놀이예요.","일부분만 보여 줘요.","그래서 질문이 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L01_basic#6','sci',6,1,'u3','L01','g6_1_sci_u3_L01_basic','lesson_basic','SC6-1-u3-C1',2,'mc','auto','다섯 고개 질문으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X01']::text[],false,'{"seq":6,"concept":"SC6-1-u3-C1","difficulty":2,"kind":"mc","stem":"다섯 고개 질문으로 알맞은 것은 어느 것인가요?","options":[{"t":"「잎은 어떤 모양인가요?」","correct":true},{"t":"「이 식물은 얼마에 살 수 있나요?」","mis":"SC6-1-u3-X01"},{"t":"「이 식물을 누가 좋아하나요?」","mis":"SC6-1-u3-X01"},{"t":"「이 식물은 무슨 맛인가요?」","mis":"SC6-1-u3-X01"}],"explanation":["생김새를 물어요.","잎 모양은 생김새예요.","값·맛은 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L01_basic#7','sci',6,1,'u3','L01','g6_1_sci_u3_L01_basic','lesson_basic','SC6-1-u3-C2',2,'mc','auto','우리 학교 식물 관찰 기록에서 소나무에 대해 알 수 있는 것은 어느 것인가요?',ARRAY['SC6-1-u3-X03']::text[],false,'{"seq":7,"concept":"SC6-1-u3-C2","difficulty":2,"kind":"mc","stem":"우리 학교 식물 관찰 기록에서 소나무에 대해 알 수 있는 것은 어느 것인가요?","options":[{"t":"줄기가 적갈색이고 바늘 모양 잎이 두 개씩 모여 달린다","correct":true},{"t":"꽃이 노란색이고 꽃잎이 다섯 장이다","mis":"SC6-1-u3-X03"},{"t":"뿌리가 땅 위로 드러나 잘 보인다","mis":"SC6-1-u3-X03"},{"t":"모든 식물과 생김새가 똑같다","mis":"SC6-1-u3-X03"}],"explanation":["소나무 줄을 봐요.","적갈색 줄기예요.","바늘 모양 잎이 두 개씩이에요."],"asset":{"type":"passage","lines":["정문 옆 소나무 — 줄기는 적갈색, 바늘 모양 잎이 두 개씩 모여 달림","화단의 애기똥풀 — 꽃이 노란색","울타리의 무궁화 — 꽃잎이 다섯 장","화단의 민들레 — 뿌리는 땅속에 있어 보이지 않음"],"title":"우리 학교 식물 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L01_basic#8','sci',6,1,'u3','L01','g6_1_sci_u3_L01_basic','lesson_basic','SC6-1-u3-C3',2,'mc','auto','식물 이름 찾기 애플리케이션으로 이름을 알아낸 뒤 할 일로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X05','SC6-1-u3-X04']::text[],false,'{"seq":8,"concept":"SC6-1-u3-C3","difficulty":2,"kind":"mc","stem":"식물 이름 찾기 애플리케이션으로 이름을 알아낸 뒤 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"식물도감으로 정확한 정보인지 확인한다","correct":true},{"t":"애플리케이션 결과는 늘 맞으니 그대로 적는다","mis":"SC6-1-u3-X05"},{"t":"수업과 상관없는 동영상을 찾아본다","mis":"SC6-1-u3-X05"},{"t":"식물을 뽑아 들고 다시 찍는다","mis":"SC6-1-u3-X04"}],"explanation":["결과가 틀릴 수도 있어요.","도감으로 확인해요.","정확한 정보를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L01_basic#9','sci',6,1,'u3','L01','g6_1_sci_u3_L01_basic','lesson_basic','SC6-1-u3-C2',2,'ox','auto','식물은 종류가 달라도 잎과 꽃의 생김새가 모두 같아요.',ARRAY['SC6-1-u3-X03']::text[],false,'{"seq":9,"concept":"SC6-1-u3-C2","difficulty":2,"kind":"ox","stem":"식물은 종류가 달라도 잎과 꽃의 생김새가 모두 같아요.","answer":"X","reason_options":[{"t":"식물마다 줄기·잎·꽃의 모양이 매우 다양하기 때문에","correct":true},{"t":"식물은 모두 같은 모양으로 자라기 때문에","mis":"SC6-1-u3-X03"}],"mis":"SC6-1-u3-X03","explanation":["여러 식물을 떠올려요.","모양이 서로 달라요.","틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L01_basic#10','sci',6,1,'u3','L01','g6_1_sci_u3_L01_basic','lesson_basic','SC6-1-u3-C3',3,'error','auto','화단에서 식물을 살펴보며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u3-X04']::text[],false,'{"seq":10,"concept":"SC6-1-u3-C3","difficulty":3,"kind":"error","stem":"화단에서 식물을 살펴보며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준혁 — 「더 잘 보려면 나무 위로 올라가서 살펴보자.」","correct":true,"mis_target":"SC6-1-u3-X04"},{"t":"아린 — 「식물이 다치지 않게 잎을 함부로 따지 말자.」","mis":"SC6-1-u3-X04"},{"t":"태민 — 「가시에 얼굴이 긁히지 않게 조심하자.」","mis":"SC6-1-u3-X04"}],"explanation":["위험한 곳은 안 돼요.","나무에 오르지 않아요.","준혁의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L01_challenge#1','sci',6,1,'u3','L01','g6_1_sci_u3_L01_challenge','lesson_challenge','SC6-1-u3-C2',2,'match','auto','우리 학교 식물 관찰 기록에서 식물과 특징을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC6-1-u3-C2","difficulty":2,"kind":"match","stem":"우리 학교 식물 관찰 기록에서 식물과 특징을 알맞게 이으세요.","pairs":[{"l":"소나무","r":"바늘 모양 잎이 두 개씩 모여 달림"},{"l":"애기똥풀","r":"꽃이 노란색"},{"l":"무궁화","r":"꽃잎이 다섯 장"}],"mis":"SC6-1-u3-X03","explanation":["기록을 봐요.","식물마다 특징이 달라요.","하나씩 이어요."],"asset":{"type":"passage","lines":["정문 옆 소나무 — 줄기는 적갈색, 바늘 모양 잎이 두 개씩 모여 달림","화단의 애기똥풀 — 꽃이 노란색","울타리의 무궁화 — 꽃잎이 다섯 장","화단의 민들레 — 뿌리는 땅속에 있어 보이지 않음"],"title":"우리 학교 식물 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L01_challenge#2','sci',6,1,'u3','L01','g6_1_sci_u3_L01_challenge','lesson_challenge','SC6-1-u3-C1',2,'mc','auto','다섯 고개 놀이에서 질문을 다섯 번 하는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X01','SC6-1-u3-X02']::text[],false,'{"seq":2,"concept":"SC6-1-u3-C1","difficulty":2,"kind":"mc","stem":"다섯 고개 놀이에서 질문을 다섯 번 하는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"식물의 생김새와 구조를 하나씩 좁혀 가며 이름을 알아내려고","correct":true},{"t":"식물의 값을 알아내려고","mis":"SC6-1-u3-X01"},{"t":"사진 전체를 보여 달라고 하려고","mis":"SC6-1-u3-X02"},{"t":"질문 수와 상관없이 처음부터 이름을 말하려고","mis":"SC6-1-u3-X02"}],"explanation":["일부분만 보여요.","질문으로 좁혀 가요.","그래서 다섯 번 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L01_challenge#3','sci',6,1,'u3','L01','g6_1_sci_u3_L01_challenge','lesson_challenge','SC6-1-u3-C1',3,'mc','auto','다섯 고개 놀이 메모의 ㉠~㉤을 바른 차례로 늘어놓은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X02']::text[],false,'{"seq":3,"concept":"SC6-1-u3-C1","difficulty":3,"kind":"mc","stem":"다섯 고개 놀이 메모의 ㉠~㉤을 바른 차례로 늘어놓은 것은 어느 것인가요?","options":[{"t":"㉡ → ㉣ → ㉤ → ㉢ → ㉠","correct":true},{"t":"㉤ → ㉡ → ㉣ → ㉠ → ㉢","mis":"SC6-1-u3-X02"},{"t":"㉡ → ㉢ → ㉤ → ㉣ → ㉠","mis":"SC6-1-u3-X02"},{"t":"㉣ → ㉡ → ㉠ → ㉤ → ㉢","mis":"SC6-1-u3-X02"}],"explanation":["먼저 화단을 살펴요.","이름 확인 뒤 사진을 찍어요.","일부분을 보여 주고 맞혀요."],"asset":{"type":"passage","lines":["㉠ 다른 모둠은 다섯 가지 질문을 한 뒤 식물 이름을 맞힌다.","㉡ 화단의 한 구역을 정해 식물을 살펴본다.","㉢ 다른 모둠에게 식물 사진의 일부분을 보여 준다.","㉣ 스마트 기기나 식물도감으로 식물 이름을 확인한다.","㉤ 모둠원과 문제로 낼 식물을 정해 사진을 찍는다."],"title":"다섯 고개 놀이 메모(차례가 섞임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L01_challenge#4','sci',6,1,'u3','L01','g6_1_sci_u3_L01_challenge','lesson_challenge','SC6-1-u3-C1',3,'mc','auto','우리 모둠이 준비한 다섯 고개 질문 가운데 바꾸어야 할 것은 어느 것인가요?',ARRAY['SC6-1-u3-X01']::text[],false,'{"seq":4,"concept":"SC6-1-u3-C1","difficulty":3,"kind":"mc","stem":"우리 모둠이 준비한 다섯 고개 질문 가운데 바꾸어야 할 것은 어느 것인가요?","options":[{"t":"③","correct":true},{"t":"①","mis":"SC6-1-u3-X01"},{"t":"②","mis":"SC6-1-u3-X01"},{"t":"⑤","mis":"SC6-1-u3-X01"}],"explanation":["생김새를 묻나요?","③은 값을 물어요.","③을 바꿔야 해요."],"asset":{"type":"passage","lines":["① 나보다 키가 큰 식물인가요?","② 꽃잎이 몇 장인가요?","③ 이 식물은 얼마에 살 수 있나요?","④ 잎은 어떤 모양인가요?","⑤ 줄기에 가시가 있나요?"],"title":"우리 모둠이 준비한 다섯 고개 질문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L01_challenge#5','sci',6,1,'u3','L01','g6_1_sci_u3_L01_challenge','lesson_challenge','SC6-1-u3-C1',3,'mc','auto','우리 모둠이 준비한 다섯 고개 질문의 ③을 바꾼 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X01','SC6-1-u3-X02']::text[],false,'{"seq":5,"concept":"SC6-1-u3-C1","difficulty":3,"kind":"mc","stem":"우리 모둠이 준비한 다섯 고개 질문의 ③을 바꾼 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「열매의 크기는 어느 정도인가요?」","correct":true},{"t":"「이 식물은 어디에서 팔까요?」","mis":"SC6-1-u3-X01"},{"t":"「이 식물로 무엇을 요리하나요?」","mis":"SC6-1-u3-X01"},{"t":"「이 식물 이름은 무엇인가요?」","mis":"SC6-1-u3-X02"}],"explanation":["생김새로 바꿔요.","열매 크기는 생김새예요.","알맞게 바꿨어요."],"asset":{"type":"passage","lines":["① 나보다 키가 큰 식물인가요?","② 꽃잎이 몇 장인가요?","③ 이 식물은 얼마에 살 수 있나요?","④ 잎은 어떤 모양인가요?","⑤ 줄기에 가시가 있나요?"],"title":"우리 모둠이 준비한 다섯 고개 질문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L01_challenge#6','sci',6,1,'u3','L01','g6_1_sci_u3_L01_challenge','lesson_challenge','SC6-1-u3-C3',3,'error','auto','식물 이름을 알아보는 과정을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u3-X05']::text[],false,'{"seq":6,"concept":"SC6-1-u3-C3","difficulty":3,"kind":"error","stem":"식물 이름을 알아보는 과정을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민서 — 「애플리케이션이 알려 줬으니 도감은 안 봐도 돼.」","correct":true,"mis_target":"SC6-1-u3-X05"},{"t":"지호 — 「비슷한 특징이 있는 식물을 도감에서 찾아 확인하자.」","mis":"SC6-1-u3-X05"},{"t":"하율 — 「수업과 관련 없는 누리집은 열지 말자.」","mis":"SC6-1-u3-X05"}],"explanation":["확인이 필요해요.","도감과 견줘요.","민서의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L01_challenge#7','sci',6,1,'u3','L01','g6_1_sci_u3_L01_challenge','lesson_challenge','SC6-1-u3-C3',3,'ox','auto','꽃가루 앨러지가 있는 친구는 식물을 살펴볼 때 마스크를 쓰는 것이 좋아요.',ARRAY['SC6-1-u3-X04']::text[],false,'{"seq":7,"concept":"SC6-1-u3-C3","difficulty":3,"kind":"ox","stem":"꽃가루 앨러지가 있는 친구는 식물을 살펴볼 때 마스크를 쓰는 것이 좋아요.","answer":"O","reason_options":[{"t":"꽃가루 때문에 몸에 이상이 생기는 것을 막을 수 있기 때문에","correct":true},{"t":"마스크를 쓰면 식물 이름을 더 빨리 맞힐 수 있기 때문에","mis":"SC6-1-u3-X04"}],"mis":"SC6-1-u3-X04","explanation":["앨러지가 있어요.","꽃가루를 막아요.","마스크를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L01_challenge#8','sci',6,1,'u3','L01','g6_1_sci_u3_L01_challenge','lesson_challenge','SC6-1-u3-C2',4,'mc','auto','우리 학교 식물 관찰 기록에서 민들레만 다섯 고개 질문을 「뿌리」로 만들기 어려운 까닭은 무엇인가요?',ARRAY['SC6-1-u3-X03','SC6-1-u3-X01']::text[],false,'{"seq":8,"concept":"SC6-1-u3-C2","difficulty":4,"kind":"mc","stem":"우리 학교 식물 관찰 기록에서 민들레만 다섯 고개 질문을 「뿌리」로 만들기 어려운 까닭은 무엇인가요?","options":[{"t":"뿌리가 땅속에 있어 사진에 보이지 않기 때문이다","correct":true},{"t":"민들레는 뿌리가 없는 식물이기 때문이다","mis":"SC6-1-u3-X03"},{"t":"뿌리는 모든 식물이 똑같이 생겼기 때문이다","mis":"SC6-1-u3-X03"},{"t":"뿌리에 관한 질문은 생김새가 아니기 때문이다","mis":"SC6-1-u3-X01"}],"explanation":["뿌리는 어디 있나요?","땅속이라 안 보여요.","사진으로 묻기 어려워요."],"asset":{"type":"passage","lines":["정문 옆 소나무 — 줄기는 적갈색, 바늘 모양 잎이 두 개씩 모여 달림","화단의 애기똥풀 — 꽃이 노란색","울타리의 무궁화 — 꽃잎이 다섯 장","화단의 민들레 — 뿌리는 땅속에 있어 보이지 않음"],"title":"우리 학교 식물 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L01_challenge#9','sci',6,1,'u3','L01','g6_1_sci_u3_L01_challenge','lesson_challenge','SC6-1-u3-C3',4,'mc','auto','모둠이 문제로 낼 식물 사진을 찍으려고 해요. 가장 알맞은 행동은 어느 것인가요?',ARRAY['SC6-1-u3-X04']::text[],false,'{"seq":9,"concept":"SC6-1-u3-C3","difficulty":4,"kind":"mc","stem":"모둠이 문제로 낼 식물 사진을 찍으려고 해요. 가장 알맞은 행동은 어느 것인가요?","options":[{"t":"식물을 그대로 둔 채 줄기·잎·꽃이 보이게 찍는다","correct":true},{"t":"잘 보이게 꽃과 잎을 따서 책상에 모아 찍는다","mis":"SC6-1-u3-X04"},{"t":"높이 있는 꽃을 찍으려고 울타리에 올라간다","mis":"SC6-1-u3-X04"},{"t":"식물을 뽑아 뿌리까지 찍어 다시 버려 둔다","mis":"SC6-1-u3-X04"}],"explanation":["식물을 아껴요.","그대로 둔 채 찍어요.","안전하게 찍어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L01_challenge#10','sci',6,1,'u3','L01','g6_1_sci_u3_L01_challenge','lesson_challenge','SC6-1-u3-C1',4,'essay','teacher','다섯 고개 놀이를 할 때 지켜야 할 질문 약속을 쓰고, 그 약속에 맞는 질문을 두 가지 만들어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-1-u3-C1","difficulty":4,"kind":"essay","stem":"다섯 고개 놀이를 할 때 지켜야 할 질문 약속을 쓰고, 그 약속에 맞는 질문을 두 가지 만들어 쓰세요.","answer_guide":{"answer":"예: 질문은 식물의 생김새나 구조에 관한 것만 한다. 「줄기에 가시가 있나요?」 「꽃잎이 몇 장인가요?」","scoring_points":["생김새나 구조에 관한 질문만 한다고 썼는가","약속에 맞는 질문 두 가지를 썼는가"]},"explanation":["약속을 떠올려요.","생김새를 물어요.","두 가지를 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L02_basic#1','sci',6,1,'u3','L02','g6_1_sci_u3_L02_basic','lesson_basic','SC6-1-u3-C4',1,'sa','auto','생물을 이루는 기본 단위를 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC6-1-u3-C4","difficulty":1,"kind":"sa","stem":"생물을 이루는 기본 단위를 두 글자로 쓰세요.","answer":["세포"],"explanation":["생물을 이루는 단위예요.","두 글자예요.","세포예요."],"mis":"SC6-1-u3-X06"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L02_basic#2','sci',6,1,'u3','L02','g6_1_sci_u3_L02_basic','lesson_basic','SC6-1-u3-C5',1,'mc','auto','식물 세포에서 세포막의 바깥쪽을 둘러싸고 있는 것은 어느 것인가요?',ARRAY['SC6-1-u3-X08','SC6-1-u3-X09']::text[],false,'{"seq":2,"concept":"SC6-1-u3-C5","difficulty":1,"kind":"mc","stem":"식물 세포에서 세포막의 바깥쪽을 둘러싸고 있는 것은 어느 것인가요?","options":[{"t":"세포벽","correct":true},{"t":"핵","mis":"SC6-1-u3-X08"},{"t":"셀로판테이프","mis":"SC6-1-u3-X08"},{"t":"아무것도 없다","mis":"SC6-1-u3-X09"}],"explanation":["세포막 바깥이에요.","식물 세포만 있어요.","세포벽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L02_basic#3','sci',6,1,'u3','L02','g6_1_sci_u3_L02_basic','lesson_basic','SC6-1-u3-C5',1,'mc','auto','세포 안에 있는 둥근 것의 이름은 어느 것인가요?',ARRAY['SC6-1-u3-X08']::text[],false,'{"seq":3,"concept":"SC6-1-u3-C5","difficulty":1,"kind":"mc","stem":"세포 안에 있는 둥근 것의 이름은 어느 것인가요?","options":[{"t":"핵","correct":true},{"t":"세포벽","mis":"SC6-1-u3-X08"},{"t":"세포막","mis":"SC6-1-u3-X08"},{"t":"받침 유리","mis":"SC6-1-u3-X08"}],"explanation":["세포 안쪽이에요.","둥근 모양이에요.","핵이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L02_basic#4','sci',6,1,'u3','L02','g6_1_sci_u3_L02_basic','lesson_basic','SC6-1-u3-C6',1,'ox','auto','대부분의 세포는 크기가 매우 작아 현미경을 사용해야 관찰할 수 있어요.',ARRAY['SC6-1-u3-X11']::text[],false,'{"seq":4,"concept":"SC6-1-u3-C6","difficulty":1,"kind":"ox","stem":"대부분의 세포는 크기가 매우 작아 현미경을 사용해야 관찰할 수 있어요.","answer":"O","reason_options":[{"t":"대부분의 세포는 맨눈으로 보기에는 너무 작기 때문에","correct":true},{"t":"세포는 모두 커서 현미경이 필요 없기 때문에","mis":"SC6-1-u3-X11"}],"mis":"SC6-1-u3-X11","explanation":["세포의 크기를 떠올려요.","대부분 아주 작아요.","현미경으로 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L02_basic#5','sci',6,1,'u3','L02','g6_1_sci_u3_L02_basic','lesson_basic','SC6-1-u3-C4',2,'mc','auto','첨성대가 여러 개의 돌로 만들어졌다는 이야기로 알 수 있는 것은 어느 것인가요?',ARRAY['SC6-1-u3-X06','SC6-1-u3-X07']::text[],false,'{"seq":5,"concept":"SC6-1-u3-C4","difficulty":2,"kind":"mc","stem":"첨성대가 여러 개의 돌로 만들어졌다는 이야기로 알 수 있는 것은 어느 것인가요?","options":[{"t":"생물도 생김새는 달라도 세포라는 기본 단위로 이루어져 있다","correct":true},{"t":"생물 전체의 모양은 세포 하나의 모양과 같다","mis":"SC6-1-u3-X06"},{"t":"생물마다 기본 단위가 모두 다르다","mis":"SC6-1-u3-X06"},{"t":"첨성대처럼 세포도 모두 같은 크기다","mis":"SC6-1-u3-X07"}],"explanation":["돌을 쌓아 만들었어요.","전체 모양은 돌과 달라요.","생물도 세포로 이루어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L02_basic#6','sci',6,1,'u3','L02','g6_1_sci_u3_L02_basic','lesson_basic','SC6-1-u3-C5',2,'mc','auto','현미경 관찰 기록장에서 양파 표피세포가 보여 주는 식물 세포의 특징은 어느 것인가요?',ARRAY['SC6-1-u3-X09','SC6-1-u3-X08']::text[],false,'{"seq":6,"concept":"SC6-1-u3-C5","difficulty":2,"kind":"mc","stem":"현미경 관찰 기록장에서 양파 표피세포가 보여 주는 식물 세포의 특징은 어느 것인가요?","options":[{"t":"각진 세포들이 붙어 있고 세포마다 둥근 핵이 있다","correct":true},{"t":"세포마다 핵이 여러 개씩 흩어져 있다","mis":"SC6-1-u3-X09"},{"t":"세포 경계가 없어 하나로 이어져 있다","mis":"SC6-1-u3-X08"},{"t":"세포막이 없고 세포벽만 있다","mis":"SC6-1-u3-X09"}],"explanation":["기록을 읽어요.","각진 모양이에요.","둥근 핵이 하나씩이에요."],"asset":{"type":"passage","lines":["사철나무잎 뒷면 — 세포의 경계가 뚜렷하고 가운데 둥근 것이 보인다.","양파 표피 — 각진 세포들이 빈틈없이 서로 붙어 있다.","양파 표피 — 세포마다 둥근 핵이 하나씩 진하게 보인다.","두 식물 세포는 크기와 모양이 서로 달랐다."],"title":"현미경 관찰 기록장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L02_basic#7','sci',6,1,'u3','L02','g6_1_sci_u3_L02_basic','lesson_basic','SC6-1-u3-C4',2,'mc','auto','현미경 관찰 기록장의 마지막 줄로 알 수 있는 것은 어느 것인가요?',ARRAY['SC6-1-u3-X07','SC6-1-u3-X06','SC6-1-u3-X11']::text[],false,'{"seq":7,"concept":"SC6-1-u3-C4","difficulty":2,"kind":"mc","stem":"현미경 관찰 기록장의 마지막 줄로 알 수 있는 것은 어느 것인가요?","options":[{"t":"식물 세포는 종류에 따라 크기와 모양이 다양하다","correct":true},{"t":"식물 세포는 크기와 모양이 모두 같다","mis":"SC6-1-u3-X07"},{"t":"양파는 세포로 이루어져 있지 않다","mis":"SC6-1-u3-X06"},{"t":"사철나무 세포만 맨눈으로 보인다","mis":"SC6-1-u3-X11"}],"explanation":["두 세포를 견줬어요.","크기와 모양이 달라요.","세포는 다양해요."],"asset":{"type":"passage","lines":["사철나무잎 뒷면 — 세포의 경계가 뚜렷하고 가운데 둥근 것이 보인다.","양파 표피 — 각진 세포들이 빈틈없이 서로 붙어 있다.","양파 표피 — 세포마다 둥근 핵이 하나씩 진하게 보인다.","두 식물 세포는 크기와 모양이 서로 달랐다."],"title":"현미경 관찰 기록장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L02_basic#8','sci',6,1,'u3','L02','g6_1_sci_u3_L02_basic','lesson_basic','SC6-1-u3-C7',2,'mc','auto','사철나무잎으로 표본을 만들 때 투명 매니큐어를 얇게 바르는 까닭은 무엇인가요?',ARRAY['SC6-1-u3-X12','SC6-1-u3-X13','SC6-1-u3-X08']::text[],false,'{"seq":8,"concept":"SC6-1-u3-C7","difficulty":2,"kind":"mc","stem":"사철나무잎으로 표본을 만들 때 투명 매니큐어를 얇게 바르는 까닭은 무엇인가요?","options":[{"t":"빛이 잘 통과해야 세포가 잘 보이기 때문이다","correct":true},{"t":"두껍게 발라야 세포가 더 커지기 때문이다","mis":"SC6-1-u3-X12"},{"t":"얇게 바르면 냄새를 맡아도 되기 때문이다","mis":"SC6-1-u3-X13"},{"t":"매니큐어가 세포벽을 만들어 주기 때문이다","mis":"SC6-1-u3-X08"}],"explanation":["빛이 통과해야 해요.","얇게 발라요.","그래야 잘 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L02_basic#9','sci',6,1,'u3','L02','g6_1_sci_u3_L02_basic','lesson_basic','SC6-1-u3-C7',2,'ox','auto','투명 매니큐어를 바를 때는 창문을 열어 환기해요.',ARRAY['SC6-1-u3-X13']::text[],false,'{"seq":9,"concept":"SC6-1-u3-C7","difficulty":2,"kind":"ox","stem":"투명 매니큐어를 바를 때는 창문을 열어 환기해요.","answer":"O","reason_options":[{"t":"매니큐어에서 나는 냄새를 맡지 않도록 하기 위해서","correct":true},{"t":"냄새를 맡아야 매니큐어가 빨리 마르기 때문에","mis":"SC6-1-u3-X13"}],"mis":"SC6-1-u3-X13","explanation":["냄새가 나요.","맡지 않게 해요.","환기해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L02_basic#10','sci',6,1,'u3','L02','g6_1_sci_u3_L02_basic','lesson_basic','SC6-1-u3-C6',3,'error','auto','세포를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u3-X10','SC6-1-u3-X11']::text[],false,'{"seq":10,"concept":"SC6-1-u3-C6","difficulty":3,"kind":"error","stem":"세포를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은호 — 「세포는 하나도 빠짐없이 맨눈으로는 볼 수 없어.」","correct":true,"mis_target":"SC6-1-u3-X10"},{"t":"나윤 — 「대부분의 세포는 현미경으로 봐야 해.」","mis":"SC6-1-u3-X11"},{"t":"세아 — 「달걀은 하나의 세포인데 맨눈으로 보여.」","mis":"SC6-1-u3-X10"}],"explanation":["달걀을 떠올려요.","맨눈으로 보이는 세포도 있어요.","은호의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L02_challenge#1','sci',6,1,'u3','L02','g6_1_sci_u3_L02_challenge','lesson_challenge','SC6-1-u3-C5',2,'match','auto','세포의 각 부분과 위치를 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC6-1-u3-C5","difficulty":2,"kind":"match","stem":"세포의 각 부분과 위치를 알맞게 이으세요.","pairs":[{"l":"핵","r":"세포 안쪽의 둥근 것"},{"l":"세포막","r":"세포를 둘러싸는 막"},{"l":"세포벽","r":"세포막의 바깥쪽을 둘러쌈"}],"mis":"SC6-1-u3-X08","explanation":["안쪽에 핵이 있어요.","세포막이 둘러싸요.","그 바깥이 세포벽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L02_challenge#2','sci',6,1,'u3','L02','g6_1_sci_u3_L02_challenge','lesson_challenge','SC6-1-u3-C7',2,'mc','auto','사철나무잎 표본 만들기의 ㉠~㉢을 바른 차례로 늘어놓은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X12']::text[],false,'{"seq":2,"concept":"SC6-1-u3-C7","difficulty":2,"kind":"mc","stem":"사철나무잎 표본 만들기의 ㉠~㉢을 바른 차례로 늘어놓은 것은 어느 것인가요?","options":[{"t":"㉡ → ㉢ → ㉠","correct":true},{"t":"㉢ → ㉡ → ㉠","mis":"SC6-1-u3-X12"},{"t":"㉠ → ㉡ → ㉢","mis":"SC6-1-u3-X12"},{"t":"㉡ → ㉠ → ㉢","mis":"SC6-1-u3-X12"}],"explanation":["매니큐어를 먼저 발라요.","마르면 테이프를 붙여요.","떼어 받침 유리에 붙여요."],"asset":{"type":"passage","lines":["㉠ 셀로판테이프를 떼어 받침 유리에 붙인다.","㉡ 잎 뒷면에 투명 매니큐어를 얇게 바른다.","㉢ 매니큐어가 완전히 마르면 셀로판테이프를 붙여 문지른다."],"title":"사철나무잎 표본 만들기(차례가 섞임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L02_challenge#3','sci',6,1,'u3','L02','g6_1_sci_u3_L02_challenge','lesson_challenge','SC6-1-u3-C5',3,'mc','auto','양파 표피세포를 관찰했을 때 세포의 가장자리가 뚜렷하게 보이는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X09','SC6-1-u3-X08']::text[],false,'{"seq":3,"concept":"SC6-1-u3-C5","difficulty":3,"kind":"mc","stem":"양파 표피세포를 관찰했을 때 세포의 가장자리가 뚜렷하게 보이는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"가장자리에 세포벽이 있기 때문이다","correct":true},{"t":"세포 안에 핵이 없기 때문이다","mis":"SC6-1-u3-X09"},{"t":"가장자리에 핵이 모여 있기 때문이다","mis":"SC6-1-u3-X08"},{"t":"세포들이 모두 떨어져 있기 때문이다","mis":"SC6-1-u3-X08"}],"explanation":["가장자리를 봐요.","세포벽이 있어요.","그래서 뚜렷해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L02_challenge#4','sci',6,1,'u3','L02','g6_1_sci_u3_L02_challenge','lesson_challenge','SC6-1-u3-C6',3,'mc','auto','대화를 읽고, 도하의 말로 바로잡을 수 있는 생각은 어느 것인가요?',ARRAY['SC6-1-u3-X11','SC6-1-u3-X06','SC6-1-u3-X07']::text[],false,'{"seq":4,"concept":"SC6-1-u3-C6","difficulty":3,"kind":"mc","stem":"대화를 읽고, 도하의 말로 바로잡을 수 있는 생각은 어느 것인가요?","options":[{"t":"모든 세포는 맨눈으로 볼 수 없다는 생각","correct":true},{"t":"대부분의 세포가 아주 작다는 생각","mis":"SC6-1-u3-X11"},{"t":"생물은 세포로 이루어져 있다는 생각","mis":"SC6-1-u3-X06"},{"t":"세포는 종류에 따라 크기가 다르다는 생각","mis":"SC6-1-u3-X07"}],"explanation":["달걀을 말했어요.","맨눈으로 보이는 세포예요.","「모든 세포」가 틀렸어요."],"asset":{"type":"speech","turns":[{"who":"서윤","text":"세포는 다 아주 작아서 맨눈으로는 하나도 볼 수 없대."},{"who":"도하","text":"달걀 하나도 하나의 세포라던데? 그건 맨눈으로 보이잖아."},{"who":"서윤","text":"정말? 그럼 어떤 세포는 맨눈으로도 보이는 거네."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L02_challenge#5','sci',6,1,'u3','L02','g6_1_sci_u3_L02_challenge','lesson_challenge','SC6-1-u3-C6',3,'mc','auto','달걀이 하나의 세포이면서도 맨눈으로 보일 만큼 큰 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X10','SC6-1-u3-X11','SC6-1-u3-X09']::text[],false,'{"seq":5,"concept":"SC6-1-u3-C6","difficulty":3,"kind":"mc","stem":"달걀이 하나의 세포이면서도 맨눈으로 보일 만큼 큰 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"영양물질을 저장하고 있기 때문이다","correct":true},{"t":"달걀은 세포가 아니기 때문이다","mis":"SC6-1-u3-X10"},{"t":"달걀 속 세포는 모두 현미경으로만 보이기 때문이다","mis":"SC6-1-u3-X11"},{"t":"달걀에는 세포막이 없기 때문이다","mis":"SC6-1-u3-X09"}],"explanation":["달걀도 세포예요.","영양물질을 저장해요.","그래서 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L02_challenge#6','sci',6,1,'u3','L02','g6_1_sci_u3_L02_challenge','lesson_challenge','SC6-1-u3-C7',3,'ox','auto','셀로판테이프는 매니큐어가 완전히 마르기 전에 붙여야 세포가 잘 떨어져요.',ARRAY['SC6-1-u3-X12']::text[],false,'{"seq":6,"concept":"SC6-1-u3-C7","difficulty":3,"kind":"ox","stem":"셀로판테이프는 매니큐어가 완전히 마르기 전에 붙여야 세포가 잘 떨어져요.","answer":"X","reason_options":[{"t":"매니큐어가 완전히 말라야 세포가 매니큐어에 고정되기 때문에","correct":true},{"t":"마르기 전에 붙여야 표본이 두꺼워져 잘 보이기 때문에","mis":"SC6-1-u3-X12"}],"mis":"SC6-1-u3-X12","explanation":["언제 붙이나요?","완전히 마른 뒤예요.","틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L02_challenge#7','sci',6,1,'u3','L02','g6_1_sci_u3_L02_challenge','lesson_challenge','SC6-1-u3-C7',3,'error','auto','세포를 관찰하는 시간에 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u3-X13']::text[],false,'{"seq":7,"concept":"SC6-1-u3-C7","difficulty":3,"kind":"error","stem":"세포를 관찰하는 시간에 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"주원 — 「매니큐어 냄새가 좋으니 가까이 맡아 봐야지.」","correct":true,"mis_target":"SC6-1-u3-X13"},{"t":"시윤 — 「받침 유리 모서리에 손이 베이지 않게 조심하자.」","mis":"SC6-1-u3-X13"},{"t":"예준 — 「표본이 깨지지 않게 살살 다루자.」","mis":"SC6-1-u3-X13"}],"explanation":["냄새를 맡지 않아요.","환기해요.","주원의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L02_challenge#8','sci',6,1,'u3','L02','g6_1_sci_u3_L02_challenge','lesson_challenge','SC6-1-u3-C4',4,'mc','auto','「생물은 크기와 생김새가 각각 다르지만 ( ㉠ )(이)라는 기본 단위로 이루어져 있고, ( ㉠ )은/는 종류에 따라 크기와 모양이 ( ㉡ ).」 ㉠, ㉡에 알맞은 말은 어느 것인가요?',ARRAY['SC6-1-u3-X07','SC6-1-u3-X06']::text[],false,'{"seq":8,"concept":"SC6-1-u3-C4","difficulty":4,"kind":"mc","stem":"「생물은 크기와 생김새가 각각 다르지만 ( ㉠ )(이)라는 기본 단위로 이루어져 있고, ( ㉠ )은/는 종류에 따라 크기와 모양이 ( ㉡ ).」 ㉠, ㉡에 알맞은 말은 어느 것인가요?","options":[{"t":"㉠ 세포, ㉡ 다양하다","correct":true},{"t":"㉠ 세포, ㉡ 모두 같다","mis":"SC6-1-u3-X07"},{"t":"㉠ 핵, ㉡ 다양하다","mis":"SC6-1-u3-X06"},{"t":"㉠ 세포벽, ㉡ 모두 같다","mis":"SC6-1-u3-X06"}],"explanation":["기본 단위는 세포예요.","크기와 모양은 다양해요.","알맞게 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L02_challenge#9','sci',6,1,'u3','L02','g6_1_sci_u3_L02_challenge','lesson_challenge','SC6-1-u3-C5',4,'mc','auto','사철나무잎과 양파 표피를 모두 관찰한 뒤 두 세포에 공통으로 있다고 말할 수 있는 것은 어느 것인가요?',ARRAY['SC6-1-u3-X09','SC6-1-u3-X08']::text[],false,'{"seq":9,"concept":"SC6-1-u3-C5","difficulty":4,"kind":"mc","stem":"사철나무잎과 양파 표피를 모두 관찰한 뒤 두 세포에 공통으로 있다고 말할 수 있는 것은 어느 것인가요?","options":[{"t":"세포막, 세포벽, 둥근 핵","correct":true},{"t":"세포벽만 있고 세포막과 핵은 없음","mis":"SC6-1-u3-X09"},{"t":"핵 여러 개와 세포막만 있음","mis":"SC6-1-u3-X09"},{"t":"세포막 바깥에 핵, 가장 안쪽에 세포벽","mis":"SC6-1-u3-X08"}],"explanation":["둘 다 식물 세포예요.","세포막·세포벽이 있어요.","둥근 핵이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L02_challenge#10','sci',6,1,'u3','L02','g6_1_sci_u3_L02_challenge','lesson_challenge','SC6-1-u3-C5',4,'essay','teacher','현미경으로 관찰한 양파 표피세포의 모습을 떠올려, 식물 세포의 특징을 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-1-u3-C5","difficulty":4,"kind":"essay","stem":"현미경으로 관찰한 양파 표피세포의 모습을 떠올려, 식물 세포의 특징을 두 가지 쓰세요.","answer_guide":{"answer":"예: 세포 안에 둥근 핵이 있다. 세포벽이 있어 세포의 경계가 뚜렷하다.","scoring_points":["둥근 핵이 있다고 썼는가","세포벽이 있거나 경계가 뚜렷하다고 썼는가"]},"explanation":["관찰한 모습을 떠올려요.","핵을 찾아요.","경계가 뚜렷해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L03_basic#1','sci',6,1,'u3','L03','g6_1_sci_u3_L03_basic','lesson_basic','SC6-1-u3-C10',1,'mc','auto','우리가 먹는 당근은 식물의 어느 부분인가요?',ARRAY['SC6-1-u3-X20']::text[],false,'{"seq":1,"concept":"SC6-1-u3-C10","difficulty":1,"kind":"mc","stem":"우리가 먹는 당근은 식물의 어느 부분인가요?","options":[{"t":"뿌리","correct":true},{"t":"줄기","mis":"SC6-1-u3-X20"},{"t":"잎","mis":"SC6-1-u3-X20"},{"t":"꽃","mis":"SC6-1-u3-X20"}],"explanation":["땅속에서 자라요.","양분을 저장해요.","당근은 뿌리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L03_basic#2','sci',6,1,'u3','L03','g6_1_sci_u3_L03_basic','lesson_basic','SC6-1-u3-C10',1,'sa','auto','「식물은 뿌리로 물을 ( )합니다.」 빈칸에 알맞은 말을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC6-1-u3-C10","difficulty":1,"kind":"sa","stem":"「식물은 뿌리로 물을 ( )합니다.」 빈칸에 알맞은 말을 두 글자로 쓰세요.","answer":["흡수"],"explanation":["뿌리가 물을 받아들여요.","두 글자예요.","흡수예요."],"mis":"SC6-1-u3-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L03_basic#3','sci',6,1,'u3','L03','g6_1_sci_u3_L03_basic','lesson_basic','SC6-1-u3-C8',1,'mc','auto','뿌리에 솜털처럼 나 있는 가는 털의 이름은 어느 것인가요?',ARRAY['SC6-1-u3-X15']::text[],false,'{"seq":3,"concept":"SC6-1-u3-C8","difficulty":1,"kind":"mc","stem":"뿌리에 솜털처럼 나 있는 가는 털의 이름은 어느 것인가요?","options":[{"t":"뿌리털","correct":true},{"t":"핵","mis":"SC6-1-u3-X15"},{"t":"세포벽","mis":"SC6-1-u3-X15"},{"t":"탈지면","mis":"SC6-1-u3-X15"}],"explanation":["뿌리에 있어요.","솜털처럼 가늘어요.","뿌리털이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L03_basic#4','sci',6,1,'u3','L03','g6_1_sci_u3_L03_basic','lesson_basic','SC6-1-u3-C10',1,'ox','auto','뿌리는 땅속 깊이 뻗어 식물이 쓰러지지 않도록 지지해요.',ARRAY['SC6-1-u3-X21']::text[],false,'{"seq":4,"concept":"SC6-1-u3-C10","difficulty":1,"kind":"ox","stem":"뿌리는 땅속 깊이 뻗어 식물이 쓰러지지 않도록 지지해요.","answer":"O","reason_options":[{"t":"뿌리가 땅을 붙잡고 있어 바람이 불어도 식물을 받쳐 주기 때문에","correct":true},{"t":"뿌리는 물만 흡수하고 다른 일은 하지 않기 때문에","mis":"SC6-1-u3-X21"}],"mis":"SC6-1-u3-X21","explanation":["뿌리가 깊어요.","식물을 붙잡아요.","쓰러지지 않게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L03_basic#5','sci',6,1,'u3','L03','g6_1_sci_u3_L03_basic','lesson_basic','SC6-1-u3-C8',2,'mc','auto','여러 가지 식물의 뿌리에서 백합과 같은 생김새의 뿌리를 가진 식물은 어느 것인가요?',ARRAY['SC6-1-u3-X14']::text[],false,'{"seq":5,"concept":"SC6-1-u3-C8","difficulty":2,"kind":"mc","stem":"여러 가지 식물의 뿌리에서 백합과 같은 생김새의 뿌리를 가진 식물은 어느 것인가요?","options":[{"t":"강아지풀","correct":true},{"t":"민들레","mis":"SC6-1-u3-X14"},{"t":"사과나무","mis":"SC6-1-u3-X14"},{"t":"모든 식물이 같은 생김새다","mis":"SC6-1-u3-X14"}],"explanation":["백합 뿌리를 봐요.","수염처럼 나 있어요.","강아지풀이 같아요."],"asset":{"type":"passage","lines":["백합 — 굵기가 비슷한 가는 뿌리가 수염처럼 나 있다.","강아지풀 — 굵기가 비슷한 가는 뿌리가 수염처럼 나 있다.","민들레 — 굵고 곧은 뿌리에 가는 뿌리가 여러 개 나 있다.","사과나무 — 굵고 곧은 뿌리에 가는 뿌리가 여러 개 나 있다."],"title":"여러 가지 식물의 뿌리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L03_basic#6','sci',6,1,'u3','L03','g6_1_sci_u3_L03_basic','lesson_basic','SC6-1-u3-C9',2,'mc','auto','뿌리가 하는 일 알아보기 실험에서 3일 뒤 물이 더 많이 줄어든 쪽은 어느 것인가요?',ARRAY['SC6-1-u3-X16']::text[],false,'{"seq":6,"concept":"SC6-1-u3-C9","difficulty":2,"kind":"mc","stem":"뿌리가 하는 일 알아보기 실험에서 3일 뒤 물이 더 많이 줄어든 쪽은 어느 것인가요?","options":[{"t":"뿌리를 자르지 않은 파 ㉯ 쪽","correct":true},{"t":"뿌리를 자른 파 ㉮ 쪽","mis":"SC6-1-u3-X16"},{"t":"두 쪽이 똑같이 줄었다","mis":"SC6-1-u3-X16"},{"t":"두 쪽 모두 그대로였다","mis":"SC6-1-u3-X16"}],"explanation":["기록을 봐요.","㉯ 쪽이 많이 줄었어요.","뿌리가 있는 쪽이에요."],"asset":{"type":"passage","lines":["파 ㉮ — 잎과 뿌리를 모두 자름","파 ㉯ — 잎만 자름","두 파를 탈지면으로 감싸 같은 양의 물이 든 눈금실린더에 넣음","물 높이를 유성펜으로 표시하고 햇빛이 잘 드는 곳에 둠","3일 뒤 — ㉮ 쪽 물은 조금, ㉯ 쪽 물은 많이 줄어듦"],"title":"뿌리가 하는 일 알아보기 실험 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L03_basic#7','sci',6,1,'u3','L03','g6_1_sci_u3_L03_basic','lesson_basic','SC6-1-u3-C9',2,'mc','auto','뿌리가 하는 일 알아보기 실험에서 두 파를 다르게 한 조건은 어느 것인가요?',ARRAY['SC6-1-u3-X17']::text[],false,'{"seq":7,"concept":"SC6-1-u3-C9","difficulty":2,"kind":"mc","stem":"뿌리가 하는 일 알아보기 실험에서 두 파를 다르게 한 조건은 어느 것인가요?","options":[{"t":"뿌리가 있는지 없는지","correct":true},{"t":"눈금실린더에 넣은 물의 양","mis":"SC6-1-u3-X17"},{"t":"놓아둔 곳의 햇빛","mis":"SC6-1-u3-X17"},{"t":"관찰한 날짜","mis":"SC6-1-u3-X17"}],"explanation":["다르게 한 것은 하나예요.","뿌리를 잘랐는지예요.","나머지는 같게 해요."],"asset":{"type":"passage","lines":["파 ㉮ — 잎과 뿌리를 모두 자름","파 ㉯ — 잎만 자름","두 파를 탈지면으로 감싸 같은 양의 물이 든 눈금실린더에 넣음","물 높이를 유성펜으로 표시하고 햇빛이 잘 드는 곳에 둠","3일 뒤 — ㉮ 쪽 물은 조금, ㉯ 쪽 물은 많이 줄어듦"],"title":"뿌리가 하는 일 알아보기 실험 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L03_basic#8','sci',6,1,'u3','L03','g6_1_sci_u3_L03_basic','lesson_basic','SC6-1-u3-C10',2,'mc','auto','「뿌리 깊은 나무는 바람에 흔들리지 않는다.」라는 말과 가장 관계있는 뿌리의 일은 어느 것인가요?',ARRAY['SC6-1-u3-X19','SC6-1-u3-X15','SC6-1-u3-X21']::text[],false,'{"seq":8,"concept":"SC6-1-u3-C10","difficulty":2,"kind":"mc","stem":"「뿌리 깊은 나무는 바람에 흔들리지 않는다.」라는 말과 가장 관계있는 뿌리의 일은 어느 것인가요?","options":[{"t":"식물을 지지하는 일","correct":true},{"t":"양분을 만드는 일","mis":"SC6-1-u3-X19"},{"t":"물을 내보내는 일","mis":"SC6-1-u3-X15"},{"t":"씨를 퍼뜨리는 일","mis":"SC6-1-u3-X21"}],"explanation":["바람에 흔들리지 않아요.","뿌리가 붙잡아요.","지지하는 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L03_basic#9','sci',6,1,'u3','L03','g6_1_sci_u3_L03_basic','lesson_basic','SC6-1-u3-C8',2,'ox','auto','식물의 뿌리는 모두 굵고 곧은 뿌리에 가는 뿌리가 나 있는 모습이에요.',ARRAY['SC6-1-u3-X14']::text[],false,'{"seq":9,"concept":"SC6-1-u3-C8","difficulty":2,"kind":"ox","stem":"식물의 뿌리는 모두 굵고 곧은 뿌리에 가는 뿌리가 나 있는 모습이에요.","answer":"X","reason_options":[{"t":"수염처럼 가는 뿌리가 난 식물도 있어 뿌리의 모습이 다양하기 때문에","correct":true},{"t":"모든 식물은 민들레처럼 뿌리가 생겼기 때문에","mis":"SC6-1-u3-X14"}],"mis":"SC6-1-u3-X14","explanation":["백합을 떠올려요.","수염처럼 났어요.","뿌리 모습은 다양해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L03_basic#10','sci',6,1,'u3','L03','g6_1_sci_u3_L03_basic','lesson_basic','SC6-1-u3-C9',3,'error','auto','실험 결과를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u3-X18','SC6-1-u3-X16']::text[],false,'{"seq":10,"concept":"SC6-1-u3-C9","difficulty":3,"kind":"error","stem":"실험 결과를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서하 — 「예상과 조금 다르니까 기록을 예상대로 고쳐 적자.」","correct":true,"mis_target":"SC6-1-u3-X18"},{"t":"로운 — 「뿌리를 자른 파 쪽 물도 조금은 줄었네.」","mis":"SC6-1-u3-X16"},{"t":"다빈 — 「뿌리가 있는 파가 물을 더 많이 흡수했어.」","mis":"SC6-1-u3-X16"}],"explanation":["결과를 바꾸면 안 돼요.","있는 그대로 적어요.","서하의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L03_challenge#1','sci',6,1,'u3','L03','g6_1_sci_u3_L03_challenge','lesson_challenge','SC6-1-u3-C10',2,'match','auto','뿌리가 하는 일과 그 예를 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC6-1-u3-C10","difficulty":2,"kind":"match","stem":"뿌리가 하는 일과 그 예를 알맞게 이으세요.","pairs":[{"l":"물 흡수","r":"뿌리털이 있어 물을 잘 받아들임"},{"l":"지지","r":"바람이 불어도 식물이 쓰러지지 않음"},{"l":"양분 저장","r":"당근·고구마의 굵은 뿌리"}],"mis":"SC6-1-u3-X21","explanation":["뿌리는 여러 일을 해요.","흡수·지지·저장이에요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L03_challenge#2','sci',6,1,'u3','L03','g6_1_sci_u3_L03_challenge','lesson_challenge','SC6-1-u3-C9',2,'mc','auto','뿌리가 하는 일 알아보기 실험에서 같게 해야 할 조건이 아닌 것은 어느 것인가요?',ARRAY['SC6-1-u3-X17']::text[],false,'{"seq":2,"concept":"SC6-1-u3-C9","difficulty":2,"kind":"mc","stem":"뿌리가 하는 일 알아보기 실험에서 같게 해야 할 조건이 아닌 것은 어느 것인가요?","options":[{"t":"파의 뿌리를 자르는지","correct":true},{"t":"눈금실린더에 담은 물의 양","mis":"SC6-1-u3-X17"},{"t":"파를 놓아두는 곳","mis":"SC6-1-u3-X17"},{"t":"파의 크기","mis":"SC6-1-u3-X17"}],"explanation":["같게 할 조건을 찾아요.","뿌리만 다르게 해요.","뿌리를 자르는지가 답이에요."],"asset":{"type":"passage","lines":["파 ㉮ — 잎과 뿌리를 모두 자름","파 ㉯ — 잎만 자름","두 파를 탈지면으로 감싸 같은 양의 물이 든 눈금실린더에 넣음","물 높이를 유성펜으로 표시하고 햇빛이 잘 드는 곳에 둠","3일 뒤 — ㉮ 쪽 물은 조금, ㉯ 쪽 물은 많이 줄어듦"],"title":"뿌리가 하는 일 알아보기 실험 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L03_challenge#3','sci',6,1,'u3','L03','g6_1_sci_u3_L03_challenge','lesson_challenge','SC6-1-u3-C9',3,'mc','auto','뿌리가 하는 일 알아보기 실험 결과로 알 수 있는 것은 어느 것인가요?',ARRAY['SC6-1-u3-X19','SC6-1-u3-X16']::text[],false,'{"seq":3,"concept":"SC6-1-u3-C9","difficulty":3,"kind":"mc","stem":"뿌리가 하는 일 알아보기 실험 결과로 알 수 있는 것은 어느 것인가요?","options":[{"t":"식물은 뿌리로 물을 흡수한다","correct":true},{"t":"식물은 뿌리로 양분을 만든다","mis":"SC6-1-u3-X19"},{"t":"뿌리를 자르면 물이 더 많이 줄어든다","mis":"SC6-1-u3-X16"},{"t":"뿌리는 물과 상관없다","mis":"SC6-1-u3-X16"}],"explanation":["㉯ 쪽이 많이 줄었어요.","뿌리가 물을 받아들여요.","뿌리는 물을 흡수해요."],"asset":{"type":"passage","lines":["파 ㉮ — 잎과 뿌리를 모두 자름","파 ㉯ — 잎만 자름","두 파를 탈지면으로 감싸 같은 양의 물이 든 눈금실린더에 넣음","물 높이를 유성펜으로 표시하고 햇빛이 잘 드는 곳에 둠","3일 뒤 — ㉮ 쪽 물은 조금, ㉯ 쪽 물은 많이 줄어듦"],"title":"뿌리가 하는 일 알아보기 실험 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L03_challenge#4','sci',6,1,'u3','L03','g6_1_sci_u3_L03_challenge','lesson_challenge','SC6-1-u3-C9',3,'mc','auto','뿌리를 자른 파 ㉮ 쪽 물도 조금 줄어든 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X16','SC6-1-u3-X17','SC6-1-u3-X18']::text[],false,'{"seq":4,"concept":"SC6-1-u3-C9","difficulty":3,"kind":"mc","stem":"뿌리를 자른 파 ㉮ 쪽 물도 조금 줄어든 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"자른 면으로 물이 조금 들어가고 공기 중으로도 날아가기 때문이다","correct":true},{"t":"뿌리를 자르면 물을 더 많이 흡수하기 때문이다","mis":"SC6-1-u3-X16"},{"t":"눈금실린더마다 물을 다르게 넣었기 때문이다","mis":"SC6-1-u3-X17"},{"t":"기록을 잘못 적었으니 고쳐야 하기 때문이다","mis":"SC6-1-u3-X18"}],"explanation":["㉮도 조금 줄었어요.","자른 면과 공기 쪽으로요.","그래도 ㉯가 더 많이 줄어요."],"asset":{"type":"passage","lines":["파 ㉮ — 잎과 뿌리를 모두 자름","파 ㉯ — 잎만 자름","두 파를 탈지면으로 감싸 같은 양의 물이 든 눈금실린더에 넣음","물 높이를 유성펜으로 표시하고 햇빛이 잘 드는 곳에 둠","3일 뒤 — ㉮ 쪽 물은 조금, ㉯ 쪽 물은 많이 줄어듦"],"title":"뿌리가 하는 일 알아보기 실험 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L03_challenge#5','sci',6,1,'u3','L03','g6_1_sci_u3_L03_challenge','lesson_challenge','SC6-1-u3-C8',3,'mc','auto','뿌리에 뿌리털이 많이 나 있으면 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X15','SC6-1-u3-X21']::text[],false,'{"seq":5,"concept":"SC6-1-u3-C8","difficulty":3,"kind":"mc","stem":"뿌리에 뿌리털이 많이 나 있으면 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"물을 잘 흡수할 수 있다","correct":true},{"t":"양분을 더 많이 만들 수 있다","mis":"SC6-1-u3-X15"},{"t":"뿌리털은 하는 일이 없다","mis":"SC6-1-u3-X15"},{"t":"식물이 더 빨리 쓰러진다","mis":"SC6-1-u3-X21"}],"explanation":["뿌리털이 많아요.","물에 닿는 곳이 많아요.","물을 잘 흡수해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L03_challenge#6','sci',6,1,'u3','L03','g6_1_sci_u3_L03_challenge','lesson_challenge','SC6-1-u3-C10',3,'error','auto','뿌리를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u3-X19','SC6-1-u3-X20','SC6-1-u3-X21']::text[],false,'{"seq":6,"concept":"SC6-1-u3-C10","difficulty":3,"kind":"error","stem":"뿌리를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하람 — 「뿌리에서 식물에 필요한 양분을 만들어.」","correct":true,"mis_target":"SC6-1-u3-X19"},{"t":"윤서 — 「당근은 뿌리에 양분을 저장해.」","mis":"SC6-1-u3-X20"},{"t":"지안 — 「뿌리는 식물이 쓰러지지 않게 해.」","mis":"SC6-1-u3-X21"}],"explanation":["양분은 어디서 만들까요?","뿌리는 만들지 않아요.","하람의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L03_challenge#7','sci',6,1,'u3','L03','g6_1_sci_u3_L03_challenge','lesson_challenge','SC6-1-u3-C10',3,'ox','auto','고구마와 당근은 뿌리에 양분을 저장하는 식물이에요.',ARRAY['SC6-1-u3-X20']::text[],false,'{"seq":7,"concept":"SC6-1-u3-C10","difficulty":3,"kind":"ox","stem":"고구마와 당근은 뿌리에 양분을 저장하는 식물이에요.","answer":"O","reason_options":[{"t":"굵어진 뿌리 속에 양분을 모아 두기 때문에","correct":true},{"t":"뿌리에는 양분을 저장할 수 없기 때문에","mis":"SC6-1-u3-X20"}],"mis":"SC6-1-u3-X20","explanation":["고구마와 당근이에요.","뿌리가 굵어요.","양분을 저장해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L03_challenge#8','sci',6,1,'u3','L03','g6_1_sci_u3_L03_challenge','lesson_challenge','SC6-1-u3-C8',4,'mc','auto','여러 가지 식물의 뿌리를 두 무리로 바르게 나눈 것은 어느 것인가요?',ARRAY['SC6-1-u3-X14']::text[],false,'{"seq":8,"concept":"SC6-1-u3-C8","difficulty":4,"kind":"mc","stem":"여러 가지 식물의 뿌리를 두 무리로 바르게 나눈 것은 어느 것인가요?","options":[{"t":"(백합, 강아지풀) / (민들레, 사과나무)","correct":true},{"t":"(백합, 민들레) / (강아지풀, 사과나무)","mis":"SC6-1-u3-X14"},{"t":"(백합, 사과나무) / (강아지풀, 민들레)","mis":"SC6-1-u3-X14"},{"t":"네 식물은 뿌리 생김새가 같아 나눌 수 없다","mis":"SC6-1-u3-X14"}],"explanation":["생김새를 견줘요.","수염처럼 · 굵고 곧은.","두 무리로 나눠요."],"asset":{"type":"passage","lines":["백합 — 굵기가 비슷한 가는 뿌리가 수염처럼 나 있다.","강아지풀 — 굵기가 비슷한 가는 뿌리가 수염처럼 나 있다.","민들레 — 굵고 곧은 뿌리에 가는 뿌리가 여러 개 나 있다.","사과나무 — 굵고 곧은 뿌리에 가는 뿌리가 여러 개 나 있다."],"title":"여러 가지 식물의 뿌리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L03_challenge#9','sci',6,1,'u3','L03','g6_1_sci_u3_L03_challenge','lesson_challenge','SC6-1-u3-C10',4,'mc','auto','태풍이 지나간 뒤 뿌리가 얕게 내린 나무만 쓰러져 있었어요. 이 일과 관계있는 뿌리의 일은 어느 것인가요?',ARRAY['SC6-1-u3-X16','SC6-1-u3-X19','SC6-1-u3-X20']::text[],false,'{"seq":9,"concept":"SC6-1-u3-C10","difficulty":4,"kind":"mc","stem":"태풍이 지나간 뒤 뿌리가 얕게 내린 나무만 쓰러져 있었어요. 이 일과 관계있는 뿌리의 일은 어느 것인가요?","options":[{"t":"식물을 지지하는 일","correct":true},{"t":"물을 흡수하는 일","mis":"SC6-1-u3-X16"},{"t":"양분을 만드는 일","mis":"SC6-1-u3-X19"},{"t":"양분을 저장하는 일","mis":"SC6-1-u3-X20"}],"explanation":["얕은 뿌리가 문제예요.","붙잡는 힘이 약해요.","지지하는 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L03_challenge#10','sci',6,1,'u3','L03','g6_1_sci_u3_L03_challenge','lesson_challenge','SC6-1-u3-C9',4,'essay','teacher','뿌리를 자른 파와 자르지 않은 파로 한 실험을 떠올려, 물이 더 많이 줄어든 눈금실린더와 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-1-u3-C9","difficulty":4,"kind":"essay","stem":"뿌리를 자른 파와 자르지 않은 파로 한 실험을 떠올려, 물이 더 많이 줄어든 눈금실린더와 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 뿌리를 자르지 않은 파가 든 눈금실린더의 물이 더 많이 줄어든다. 식물의 뿌리는 물을 흡수하기 때문이다.","scoring_points":["뿌리를 자르지 않은 파 쪽이라고 썼는가","뿌리가 물을 흡수한다는 까닭을 썼는가"]},"explanation":["결과를 떠올려요.","뿌리가 있는 쪽이에요.","뿌리가 물을 흡수해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L04_basic#1','sci',6,1,'u3','L04','g6_1_sci_u3_L04_basic','lesson_basic','SC6-1-u3-C12',1,'sa','auto','「줄기에는 ( )이/가 이동하는 통로가 있습니다.」 빈칸에 알맞은 말을 한 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC6-1-u3-C12","difficulty":1,"kind":"sa","stem":"「줄기에는 ( )이/가 이동하는 통로가 있습니다.」 빈칸에 알맞은 말을 한 글자로 쓰세요.","answer":["물"],"explanation":["색소 물이 올라갔어요.","한 글자예요.","물이에요."],"mis":"SC6-1-u3-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L04_basic#2','sci',6,1,'u3','L04','g6_1_sci_u3_L04_basic','lesson_basic','SC6-1-u3-C13',1,'mc','auto','감자는 식물의 어느 부분에 양분을 저장하나요?',ARRAY['SC6-1-u3-X25']::text[],false,'{"seq":2,"concept":"SC6-1-u3-C13","difficulty":1,"kind":"mc","stem":"감자는 식물의 어느 부분에 양분을 저장하나요?","options":[{"t":"줄기","correct":true},{"t":"뿌리","mis":"SC6-1-u3-X25"},{"t":"꽃","mis":"SC6-1-u3-X25"},{"t":"열매","mis":"SC6-1-u3-X25"}],"explanation":["땅속에 있어요.","하지만 뿌리가 아니에요.","감자는 줄기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L04_basic#3','sci',6,1,'u3','L04','g6_1_sci_u3_L04_basic','lesson_basic','SC6-1-u3-C12',1,'ox','auto','대부분의 식물 줄기는 곧게 서서 식물을 지지해요.',ARRAY['SC6-1-u3-X27']::text[],false,'{"seq":3,"concept":"SC6-1-u3-C12","difficulty":1,"kind":"ox","stem":"대부분의 식물 줄기는 곧게 서서 식물을 지지해요.","answer":"O","reason_options":[{"t":"곧은 줄기가 식물의 몸을 받쳐 주기 때문에","correct":true},{"t":"줄기는 물만 옮길 뿐 식물을 받치지 않기 때문에","mis":"SC6-1-u3-X27"}],"mis":"SC6-1-u3-X27","explanation":["줄기가 서 있어요.","식물을 받쳐요.","지지해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L04_basic#4','sci',6,1,'u3','L04','g6_1_sci_u3_L04_basic','lesson_basic','SC6-1-u3-C13',1,'mc','auto','줄기가 다른 식물이나 막대를 감고 올라가는 식물은 어느 것인가요?',ARRAY['SC6-1-u3-X26','SC6-1-u3-X25']::text[],false,'{"seq":4,"concept":"SC6-1-u3-C13","difficulty":1,"kind":"mc","stem":"줄기가 다른 식물이나 막대를 감고 올라가는 식물은 어느 것인가요?","options":[{"t":"나팔꽃","correct":true},{"t":"봉선화","mis":"SC6-1-u3-X26"},{"t":"딸기","mis":"SC6-1-u3-X26"},{"t":"감자","mis":"SC6-1-u3-X25"}],"explanation":["감고 올라가요.","나팔꽃이에요.","줄기 모양은 다양해요."],"asset":{"type":"passage","lines":["봉선화 — 줄기가 곧게 서 있다.","나팔꽃 — 줄기가 다른 식물이나 막대를 감고 올라간다.","딸기 — 줄기가 땅 위를 기듯이 뻗는다.","감자 — 땅속 줄기에 양분을 저장한다."],"title":"여러 가지 식물의 줄기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L04_basic#5','sci',6,1,'u3','L04','g6_1_sci_u3_L04_basic','lesson_basic','SC6-1-u3-C11',2,'mc','auto','백합 줄기 실험 기록에서 하루 뒤 백합의 꽃과 잎이 붉은빛을 띤 까닭은 무엇인가요?',ARRAY['SC6-1-u3-X23','SC6-1-u3-X24','SC6-1-u3-X22']::text[],false,'{"seq":5,"concept":"SC6-1-u3-C11","difficulty":2,"kind":"mc","stem":"백합 줄기 실험 기록에서 하루 뒤 백합의 꽃과 잎이 붉은빛을 띤 까닭은 무엇인가요?","options":[{"t":"줄기를 통해 색소 물이 잎과 꽃까지 이동했기 때문이다","correct":true},{"t":"꽃잎이 원래 붉은색이었기 때문이다","mis":"SC6-1-u3-X23"},{"t":"색소 물은 줄기에만 머물렀기 때문이다","mis":"SC6-1-u3-X24"},{"t":"잎과 꽃이 공기 중의 색소를 흡수했기 때문이다","mis":"SC6-1-u3-X22"}],"explanation":["색소 물이 올라갔어요.","잎과 꽃까지 갔어요.","그래서 붉어졌어요."],"asset":{"type":"passage","lines":["백합 줄기를 붉은색 색소를 녹인 물에 넣어 햇빛이 드는 곳에 둠","하루 뒤 — 흰 꽃잎과 초록 잎이 붉은빛을 띰","줄기를 가로로 자른 단면 — 붉은 점들이 퍼져 있음","줄기를 세로로 자른 단면 — 붉은 선들이 이어져 있음"],"title":"백합 줄기 실험 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L04_basic#6','sci',6,1,'u3','L04','g6_1_sci_u3_L04_basic','lesson_basic','SC6-1-u3-C11',2,'mc','auto','백합 줄기를 세로로 자른 단면에서 볼 수 있는 모습은 어느 것인가요?',ARRAY['SC6-1-u3-X23','SC6-1-u3-X24']::text[],false,'{"seq":6,"concept":"SC6-1-u3-C11","difficulty":2,"kind":"mc","stem":"백합 줄기를 세로로 자른 단면에서 볼 수 있는 모습은 어느 것인가요?","options":[{"t":"붉은 선들이 이어져 있다","correct":true},{"t":"붉은 점들만 퍼져 있다","mis":"SC6-1-u3-X23"},{"t":"붉은색이 하나도 없다","mis":"SC6-1-u3-X24"},{"t":"줄기 전체가 고르게 붉다","mis":"SC6-1-u3-X23"}],"explanation":["세로로 잘랐어요.","선처럼 이어져요.","물이 이동한 길이에요."],"asset":{"type":"passage","lines":["백합 줄기를 붉은색 색소를 녹인 물에 넣어 햇빛이 드는 곳에 둠","하루 뒤 — 흰 꽃잎과 초록 잎이 붉은빛을 띰","줄기를 가로로 자른 단면 — 붉은 점들이 퍼져 있음","줄기를 세로로 자른 단면 — 붉은 선들이 이어져 있음"],"title":"백합 줄기 실험 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L04_basic#7','sci',6,1,'u3','L04','g6_1_sci_u3_L04_basic','lesson_basic','SC6-1-u3-C12',2,'mc','auto','뿌리에서 흡수한 물이 잎과 꽃으로 가려면 꼭 지나야 하는 기관은 어느 것인가요?',ARRAY['SC6-1-u3-X22','SC6-1-u3-X24']::text[],false,'{"seq":7,"concept":"SC6-1-u3-C12","difficulty":2,"kind":"mc","stem":"뿌리에서 흡수한 물이 잎과 꽃으로 가려면 꼭 지나야 하는 기관은 어느 것인가요?","options":[{"t":"줄기","correct":true},{"t":"뿌리털","mis":"SC6-1-u3-X22"},{"t":"열매","mis":"SC6-1-u3-X22"},{"t":"어떤 기관도 지나지 않는다","mis":"SC6-1-u3-X24"}],"explanation":["뿌리와 잎 사이예요.","줄기가 이어 줘요.","줄기를 지나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L04_basic#8','sci',6,1,'u3','L04','g6_1_sci_u3_L04_basic','lesson_basic','SC6-1-u3-C13',2,'mc','auto','딸기 줄기의 특징으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X26','SC6-1-u3-X25']::text[],false,'{"seq":8,"concept":"SC6-1-u3-C13","difficulty":2,"kind":"mc","stem":"딸기 줄기의 특징으로 알맞은 것은 어느 것인가요?","options":[{"t":"땅 위를 기듯이 뻗는다","correct":true},{"t":"곧게 서서 위로만 자란다","mis":"SC6-1-u3-X26"},{"t":"땅속에서 굵어져 뿌리가 된다","mis":"SC6-1-u3-X25"},{"t":"다른 식물을 감고 올라간다","mis":"SC6-1-u3-X26"}],"explanation":["딸기를 떠올려요.","땅 위를 기어요.","줄기 모양이 다양해요."],"asset":{"type":"passage","lines":["봉선화 — 줄기가 곧게 서 있다.","나팔꽃 — 줄기가 다른 식물이나 막대를 감고 올라간다.","딸기 — 줄기가 땅 위를 기듯이 뻗는다.","감자 — 땅속 줄기에 양분을 저장한다."],"title":"여러 가지 식물의 줄기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L04_basic#9','sci',6,1,'u3','L04','g6_1_sci_u3_L04_basic','lesson_basic','SC6-1-u3-C12',2,'ox','auto','식물의 줄기는 땅속에서 물을 흡수하는 일을 해요.',ARRAY['SC6-1-u3-X22']::text[],false,'{"seq":9,"concept":"SC6-1-u3-C12","difficulty":2,"kind":"ox","stem":"식물의 줄기는 땅속에서 물을 흡수하는 일을 해요.","answer":"X","reason_options":[{"t":"물을 흡수하는 것은 뿌리이고 줄기는 물이 이동하는 통로이기 때문에","correct":true},{"t":"줄기에 뿌리털이 많이 나 있기 때문에","mis":"SC6-1-u3-X22"}],"mis":"SC6-1-u3-X22","explanation":["흡수는 어디서 하나요?","뿌리가 해요.","줄기는 통로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L04_basic#10','sci',6,1,'u3','L04','g6_1_sci_u3_L04_basic','lesson_basic','SC6-1-u3-C13',3,'error','auto','감자와 고구마를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u3-X25','SC6-1-u3-X20']::text[],false,'{"seq":10,"concept":"SC6-1-u3-C13","difficulty":3,"kind":"error","stem":"감자와 고구마를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수호 — 「고구마가 뿌리니까 비슷하게 생긴 감자도 뿌리야.」","correct":true,"mis_target":"SC6-1-u3-X25"},{"t":"채원 — 「감자는 줄기에 양분을 저장한 거야.」","mis":"SC6-1-u3-X25"},{"t":"이준 — 「고구마는 뿌리에 양분을 저장해.」","mis":"SC6-1-u3-X20"}],"explanation":["비슷해 보여도 달라요.","감자는 줄기예요.","수호의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L04_challenge#1','sci',6,1,'u3','L04','g6_1_sci_u3_L04_challenge','lesson_challenge','SC6-1-u3-C13',2,'match','auto','식물과 줄기의 특징을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC6-1-u3-C13","difficulty":2,"kind":"match","stem":"식물과 줄기의 특징을 알맞게 이으세요.","pairs":[{"l":"봉선화","r":"곧게 서 있음"},{"l":"나팔꽃","r":"다른 식물을 감고 올라감"},{"l":"딸기","r":"땅 위를 기듯이 뻗음"}],"mis":"SC6-1-u3-X26","explanation":["기록을 봐요.","줄기 모양이 달라요.","하나씩 이어요."],"asset":{"type":"passage","lines":["봉선화 — 줄기가 곧게 서 있다.","나팔꽃 — 줄기가 다른 식물이나 막대를 감고 올라간다.","딸기 — 줄기가 땅 위를 기듯이 뻗는다.","감자 — 땅속 줄기에 양분을 저장한다."],"title":"여러 가지 식물의 줄기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L04_challenge#2','sci',6,1,'u3','L04','g6_1_sci_u3_L04_challenge','lesson_challenge','SC6-1-u3-C11',2,'mc','auto','백합 줄기를 가로로 자른 단면에 붉은 점들이 퍼져 있는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X23','SC6-1-u3-X22','SC6-1-u3-X24']::text[],false,'{"seq":2,"concept":"SC6-1-u3-C11","difficulty":2,"kind":"mc","stem":"백합 줄기를 가로로 자른 단면에 붉은 점들이 퍼져 있는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"물이 이동하는 통로가 줄기 곳곳에 있기 때문이다","correct":true},{"t":"색소가 줄기에 저장되었기 때문이다","mis":"SC6-1-u3-X23"},{"t":"줄기가 물을 흡수하기 때문이다","mis":"SC6-1-u3-X22"},{"t":"색소 물은 줄기 끝에서 멈추기 때문이다","mis":"SC6-1-u3-X24"}],"explanation":["가로로 잘랐어요.","통로가 점으로 보여요.","물이 이동한 통로예요."],"asset":{"type":"passage","lines":["백합 줄기를 붉은색 색소를 녹인 물에 넣어 햇빛이 드는 곳에 둠","하루 뒤 — 흰 꽃잎과 초록 잎이 붉은빛을 띰","줄기를 가로로 자른 단면 — 붉은 점들이 퍼져 있음","줄기를 세로로 자른 단면 — 붉은 선들이 이어져 있음"],"title":"백합 줄기 실험 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L04_challenge#3','sci',6,1,'u3','L04','g6_1_sci_u3_L04_challenge','lesson_challenge','SC6-1-u3-C12',3,'mc','auto','백합 줄기 실험으로 알 수 있는 줄기가 하는 일은 어느 것인가요?',ARRAY['SC6-1-u3-X27','SC6-1-u3-X22','SC6-1-u3-X24']::text[],false,'{"seq":3,"concept":"SC6-1-u3-C12","difficulty":3,"kind":"mc","stem":"백합 줄기 실험으로 알 수 있는 줄기가 하는 일은 어느 것인가요?","options":[{"t":"뿌리에서 흡수한 물을 잎과 꽃 등으로 옮긴다","correct":true},{"t":"잎에서 쓸 양분을 줄기가 만든다","mis":"SC6-1-u3-X27"},{"t":"물을 땅속에서 직접 흡수한다","mis":"SC6-1-u3-X22"},{"t":"물을 줄기 안에만 모아 둔다","mis":"SC6-1-u3-X24"}],"explanation":["색소 물이 올라갔어요.","잎과 꽃까지 갔어요.","줄기는 물의 통로예요."],"asset":{"type":"passage","lines":["백합 줄기를 붉은색 색소를 녹인 물에 넣어 햇빛이 드는 곳에 둠","하루 뒤 — 흰 꽃잎과 초록 잎이 붉은빛을 띰","줄기를 가로로 자른 단면 — 붉은 점들이 퍼져 있음","줄기를 세로로 자른 단면 — 붉은 선들이 이어져 있음"],"title":"백합 줄기 실험 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L04_challenge#4','sci',6,1,'u3','L04','g6_1_sci_u3_L04_challenge','lesson_challenge','SC6-1-u3-C11',3,'mc','auto','하루 뒤 백합 줄기 단면에서 붉게 물든 부분은 무엇인가요?',ARRAY['SC6-1-u3-X23','SC6-1-u3-X22']::text[],false,'{"seq":4,"concept":"SC6-1-u3-C11","difficulty":3,"kind":"mc","stem":"하루 뒤 백합 줄기 단면에서 붉게 물든 부분은 무엇인가요?","options":[{"t":"물이 이동한 통로","correct":true},{"t":"양분이 저장된 곳","mis":"SC6-1-u3-X23"},{"t":"줄기가 물을 흡수한 곳","mis":"SC6-1-u3-X22"},{"t":"원래부터 붉은색인 곳","mis":"SC6-1-u3-X23"}],"explanation":["붉은 물이 지나갔어요.","그 길이 물들었어요.","물이 이동한 통로예요."],"asset":{"type":"passage","lines":["백합 줄기를 붉은색 색소를 녹인 물에 넣어 햇빛이 드는 곳에 둠","하루 뒤 — 흰 꽃잎과 초록 잎이 붉은빛을 띰","줄기를 가로로 자른 단면 — 붉은 점들이 퍼져 있음","줄기를 세로로 자른 단면 — 붉은 선들이 이어져 있음"],"title":"백합 줄기 실험 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L04_challenge#5','sci',6,1,'u3','L04','g6_1_sci_u3_L04_challenge','lesson_challenge','SC6-1-u3-C12',3,'error','auto','줄기가 하는 일을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u3-X27','SC6-1-u3-X26','SC6-1-u3-X23']::text[],false,'{"seq":5,"concept":"SC6-1-u3-C12","difficulty":3,"kind":"error","stem":"줄기가 하는 일을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「줄기는 햇빛으로 양분을 만들어서 뿌리로 보내.」","correct":true,"mis_target":"SC6-1-u3-X27"},{"t":"소율 — 「줄기는 뿌리와 잎, 꽃을 이어 줘.」","mis":"SC6-1-u3-X26"},{"t":"가은 — 「줄기에는 물이 이동하는 통로가 있어.」","mis":"SC6-1-u3-X23"}],"explanation":["줄기는 무엇을 하나요?","통로이자 연결이에요.","태오의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L04_challenge#6','sci',6,1,'u3','L04','g6_1_sci_u3_L04_challenge','lesson_challenge','SC6-1-u3-C13',3,'ox','auto','식물의 줄기는 모두 곧게 서서 자라요.',ARRAY['SC6-1-u3-X26']::text[],false,'{"seq":6,"concept":"SC6-1-u3-C13","difficulty":3,"kind":"ox","stem":"식물의 줄기는 모두 곧게 서서 자라요.","answer":"X","reason_options":[{"t":"나팔꽃처럼 감고 올라가거나 딸기처럼 땅 위를 기는 줄기도 있기 때문에","correct":true},{"t":"줄기는 서 있어야만 물이 이동하기 때문에","mis":"SC6-1-u3-X26"}],"mis":"SC6-1-u3-X26","explanation":["나팔꽃과 딸기를 떠올려요.","모두 곧진 않아요.","틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L04_challenge#7','sci',6,1,'u3','L04','g6_1_sci_u3_L04_challenge','lesson_challenge','SC6-1-u3-C13',3,'mc','auto','담쟁이덩굴이 벽을 타고 위로 자라는 모습과 줄기의 특징이 가장 비슷한 식물은 어느 것인가요?',ARRAY['SC6-1-u3-X26','SC6-1-u3-X25']::text[],false,'{"seq":7,"concept":"SC6-1-u3-C13","difficulty":3,"kind":"mc","stem":"담쟁이덩굴이 벽을 타고 위로 자라는 모습과 줄기의 특징이 가장 비슷한 식물은 어느 것인가요?","options":[{"t":"나팔꽃","correct":true},{"t":"봉선화","mis":"SC6-1-u3-X26"},{"t":"감자","mis":"SC6-1-u3-X25"},{"t":"딸기","mis":"SC6-1-u3-X26"}],"explanation":["타고 올라가요.","감고 올라가는 줄기예요.","나팔꽃과 비슷해요."],"asset":{"type":"passage","lines":["봉선화 — 줄기가 곧게 서 있다.","나팔꽃 — 줄기가 다른 식물이나 막대를 감고 올라간다.","딸기 — 줄기가 땅 위를 기듯이 뻗는다.","감자 — 땅속 줄기에 양분을 저장한다."],"title":"여러 가지 식물의 줄기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L04_challenge#8','sci',6,1,'u3','L04','g6_1_sci_u3_L04_challenge','lesson_challenge','SC6-1-u3-C11',4,'mc','auto','백합 줄기 실험을 다시 할 때 붉은색 색소 물에 넣은 백합을 햇빛이 잘 드는 곳에 두는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X23','SC6-1-u3-X24','SC6-1-u3-X22']::text[],false,'{"seq":8,"concept":"SC6-1-u3-C11","difficulty":4,"kind":"mc","stem":"백합 줄기 실험을 다시 할 때 붉은색 색소 물에 넣은 백합을 햇빛이 잘 드는 곳에 두는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"물이 활발하게 이동해 색깔 변화를 뚜렷하게 볼 수 있어서","correct":true},{"t":"햇빛이 꽃을 붉게 물들이기 때문에","mis":"SC6-1-u3-X23"},{"t":"그늘에서는 색소 물이 줄기에만 머물러야 하기 때문에","mis":"SC6-1-u3-X24"},{"t":"햇빛을 받으면 줄기가 물을 흡수하기 때문에","mis":"SC6-1-u3-X22"}],"explanation":["햇빛이 드는 곳이에요.","물이 잘 올라가요.","변화가 뚜렷해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L04_challenge#9','sci',6,1,'u3','L04','g6_1_sci_u3_L04_challenge','lesson_challenge','SC6-1-u3-C12',4,'mc','auto','줄기에 문제가 생겨 물이 이동하는 통로가 막힌다면 어떻게 될지 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['SC6-1-u3-X22','SC6-1-u3-X27','SC6-1-u3-X24']::text[],false,'{"seq":9,"concept":"SC6-1-u3-C12","difficulty":4,"kind":"mc","stem":"줄기에 문제가 생겨 물이 이동하는 통로가 막힌다면 어떻게 될지 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"뿌리가 물을 흡수해도 잎과 꽃까지 물이 가지 못한다","correct":true},{"t":"줄기가 대신 물을 흡수하니 괜찮다","mis":"SC6-1-u3-X22"},{"t":"줄기가 양분을 만들어 주니 괜찮다","mis":"SC6-1-u3-X27"},{"t":"물은 줄기 없이도 잎으로 바로 간다","mis":"SC6-1-u3-X24"}],"explanation":["통로가 막혔어요.","물이 올라가지 못해요.","잎과 꽃이 물을 못 받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L04_challenge#10','sci',6,1,'u3','L04','g6_1_sci_u3_L04_challenge','lesson_challenge','SC6-1-u3-C12',4,'essay','teacher','붉은색 색소 물에 하루 동안 넣어 둔 백합 줄기를 잘랐더니 단면이 붉게 물들어 있었어요. 붉게 물든 부분이 무엇인지 쓰고, 이것으로 알 수 있는 줄기가 하는 일을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-1-u3-C12","difficulty":4,"kind":"essay","stem":"붉은색 색소 물에 하루 동안 넣어 둔 백합 줄기를 잘랐더니 단면이 붉게 물들어 있었어요. 붉게 물든 부분이 무엇인지 쓰고, 이것으로 알 수 있는 줄기가 하는 일을 쓰세요.","answer_guide":{"answer":"예: 붉게 물든 부분은 물이 이동한 통로이다. 줄기는 뿌리에서 흡수한 물을 잎이나 꽃 등 식물의 각 기관으로 옮긴다.","scoring_points":["물이 이동한 통로라고 썼는가","물을 잎과 꽃 등으로 옮긴다고 썼는가"]},"explanation":["붉은 물이 지나갔어요.","물이 이동한 통로예요.","줄기는 물을 옮겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L05_basic#1','sci',6,1,'u3','L05','g6_1_sci_u3_L05_basic','lesson_basic','SC6-1-u3-C15',1,'sa','auto','식물이 빛을 이용해 이산화 탄소와 물로 양분을 만드는 것을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC6-1-u3-C15","difficulty":1,"kind":"sa","stem":"식물이 빛을 이용해 이산화 탄소와 물로 양분을 만드는 것을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["광합성"],"explanation":["빛으로 양분을 만들어요.","세 글자예요.","광합성이에요."],"mis":"SC6-1-u3-X30"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L05_basic#2','sci',6,1,'u3','L05','g6_1_sci_u3_L05_basic','lesson_basic','SC6-1-u3-C14',1,'mc','auto','식물의 잎은 대부분 무엇으로 이루어져 있나요?',ARRAY['SC6-1-u3-X28']::text[],false,'{"seq":2,"concept":"SC6-1-u3-C14","difficulty":1,"kind":"mc","stem":"식물의 잎은 대부분 무엇으로 이루어져 있나요?","options":[{"t":"잎몸과 잎자루","correct":true},{"t":"뿌리와 열매","mis":"SC6-1-u3-X28"},{"t":"뿌리털과 줄기","mis":"SC6-1-u3-X28"},{"t":"세포벽만","mis":"SC6-1-u3-X28"}],"explanation":["잎을 떠올려요.","넓은 부분과 자루예요.","잎몸과 잎자루예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L05_basic#3','sci',6,1,'u3','L05','g6_1_sci_u3_L05_basic','lesson_basic','SC6-1-u3-C15',1,'ox','auto','식물이 양분을 만들려면 빛이 필요해요.',ARRAY['SC6-1-u3-X30']::text[],false,'{"seq":3,"concept":"SC6-1-u3-C15","difficulty":1,"kind":"ox","stem":"식물이 양분을 만들려면 빛이 필요해요.","answer":"O","reason_options":[{"t":"빛을 받은 잎에서만 녹말과 같은 양분이 만들어졌기 때문에","correct":true},{"t":"양분은 빛과 상관없이 어둠 속에서 더 잘 만들어지기 때문에","mis":"SC6-1-u3-X30"}],"mis":"SC6-1-u3-X30","explanation":["포일 실험을 떠올려요.","빛을 받은 잎에서 만들어요.","빛이 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L05_basic#4','sci',6,1,'u3','L05','g6_1_sci_u3_L05_basic','lesson_basic','SC6-1-u3-C15',1,'mc','auto','광합성이 가장 활발하게 일어나는 곳은 주로 어디인가요?',ARRAY['SC6-1-u3-X29']::text[],false,'{"seq":4,"concept":"SC6-1-u3-C15","difficulty":1,"kind":"mc","stem":"광합성이 가장 활발하게 일어나는 곳은 주로 어디인가요?","options":[{"t":"잎","correct":true},{"t":"뿌리털","mis":"SC6-1-u3-X29"},{"t":"땅속 뿌리","mis":"SC6-1-u3-X29"},{"t":"열매 속 씨","mis":"SC6-1-u3-X29"}],"explanation":["양분을 만드는 곳이에요.","주로 잎이에요.","잎에서 가장 활발해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L05_basic#5','sci',6,1,'u3','L05','g6_1_sci_u3_L05_basic','lesson_basic','SC6-1-u3-C14',2,'match','auto','잎을 관찰한 메모의 ㉠~㉢과 이름을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC6-1-u3-C14","difficulty":2,"kind":"match","stem":"잎을 관찰한 메모의 ㉠~㉢과 이름을 알맞게 이으세요.","pairs":[{"l":"㉠","r":"잎몸"},{"l":"㉡","r":"잎자루"},{"l":"㉢","r":"잎맥"}],"mis":"SC6-1-u3-X28","explanation":["넓적한 부분은 잎몸이에요.","자루는 잎자루예요.","퍼진 줄은 잎맥이에요."],"asset":{"type":"passage","lines":["㉠ 넓적하고 평평한 부분","㉡ ㉠과 줄기를 잇는 가느다란 자루 부분","㉢ ㉠에 그물이나 줄처럼 퍼져 있는 부분"],"title":"잎을 관찰한 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L05_basic#6','sci',6,1,'u3','L05','g6_1_sci_u3_L05_basic','lesson_basic','SC6-1-u3-C16',2,'mc','auto','광합성으로 만든 양분 확인 실험에서 잎 하나에 알루미늄 포일을 씌운 까닭은 무엇인가요?',ARRAY['SC6-1-u3-X32','SC6-1-u3-X30']::text[],false,'{"seq":6,"concept":"SC6-1-u3-C16","difficulty":2,"kind":"mc","stem":"광합성으로 만든 양분 확인 실험에서 잎 하나에 알루미늄 포일을 씌운 까닭은 무엇인가요?","options":[{"t":"빛을 받은 잎과 받지 못한 잎을 견주기 위해","correct":true},{"t":"잎이 마르지 않게 하려고","mis":"SC6-1-u3-X32"},{"t":"잎을 따뜻하게 하려고","mis":"SC6-1-u3-X32"},{"t":"포일이 양분을 만들어 주기 때문에","mis":"SC6-1-u3-X30"}],"explanation":["포일은 빛을 막아요.","빛만 다르게 해요.","두 잎을 견줘요."],"asset":{"type":"passage","lines":["① 잎 하나에 알루미늄 포일을 씌우고 화분을 햇빛이 드는 곳에 둔다.","② 하루 뒤 포일을 씌운 잎과 씌우지 않은 잎을 하나씩 딴다.","③ 두 잎을 뜨거운 물에 잠깐 담갔다가 에탄올이 든 시험관에 넣는다.","④ 시험관을 뜨거운 물에 담가 잎의 초록색을 뺀다.","⑤ 잎을 물에 헹군 뒤 녹말을 만나면 색이 변하는 용액을 떨어뜨린다."],"title":"광합성으로 만든 양분 확인 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L05_basic#7','sci',6,1,'u3','L05','g6_1_sci_u3_L05_basic','lesson_basic','SC6-1-u3-C16',2,'mc','auto','실험 결과에서 용액을 떨어뜨린 곳이 청람색으로 변한 잎은 어느 것인가요?',ARRAY['SC6-1-u3-X31']::text[],false,'{"seq":7,"concept":"SC6-1-u3-C16","difficulty":2,"kind":"mc","stem":"실험 결과에서 용액을 떨어뜨린 곳이 청람색으로 변한 잎은 어느 것인가요?","options":[{"t":"포일을 씌우지 않은 잎","correct":true},{"t":"포일을 씌운 잎","mis":"SC6-1-u3-X31"},{"t":"두 잎 모두","mis":"SC6-1-u3-X31"},{"t":"두 잎 모두 변하지 않았다","mis":"SC6-1-u3-X31"}],"explanation":["결과를 봐요.","햇빛을 받은 잎이에요.","포일을 씌우지 않은 잎이에요."],"asset":{"type":"passage","lines":["포일을 씌우지 않은 잎 — 용액을 떨어뜨린 곳이 청람색으로 변함","포일을 씌운 잎 — 색깔 변화가 없음"],"title":"실험 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L05_basic#8','sci',6,1,'u3','L05','g6_1_sci_u3_L05_basic','lesson_basic','SC6-1-u3-C17',2,'mc','auto','잎에서 만든 양분은 어떻게 되나요?',ARRAY['SC6-1-u3-X35','SC6-1-u3-X30']::text[],false,'{"seq":8,"concept":"SC6-1-u3-C17","difficulty":2,"kind":"mc","stem":"잎에서 만든 양분은 어떻게 되나요?","options":[{"t":"줄기를 통해 식물 전체로 이동해 쓰이고 남은 것은 저장된다","correct":true},{"t":"만든 잎에서만 쓰이고 사라진다","mis":"SC6-1-u3-X35"},{"t":"뿌리를 통해 땅속으로 버려진다","mis":"SC6-1-u3-X35"},{"t":"꽃에서 다시 물로 바뀐다","mis":"SC6-1-u3-X30"}],"explanation":["양분이 움직여요.","줄기를 통해 이동해요.","쓰고 남으면 저장해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L05_basic#9','sci',6,1,'u3','L05','g6_1_sci_u3_L05_basic','lesson_basic','SC6-1-u3-C16',2,'ox','auto','에탄올이 든 시험관을 다룰 때는 나오는 기체를 마시지 않도록 하고 창문을 열어 환기해요.',ARRAY['SC6-1-u3-X33']::text[],false,'{"seq":9,"concept":"SC6-1-u3-C16","difficulty":2,"kind":"ox","stem":"에탄올이 든 시험관을 다룰 때는 나오는 기체를 마시지 않도록 하고 창문을 열어 환기해요.","answer":"O","reason_options":[{"t":"에탄올에서 나온 기체를 마시면 몸에 해로울 수 있기 때문에","correct":true},{"t":"기체를 마셔야 실험 결과가 잘 나오기 때문에","mis":"SC6-1-u3-X33"}],"mis":"SC6-1-u3-X33","explanation":["에탄올을 써요.","기체를 마시지 않아요.","환기해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L05_basic#10','sci',6,1,'u3','L05','g6_1_sci_u3_L05_basic','lesson_basic','SC6-1-u3-C15',3,'error','auto','광합성을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u3-X29','SC6-1-u3-X30']::text[],false,'{"seq":10,"concept":"SC6-1-u3-C15","difficulty":3,"kind":"error","stem":"광합성을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지윤 — 「광합성은 식물의 잎에서만 일어나고 다른 곳에선 절대 안 일어나.」","correct":true,"mis_target":"SC6-1-u3-X29"},{"t":"민규 — 「광합성은 주로 잎에서 가장 활발하게 일어나.」","mis":"SC6-1-u3-X29"},{"t":"세린 — 「광합성에는 빛과 이산화 탄소, 물이 필요해.」","mis":"SC6-1-u3-X30"}],"explanation":["주로 잎이에요.","잎에서만은 아니에요.","지윤의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L05_challenge#1','sci',6,1,'u3','L05','g6_1_sci_u3_L05_challenge','lesson_challenge','SC6-1-u3-C15',2,'mc','auto','광합성에 관한 설명으로 옳은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X30']::text[],false,'{"seq":1,"concept":"SC6-1-u3-C15","difficulty":2,"kind":"mc","stem":"광합성에 관한 설명으로 옳은 것은 어느 것인가요?","options":[{"t":"식물이 빛을 이용해 이산화 탄소와 물로 양분을 만드는 것이다","correct":true},{"t":"식물이 빛을 이용해 물을 만드는 것이다","mis":"SC6-1-u3-X30"},{"t":"식물이 산소와 이산화 탄소로 양분을 만드는 것이다","mis":"SC6-1-u3-X30"},{"t":"식물이 어둠 속에서 양분을 만드는 것이다","mis":"SC6-1-u3-X30"}],"explanation":["재료를 떠올려요.","이산화 탄소와 물이에요.","빛으로 양분을 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L05_challenge#2','sci',6,1,'u3','L05','g6_1_sci_u3_L05_challenge','lesson_challenge','SC6-1-u3-C16',2,'mc','auto','광합성으로 만든 양분 확인 실험에서 잎을 에탄올에 넣어 뜨거운 물에 담가 두는 까닭은 무엇인가요?',ARRAY['SC6-1-u3-X30','SC6-1-u3-X32','SC6-1-u3-X33']::text[],false,'{"seq":2,"concept":"SC6-1-u3-C16","difficulty":2,"kind":"mc","stem":"광합성으로 만든 양분 확인 실험에서 잎을 에탄올에 넣어 뜨거운 물에 담가 두는 까닭은 무엇인가요?","options":[{"t":"잎의 초록색을 빼서 색깔 변화를 잘 보이게 하려고","correct":true},{"t":"잎에 양분을 새로 만들어 주려고","mis":"SC6-1-u3-X30"},{"t":"포일을 씌운 잎과 다르게 하려고","mis":"SC6-1-u3-X32"},{"t":"에탄올 냄새를 맡아 보려고","mis":"SC6-1-u3-X33"}],"explanation":["잎이 초록색이에요.","색을 빼면 잘 보여요.","색깔 변화를 봐요."],"asset":{"type":"passage","lines":["① 잎 하나에 알루미늄 포일을 씌우고 화분을 햇빛이 드는 곳에 둔다.","② 하루 뒤 포일을 씌운 잎과 씌우지 않은 잎을 하나씩 딴다.","③ 두 잎을 뜨거운 물에 잠깐 담갔다가 에탄올이 든 시험관에 넣는다.","④ 시험관을 뜨거운 물에 담가 잎의 초록색을 뺀다.","⑤ 잎을 물에 헹군 뒤 녹말을 만나면 색이 변하는 용액을 떨어뜨린다."],"title":"광합성으로 만든 양분 확인 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L05_challenge#3','sci',6,1,'u3','L05','g6_1_sci_u3_L05_challenge','lesson_challenge','SC6-1-u3-C16',3,'mc','auto','실험 결과로 알 수 있는 것은 어느 것인가요?',ARRAY['SC6-1-u3-X31','SC6-1-u3-X30']::text[],false,'{"seq":3,"concept":"SC6-1-u3-C16","difficulty":3,"kind":"mc","stem":"실험 결과로 알 수 있는 것은 어느 것인가요?","options":[{"t":"햇빛을 받은 잎에서 녹말과 같은 양분이 만들어진다","correct":true},{"t":"포일을 씌운 잎에서 양분이 더 많이 만들어진다","mis":"SC6-1-u3-X31"},{"t":"빛과 상관없이 두 잎 모두 양분을 만든다","mis":"SC6-1-u3-X31"},{"t":"잎은 양분을 만들지 않고 뿌리에서 받는다","mis":"SC6-1-u3-X30"}],"explanation":["청람색이 된 잎을 봐요.","햇빛을 받은 잎이에요.","양분이 만들어졌어요."],"asset":{"type":"passage","lines":["포일을 씌우지 않은 잎 — 용액을 떨어뜨린 곳이 청람색으로 변함","포일을 씌운 잎 — 색깔 변화가 없음"],"title":"실험 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L05_challenge#4','sci',6,1,'u3','L05','g6_1_sci_u3_L05_challenge','lesson_challenge','SC6-1-u3-C17',3,'mc','auto','많은 식물의 잎이 납작하고 넓은 까닭을 잎이 하는 일과 관련지어 말한 것은 어느 것인가요?',ARRAY['SC6-1-u3-X22','SC6-1-u3-X36']::text[],false,'{"seq":4,"concept":"SC6-1-u3-C17","difficulty":3,"kind":"mc","stem":"많은 식물의 잎이 납작하고 넓은 까닭을 잎이 하는 일과 관련지어 말한 것은 어느 것인가요?","options":[{"t":"빛을 받는 면이 넓어 광합성이 잘 일어나기 때문이다","correct":true},{"t":"넓을수록 물을 땅에서 잘 흡수하기 때문이다","mis":"SC6-1-u3-X22"},{"t":"잎의 모양은 하는 일과 상관없기 때문이다","mis":"SC6-1-u3-X36"},{"t":"넓어야 꽃가루가 잘 붙기 때문이다","mis":"SC6-1-u3-X36"}],"explanation":["잎은 빛을 받아요.","넓으면 빛을 많이 받아요.","광합성이 잘 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L05_challenge#5','sci',6,1,'u3','L05','g6_1_sci_u3_L05_challenge','lesson_challenge','SC6-1-u3-C16',3,'error','auto','실험을 마친 뒤 모둠 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u3-X31','SC6-1-u3-X32','SC6-1-u3-X33']::text[],false,'{"seq":5,"concept":"SC6-1-u3-C16","difficulty":3,"kind":"error","stem":"실험을 마친 뒤 모둠 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「포일을 씌운 잎이 청람색으로 변했으니 그 잎이 양분을 만든 거야.」","correct":true,"mis_target":"SC6-1-u3-X31"},{"t":"하린 — 「포일은 잎에 닿는 빛을 막으려고 씌웠어.」","mis":"SC6-1-u3-X32"},{"t":"준서 — 「뜨거운 물에 손이 데지 않게 조심했어.」","mis":"SC6-1-u3-X33"}],"explanation":["결과를 다시 봐요.","변한 잎은 햇빛을 받은 잎이에요.","도윤의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["포일을 씌우지 않은 잎 — 용액을 떨어뜨린 곳이 청람색으로 변함","포일을 씌운 잎 — 색깔 변화가 없음"],"title":"실험 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L05_challenge#6','sci',6,1,'u3','L05','g6_1_sci_u3_L05_challenge','lesson_challenge','SC6-1-u3-C15',3,'ox','auto','식물은 햇빛을 많이 받을수록 언제나 더 잘 자라요.',ARRAY['SC6-1-u3-X34']::text[],false,'{"seq":6,"concept":"SC6-1-u3-C15","difficulty":3,"kind":"ox","stem":"식물은 햇빛을 많이 받을수록 언제나 더 잘 자라요.","answer":"X","reason_options":[{"t":"식물마다 알맞은 빛의 양이 달라 무조건 많다고 좋은 것은 아니기 때문에","correct":true},{"t":"햇빛만 많으면 물과 이산화 탄소는 필요 없기 때문에","mis":"SC6-1-u3-X34"}],"mis":"SC6-1-u3-X34","explanation":["빛이 필요해요.","하지만 알맞은 양이 달라요.","언제나 그렇진 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L05_challenge#7','sci',6,1,'u3','L05','g6_1_sci_u3_L05_challenge','lesson_challenge','SC6-1-u3-C15',3,'mc','auto','초록색을 띠는 어린 줄기에서도 광합성이 일어날 수 있다는 말을 듣고 바르게 정리한 것은 어느 것인가요?',ARRAY['SC6-1-u3-X29','SC6-1-u3-X30']::text[],false,'{"seq":7,"concept":"SC6-1-u3-C15","difficulty":3,"kind":"mc","stem":"초록색을 띠는 어린 줄기에서도 광합성이 일어날 수 있다는 말을 듣고 바르게 정리한 것은 어느 것인가요?","options":[{"t":"광합성은 주로 잎에서 활발하지만 잎에서만 일어나는 것은 아니다","correct":true},{"t":"광합성은 잎에서만 일어나므로 이 말은 틀렸다","mis":"SC6-1-u3-X29"},{"t":"광합성은 줄기에서 가장 활발하게 일어난다","mis":"SC6-1-u3-X29"},{"t":"초록색 줄기는 빛이 없어도 양분을 만든다","mis":"SC6-1-u3-X30"}],"explanation":["초록색 부분이에요.","주로 잎에서 일어나요.","잎에서만은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L05_challenge#8','sci',6,1,'u3','L05','g6_1_sci_u3_L05_challenge','lesson_challenge','SC6-1-u3-C17',4,'mc','auto','잎에서 만든 양분이 식물에서 쓰이는 모습을 차례대로 바르게 말한 것은 어느 것인가요?',ARRAY['SC6-1-u3-X19','SC6-1-u3-X35','SC6-1-u3-X27']::text[],false,'{"seq":8,"concept":"SC6-1-u3-C17","difficulty":4,"kind":"mc","stem":"잎에서 만든 양분이 식물에서 쓰이는 모습을 차례대로 바르게 말한 것은 어느 것인가요?","options":[{"t":"잎에서 만들어짐 → 줄기를 통해 식물 전체로 이동 → 각 기관에서 쓰이고 남은 양분은 저장","correct":true},{"t":"뿌리에서 만들어짐 → 줄기를 통해 잎으로 이동 → 잎에서만 쓰임","mis":"SC6-1-u3-X19"},{"t":"잎에서 만들어짐 → 잎에서만 쓰임 → 남은 양분은 사라짐","mis":"SC6-1-u3-X35"},{"t":"줄기에서 만들어짐 → 꽃으로 이동 → 열매에서 물로 바뀜","mis":"SC6-1-u3-X27"}],"explanation":["만드는 곳은 잎이에요.","줄기를 통해 이동해요.","남으면 저장해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L05_challenge#9','sci',6,1,'u3','L05','g6_1_sci_u3_L05_challenge','lesson_challenge','SC6-1-u3-C16',4,'mc','auto','이 실험을 비가 오고 어두운 날에만 했다면 결과가 어떻게 되었을지 가장 알맞게 예상한 것은 어느 것인가요?',ARRAY['SC6-1-u3-X31','SC6-1-u3-X30']::text[],false,'{"seq":9,"concept":"SC6-1-u3-C16","difficulty":4,"kind":"mc","stem":"이 실험을 비가 오고 어두운 날에만 했다면 결과가 어떻게 되었을지 가장 알맞게 예상한 것은 어느 것인가요?","options":[{"t":"포일을 씌우지 않은 잎도 빛을 덜 받아 색깔 변화가 뚜렷하지 않을 수 있다","correct":true},{"t":"두 잎 모두 더 진한 청람색으로 변한다","mis":"SC6-1-u3-X31"},{"t":"포일을 씌운 잎만 청람색으로 변한다","mis":"SC6-1-u3-X31"},{"t":"빛은 상관없으니 결과는 똑같이 뚜렷하다","mis":"SC6-1-u3-X30"}],"explanation":["빛이 적은 날이에요.","양분이 덜 만들어져요.","변화가 뚜렷하지 않을 수 있어요."],"asset":{"type":"passage","lines":["① 잎 하나에 알루미늄 포일을 씌우고 화분을 햇빛이 드는 곳에 둔다.","② 하루 뒤 포일을 씌운 잎과 씌우지 않은 잎을 하나씩 딴다.","③ 두 잎을 뜨거운 물에 잠깐 담갔다가 에탄올이 든 시험관에 넣는다.","④ 시험관을 뜨거운 물에 담가 잎의 초록색을 뺀다.","⑤ 잎을 물에 헹군 뒤 녹말을 만나면 색이 변하는 용액을 떨어뜨린다."],"title":"광합성으로 만든 양분 확인 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L05_challenge#10','sci',6,1,'u3','L05','g6_1_sci_u3_L05_challenge','lesson_challenge','SC6-1-u3-C16',4,'essay','teacher','광합성으로 만든 양분 확인 실험에서 포일을 씌우지 않은 잎에 용액을 떨어뜨렸을 때 나타난 색깔 변화와, 이를 통해 알 수 있는 사실을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-1-u3-C16","difficulty":4,"kind":"essay","stem":"광합성으로 만든 양분 확인 실험에서 포일을 씌우지 않은 잎에 용액을 떨어뜨렸을 때 나타난 색깔 변화와, 이를 통해 알 수 있는 사실을 쓰세요.","answer_guide":{"answer":"예: 용액을 떨어뜨린 곳이 청람색으로 변한다. 햇빛을 받은 잎에서는 녹말과 같은 양분이 만들어진다는 것을 알 수 있다.","scoring_points":["청람색으로 변한다고 썼는가","햇빛을 받은 잎에서 양분이 만들어진다고 썼는가"]},"explanation":["결과를 떠올려요.","청람색이에요.","빛을 받은 잎이 양분을 만들어요."],"asset":{"type":"passage","lines":["포일을 씌우지 않은 잎 — 용액을 떨어뜨린 곳이 청람색으로 변함","포일을 씌운 잎 — 색깔 변화가 없음"],"title":"실험 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L06_basic#1','sci',6,1,'u3','L06','g6_1_sci_u3_L06_basic','lesson_basic','SC6-1-u3-C18',1,'sa','auto','잎에 도달한 물의 일부가 수증기가 되어 식물 밖으로 빠져나가는 것을 무엇이라고 하나요? 다섯 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC6-1-u3-C18","difficulty":1,"kind":"sa","stem":"잎에 도달한 물의 일부가 수증기가 되어 식물 밖으로 빠져나가는 것을 무엇이라고 하나요? 다섯 글자로 쓰세요.","answer":["증산 작용","증산작용"],"explanation":["물이 수증기로 빠져나가요.","다섯 글자예요.","증산 작용이에요."],"mis":"SC6-1-u3-X37"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L06_basic#2','sci',6,1,'u3','L06','g6_1_sci_u3_L06_basic','lesson_basic','SC6-1-u3-C20',1,'mc','auto','잎의 표면에 있는 아주 작은 구멍의 이름은 어느 것인가요?',ARRAY['SC6-1-u3-X38']::text[],false,'{"seq":2,"concept":"SC6-1-u3-C20","difficulty":1,"kind":"mc","stem":"잎의 표면에 있는 아주 작은 구멍의 이름은 어느 것인가요?","options":[{"t":"기공","correct":true},{"t":"잎맥","mis":"SC6-1-u3-X38"},{"t":"뿌리털","mis":"SC6-1-u3-X38"},{"t":"세포벽","mis":"SC6-1-u3-X38"}],"explanation":["아주 작은 구멍이에요.","물이 빠져나가요.","기공이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L06_basic#3','sci',6,1,'u3','L06','g6_1_sci_u3_L06_basic','lesson_basic','SC6-1-u3-C20',1,'ox','auto','기공은 대부분 잎의 뒷면에 있어요.',ARRAY['SC6-1-u3-X38']::text[],false,'{"seq":3,"concept":"SC6-1-u3-C20","difficulty":1,"kind":"ox","stem":"기공은 대부분 잎의 뒷면에 있어요.","answer":"O","reason_options":[{"t":"그래서 증산 작용이 주로 잎의 뒷면에서 일어나기 때문에","correct":true},{"t":"기공은 모두 줄기에 있기 때문에","mis":"SC6-1-u3-X38"}],"mis":"SC6-1-u3-X38","explanation":["기공의 자리예요.","대부분 뒷면이에요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L06_basic#4','sci',6,1,'u3','L06','g6_1_sci_u3_L06_basic','lesson_basic','SC6-1-u3-C19',1,'mc','auto','푸른색 염화 코발트 종이가 물을 흡수하면 무슨 색으로 변하나요?',ARRAY['SC6-1-u3-X39','SC6-1-u3-X31']::text[],false,'{"seq":4,"concept":"SC6-1-u3-C19","difficulty":1,"kind":"mc","stem":"푸른색 염화 코발트 종이가 물을 흡수하면 무슨 색으로 변하나요?","options":[{"t":"붉은색","correct":true},{"t":"푸른색 그대로","mis":"SC6-1-u3-X39"},{"t":"흰색","mis":"SC6-1-u3-X39"},{"t":"청람색","mis":"SC6-1-u3-X31"}],"explanation":["물을 흡수했어요.","색이 바뀌어요.","붉은색이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L06_basic#5','sci',6,1,'u3','L06','g6_1_sci_u3_L06_basic','lesson_basic','SC6-1-u3-C19',2,'mc','auto','증산 작용 확인 실험 기록에서 10분 뒤 붉은색으로 변한 종이는 어느 것인가요?',ARRAY['SC6-1-u3-X39','SC6-1-u3-X37']::text[],false,'{"seq":5,"concept":"SC6-1-u3-C19","difficulty":2,"kind":"mc","stem":"증산 작용 확인 실험 기록에서 10분 뒤 붉은색으로 변한 종이는 어느 것인가요?","options":[{"t":"잎 뒷면에 붙인 종이 ㉯","correct":true},{"t":"빈 페트리 접시에 붙인 종이 ㉮","mis":"SC6-1-u3-X39"},{"t":"두 종이 모두","mis":"SC6-1-u3-X39"},{"t":"두 종이 모두 그대로","mis":"SC6-1-u3-X37"}],"explanation":["기록을 봐요.","잎 뒷면의 종이예요.","㉯가 붉어졌어요."],"asset":{"type":"passage","lines":["푸른색 염화 코발트 종이는 물을 흡수하면 붉은색으로 변한다.","종이 ㉮ — 빈 페트리 접시에 붙임","종이 ㉯ — 식물 잎 뒷면에 붙임","햇빛이 드는 곳에 두고 10분 뒤 — ㉮ 푸른색 그대로, ㉯ 붉은색"],"title":"증산 작용 확인 실험 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L06_basic#6','sci',6,1,'u3','L06','g6_1_sci_u3_L06_basic','lesson_basic','SC6-1-u3-C19',2,'mc','auto','증산 작용 확인 실험에서 빈 페트리 접시에도 종이 ㉮를 붙인 까닭은 무엇인가요?',ARRAY['SC6-1-u3-X39']::text[],false,'{"seq":6,"concept":"SC6-1-u3-C19","difficulty":2,"kind":"mc","stem":"증산 작용 확인 실험에서 빈 페트리 접시에도 종이 ㉮를 붙인 까닭은 무엇인가요?","options":[{"t":"잎에 붙인 종이와 결과를 견주기 위해서","correct":true},{"t":"페트리 접시도 물을 내보내기 때문에","mis":"SC6-1-u3-X39"},{"t":"종이를 아끼려고","mis":"SC6-1-u3-X39"},{"t":"잎보다 더 빨리 붉어지게 하려고","mis":"SC6-1-u3-X39"}],"explanation":["잎 없이 붙였어요.","견주기 위한 종이예요.","차이를 봐요."],"asset":{"type":"passage","lines":["푸른색 염화 코발트 종이는 물을 흡수하면 붉은색으로 변한다.","종이 ㉮ — 빈 페트리 접시에 붙임","종이 ㉯ — 식물 잎 뒷면에 붙임","햇빛이 드는 곳에 두고 10분 뒤 — ㉮ 푸른색 그대로, ㉯ 붉은색"],"title":"증산 작용 확인 실험 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L06_basic#7','sci',6,1,'u3','L06','g6_1_sci_u3_L06_basic','lesson_basic','SC6-1-u3-C21',2,'mc','auto','증산 작용이 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X37','SC6-1-u3-X41','SC6-1-u3-X30']::text[],false,'{"seq":7,"concept":"SC6-1-u3-C21","difficulty":2,"kind":"mc","stem":"증산 작용이 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"뿌리에서 흡수한 물이 잎까지 올라오게 한다","correct":true},{"t":"공기 중의 수증기를 식물 안으로 끌어들인다","mis":"SC6-1-u3-X37"},{"t":"물을 쓸모없이 버리기만 한다","mis":"SC6-1-u3-X41"},{"t":"잎에서 양분을 만든다","mis":"SC6-1-u3-X30"}],"explanation":["물이 빠져나가요.","그래서 물이 올라와요.","물을 잎까지 끌어올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L06_basic#8','sci',6,1,'u3','L06','g6_1_sci_u3_L06_basic','lesson_basic','SC6-1-u3-C18',2,'mc','auto','식물이 많은 온실 안이 바깥보다 더 습한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X37','SC6-1-u3-X38','SC6-1-u3-X41']::text[],false,'{"seq":8,"concept":"SC6-1-u3-C18","difficulty":2,"kind":"mc","stem":"식물이 많은 온실 안이 바깥보다 더 습한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"많은 식물의 잎에서 물이 수증기가 되어 빠져나오기 때문이다","correct":true},{"t":"식물이 공기 중의 수증기를 모두 빨아들이기 때문이다","mis":"SC6-1-u3-X37"},{"t":"식물의 뿌리가 공기 중으로 물을 내보내기 때문이다","mis":"SC6-1-u3-X38"},{"t":"온실의 식물은 증산 작용을 하지 않기 때문이다","mis":"SC6-1-u3-X41"}],"explanation":["식물이 많아요.","잎에서 수증기가 나와요.","그래서 습해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L06_basic#9','sci',6,1,'u3','L06','g6_1_sci_u3_L06_basic','lesson_basic','SC6-1-u3-C19',2,'ox','auto','실험에 쓴 푸른색 염화 코발트 종이는 손으로 집지 않고 핀셋으로 집어요.',ARRAY['SC6-1-u3-X39']::text[],false,'{"seq":9,"concept":"SC6-1-u3-C19","difficulty":2,"kind":"ox","stem":"실험에 쓴 푸른색 염화 코발트 종이는 손으로 집지 않고 핀셋으로 집어요.","answer":"O","reason_options":[{"t":"손의 물기가 묻으면 종이 색이 변해 결과를 알 수 없기 때문에","correct":true},{"t":"핀셋으로 집어야 종이가 더 푸르러지기 때문에","mis":"SC6-1-u3-X39"}],"mis":"SC6-1-u3-X39","explanation":["종이는 물에 반응해요.","손에도 물기가 있어요.","핀셋으로 집어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L06_basic#10','sci',6,1,'u3','L06','g6_1_sci_u3_L06_basic','lesson_basic','SC6-1-u3-C18',3,'error','auto','증산 작용을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u3-X37','SC6-1-u3-X38']::text[],false,'{"seq":10,"concept":"SC6-1-u3-C18","difficulty":3,"kind":"error","stem":"증산 작용을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태린 — 「증산 작용은 공기 중의 수증기가 잎으로 들어오는 거야.」","correct":true,"mis_target":"SC6-1-u3-X37"},{"t":"나은 — 「잎에 도달한 물의 일부가 수증기가 되어 빠져나가.」","mis":"SC6-1-u3-X37"},{"t":"우진 — 「기공을 통해 물이 식물 밖으로 나가.」","mis":"SC6-1-u3-X38"}],"explanation":["물은 어느 쪽으로 가나요?","식물 밖으로 나가요.","태린의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L06_challenge#1','sci',6,1,'u3','L06','g6_1_sci_u3_L06_challenge','lesson_challenge','SC6-1-u3-C20',2,'mc','auto','현미경으로 본 잎의 표면에서 두 세포 사이의 아주 작은 구멍은 무엇이고, 무슨 일과 관계있나요?',ARRAY['SC6-1-u3-X37','SC6-1-u3-X38']::text[],false,'{"seq":1,"concept":"SC6-1-u3-C20","difficulty":2,"kind":"mc","stem":"현미경으로 본 잎의 표면에서 두 세포 사이의 아주 작은 구멍은 무엇이고, 무슨 일과 관계있나요?","options":[{"t":"기공 — 잎에 도달한 물이 수증기가 되어 빠져나가는 일","correct":true},{"t":"기공 — 땅속의 물을 흡수하는 일","mis":"SC6-1-u3-X37"},{"t":"잎맥 — 양분을 저장하는 일","mis":"SC6-1-u3-X38"},{"t":"핵 — 물이 빠져나가는 일","mis":"SC6-1-u3-X38"}],"explanation":["아주 작은 구멍이에요.","기공이에요.","물이 빠져나가요."],"asset":{"type":"passage","lines":["강낭콩 모양의 세포 두 개가 마주 보고 있다.","두 세포 사이에 아주 작은 구멍이 있다.","그 둘레를 각진 모양의 세포들이 둘러싸고 있다."],"title":"현미경으로 본 잎의 표면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L06_challenge#2','sci',6,1,'u3','L06','g6_1_sci_u3_L06_challenge','lesson_challenge','SC6-1-u3-C19',2,'mc','auto','증산 작용 확인 실험 기록으로 알 수 있는 것은 어느 것인가요?',ARRAY['SC6-1-u3-X39','SC6-1-u3-X37','SC6-1-u3-X41']::text[],false,'{"seq":2,"concept":"SC6-1-u3-C19","difficulty":2,"kind":"mc","stem":"증산 작용 확인 실험 기록으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"잎을 통해 물이 식물 밖으로 빠져나간다","correct":true},{"t":"페트리 접시에서 물이 나온다","mis":"SC6-1-u3-X39"},{"t":"공기 중의 수증기가 잎으로 들어간다","mis":"SC6-1-u3-X37"},{"t":"잎은 물과 상관이 없다","mis":"SC6-1-u3-X41"}],"explanation":["㉯만 붉어졌어요.","잎에서 물이 나왔어요.","물이 빠져나가요."],"asset":{"type":"passage","lines":["푸른색 염화 코발트 종이는 물을 흡수하면 붉은색으로 변한다.","종이 ㉮ — 빈 페트리 접시에 붙임","종이 ㉯ — 식물 잎 뒷면에 붙임","햇빛이 드는 곳에 두고 10분 뒤 — ㉮ 푸른색 그대로, ㉯ 붉은색"],"title":"증산 작용 확인 실험 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L06_challenge#3','sci',6,1,'u3','L06','g6_1_sci_u3_L06_challenge','lesson_challenge','SC6-1-u3-C19',3,'mc','auto','푸른색 염화 코발트 종이를 잎의 앞면이 아니라 뒷면에 붙이는 까닭은 무엇인가요?',ARRAY['SC6-1-u3-X37','SC6-1-u3-X38','SC6-1-u3-X39']::text[],false,'{"seq":3,"concept":"SC6-1-u3-C19","difficulty":3,"kind":"mc","stem":"푸른색 염화 코발트 종이를 잎의 앞면이 아니라 뒷면에 붙이는 까닭은 무엇인가요?","options":[{"t":"기공이 대부분 잎 뒷면에 있어 증산 작용이 뒷면에서 많이 일어나기 때문이다","correct":true},{"t":"잎 뒷면은 물을 흡수하는 곳이기 때문이다","mis":"SC6-1-u3-X37"},{"t":"잎 앞면에서 증산 작용이 더 많이 일어나기 때문이다","mis":"SC6-1-u3-X38"},{"t":"뒷면에 붙여야 종이가 덜 붉어지기 때문이다","mis":"SC6-1-u3-X39"}],"explanation":["기공은 어디에 많나요?","대부분 뒷면이에요.","그래서 뒷면에 붙여요."],"asset":{"type":"passage","lines":["푸른색 염화 코발트 종이는 물을 흡수하면 붉은색으로 변한다.","종이 ㉮ — 빈 페트리 접시에 붙임","종이 ㉯ — 식물 잎 뒷면에 붙임","햇빛이 드는 곳에 두고 10분 뒤 — ㉮ 푸른색 그대로, ㉯ 붉은색"],"title":"증산 작용 확인 실험 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L06_challenge#4','sci',6,1,'u3','L06','g6_1_sci_u3_L06_challenge','lesson_challenge','SC6-1-u3-C21',3,'mc','auto','증발과 증산 작용을 바르게 견준 것은 어느 것인가요?',ARRAY['SC6-1-u3-X40','SC6-1-u3-X37']::text[],false,'{"seq":4,"concept":"SC6-1-u3-C21","difficulty":3,"kind":"mc","stem":"증발과 증산 작용을 바르게 견준 것은 어느 것인가요?","options":[{"t":"물이 수증기가 되는 점은 같고, 증산 작용은 그 일이 식물의 잎에서 일어나는 것이다","correct":true},{"t":"증발과 증산 작용은 전혀 다른 현상이다","mis":"SC6-1-u3-X40"},{"t":"증산 작용은 수증기가 물로 바뀌는 것이다","mis":"SC6-1-u3-X37"},{"t":"증발은 식물의 기공에서만 일어난다","mis":"SC6-1-u3-X40"}],"explanation":["물이 수증기가 돼요.","그 점은 같아요.","증산은 잎에서 일어나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L06_challenge#5','sci',6,1,'u3','L06','g6_1_sci_u3_L06_challenge','lesson_challenge','SC6-1-u3-C21',3,'error','auto','증산 작용이 하는 일을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u3-X41']::text[],false,'{"seq":5,"concept":"SC6-1-u3-C21","difficulty":3,"kind":"error","stem":"증산 작용이 하는 일을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하준 — 「증산 작용은 아까운 물을 버리기만 하는 쓸모없는 일이야.」","correct":true,"mis_target":"SC6-1-u3-X41"},{"t":"소미 — 「증산 작용 덕분에 뿌리의 물이 잎까지 올라와.」","mis":"SC6-1-u3-X41"},{"t":"지후 — 「증산 작용은 식물의 온도를 조절해.」","mis":"SC6-1-u3-X41"}],"explanation":["하는 일을 떠올려요.","물을 끌어올리고 온도를 조절해요.","하준의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L06_challenge#6','sci',6,1,'u3','L06','g6_1_sci_u3_L06_challenge','lesson_challenge','SC6-1-u3-C21',3,'ox','auto','물이 부족한 사막에 사는 식물은 잎이 넓은 것이 살아가기에 유리해요.',ARRAY['SC6-1-u3-X41']::text[],false,'{"seq":6,"concept":"SC6-1-u3-C21","difficulty":3,"kind":"ox","stem":"물이 부족한 사막에 사는 식물은 잎이 넓은 것이 살아가기에 유리해요.","answer":"X","reason_options":[{"t":"잎이 넓으면 증산 작용으로 물을 많이 잃어 물이 부족해질 수 있기 때문에","correct":true},{"t":"잎이 넓어야 공기 중의 물을 더 많이 빨아들이기 때문에","mis":"SC6-1-u3-X41"}],"mis":"SC6-1-u3-X41","explanation":["사막은 물이 부족해요.","넓은 잎은 물을 많이 잃어요.","좁은 잎이 유리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L06_challenge#7','sci',6,1,'u3','L06','g6_1_sci_u3_L06_challenge','lesson_challenge','SC6-1-u3-C18',3,'mc','auto','뿌리에서 흡수한 물이 식물 밖으로 나가기까지의 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X49','SC6-1-u3-X38','SC6-1-u3-X37']::text[],false,'{"seq":7,"concept":"SC6-1-u3-C18","difficulty":3,"kind":"mc","stem":"뿌리에서 흡수한 물이 식물 밖으로 나가기까지의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"뿌리 → 줄기 → 잎 → 기공을 통해 밖으로","correct":true},{"t":"잎 → 줄기 → 뿌리 → 땅속으로","mis":"SC6-1-u3-X49"},{"t":"뿌리 → 기공 → 줄기 → 잎","mis":"SC6-1-u3-X38"},{"t":"기공 → 잎 → 줄기 → 뿌리","mis":"SC6-1-u3-X37"}],"explanation":["물은 뿌리에서 출발해요.","줄기를 지나 잎에 가요.","기공으로 나가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L06_challenge#8','sci',6,1,'u3','L06','g6_1_sci_u3_L06_challenge','lesson_challenge','SC6-1-u3-C21',4,'mc','auto','더운 여름날 큰 나무 그늘이 특히 시원하게 느껴지는 까닭과 가장 관계있는 것은 어느 것인가요?',ARRAY['SC6-1-u3-X37','SC6-1-u3-X41','SC6-1-u3-X40']::text[],false,'{"seq":8,"concept":"SC6-1-u3-C21","difficulty":4,"kind":"mc","stem":"더운 여름날 큰 나무 그늘이 특히 시원하게 느껴지는 까닭과 가장 관계있는 것은 어느 것인가요?","options":[{"t":"잎에서 물이 수증기가 되어 빠져나가며 식물의 온도를 조절하기 때문이다","correct":true},{"t":"나무가 공기 중의 수증기를 빨아들이기 때문이다","mis":"SC6-1-u3-X37"},{"t":"나무뿌리가 땅속 물을 모두 가두기 때문이다","mis":"SC6-1-u3-X41"},{"t":"증발과 증산 작용은 전혀 다른 일이라 상관없다","mis":"SC6-1-u3-X40"}],"explanation":["잎에서 무슨 일이 일어나요?","물이 수증기로 나가요.","온도를 조절해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L06_challenge#9','sci',6,1,'u3','L06','g6_1_sci_u3_L06_challenge','lesson_challenge','SC6-1-u3-C19',4,'mc','auto','잎이 달린 식물 두 그루 가운데 한 그루만 잎을 모두 떼고, 줄기를 같은 양의 물에 꽂아 햇빛에 두었어요. 하루 뒤 물이 더 많이 줄어든 쪽과 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X41','SC6-1-u3-X38','SC6-1-u3-X37']::text[],false,'{"seq":9,"concept":"SC6-1-u3-C19","difficulty":4,"kind":"mc","stem":"잎이 달린 식물 두 그루 가운데 한 그루만 잎을 모두 떼고, 줄기를 같은 양의 물에 꽂아 햇빛에 두었어요. 하루 뒤 물이 더 많이 줄어든 쪽과 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"잎이 있는 쪽 — 잎에서 증산 작용이 일어나 물이 많이 빠져나갔기 때문이다","correct":true},{"t":"잎을 뗀 쪽 — 잎이 없으면 물을 더 많이 흡수하기 때문이다","mis":"SC6-1-u3-X41"},{"t":"두 쪽이 같다 — 증산 작용은 줄기에서 주로 일어나기 때문이다","mis":"SC6-1-u3-X38"},{"t":"잎이 있는 쪽 — 잎이 공기 중 수증기를 빨아들였기 때문이다","mis":"SC6-1-u3-X37"}],"explanation":["잎이 있나 없나예요.","증산 작용은 잎에서 일어나요.","잎이 있는 쪽이 더 줄어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L06_challenge#10','sci',6,1,'u3','L06','g6_1_sci_u3_L06_challenge','lesson_challenge','SC6-1-u3-C18',4,'essay','teacher','「잎」, 「물」, 「수증기」를 모두 넣어 증산 작용을 설명하는 글을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-1-u3-C18","difficulty":4,"kind":"essay","stem":"「잎」, 「물」, 「수증기」를 모두 넣어 증산 작용을 설명하는 글을 쓰세요.","answer_guide":{"answer":"예: 뿌리에서 흡수해 잎에 도달한 물의 일부가 수증기가 되어 잎의 기공을 통해 식물 밖으로 빠져나가는 것을 증산 작용이라고 한다.","scoring_points":["잎에 도달한 물이라고 썼는가","수증기가 되어 밖으로 빠져나간다고 썼는가","세 낱말을 모두 넣었는가"]},"explanation":["세 낱말을 넣어요.","물이 수증기가 돼요.","잎 밖으로 나가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L07_basic#1','sci',6,1,'u3','L07','g6_1_sci_u3_L07_basic','lesson_basic','SC6-1-u3-C23',1,'mc','auto','꽃이 하는 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X45']::text[],false,'{"seq":1,"concept":"SC6-1-u3-C23","difficulty":1,"kind":"mc","stem":"꽃이 하는 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"씨를 만든다","correct":true},{"t":"양분을 만든다","mis":"SC6-1-u3-X45"},{"t":"물을 흡수한다","mis":"SC6-1-u3-X45"},{"t":"식물을 땅에 붙잡아 둔다","mis":"SC6-1-u3-X45"}],"explanation":["꽃에서 무엇이 생기나요?","씨가 생겨요.","꽃은 씨를 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L07_basic#2','sci',6,1,'u3','L07','g6_1_sci_u3_L07_basic','lesson_basic','SC6-1-u3-C23',1,'sa','auto','수술에 있는 꽃가루가 암술에 옮겨 붙는 과정을 무엇이라고 하나요? 다섯 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC6-1-u3-C23","difficulty":1,"kind":"sa","stem":"수술에 있는 꽃가루가 암술에 옮겨 붙는 과정을 무엇이라고 하나요? 다섯 글자로 쓰세요.","answer":["꽃가루받이"],"explanation":["꽃가루가 옮겨 붙어요.","다섯 글자예요.","꽃가루받이예요."],"mis":"SC6-1-u3-X44"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L07_basic#3','sci',6,1,'u3','L07','g6_1_sci_u3_L07_basic','lesson_basic','SC6-1-u3-C22',1,'mc','auto','꽃의 구조에서 암술 주변을 둘러싸고 있는 것은 어느 것인가요?',ARRAY['SC6-1-u3-X43']::text[],false,'{"seq":3,"concept":"SC6-1-u3-C22","difficulty":1,"kind":"mc","stem":"꽃의 구조에서 암술 주변을 둘러싸고 있는 것은 어느 것인가요?","options":[{"t":"수술","correct":true},{"t":"꽃받침","mis":"SC6-1-u3-X43"},{"t":"잎자루","mis":"SC6-1-u3-X43"},{"t":"열매","mis":"SC6-1-u3-X43"}],"explanation":["가운데 암술이 있어요.","그 둘레예요.","수술이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L07_basic#4','sci',6,1,'u3','L07','g6_1_sci_u3_L07_basic','lesson_basic','SC6-1-u3-C25',1,'ox','auto','꽃을 관찰할 때는 꽃을 맛보지 않아요.',ARRAY['SC6-1-u3-X47']::text[],false,'{"seq":4,"concept":"SC6-1-u3-C25","difficulty":1,"kind":"ox","stem":"꽃을 관찰할 때는 꽃을 맛보지 않아요.","answer":"O","reason_options":[{"t":"관찰하는 꽃을 입에 넣는 것은 위험할 수 있기 때문에","correct":true},{"t":"맛을 보아야 꽃의 구조를 정확히 알 수 있기 때문에","mis":"SC6-1-u3-X47"}],"mis":"SC6-1-u3-X47","explanation":["관찰 안전이에요.","입에 넣지 않아요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L07_basic#5','sci',6,1,'u3','L07','g6_1_sci_u3_L07_basic','lesson_basic','SC6-1-u3-C24',2,'mc','auto','열매가 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X46']::text[],false,'{"seq":5,"concept":"SC6-1-u3-C24","difficulty":2,"kind":"mc","stem":"열매가 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"씨를 보호하고 씨가 익으면 멀리 퍼지게 한다","correct":true},{"t":"씨를 새로 만든다","mis":"SC6-1-u3-X46"},{"t":"아무 일도 하지 않는다","mis":"SC6-1-u3-X46"},{"t":"물을 흡수해 줄기로 보낸다","mis":"SC6-1-u3-X46"}],"explanation":["열매 속에 씨가 있어요.","씨를 지켜요.","멀리 퍼뜨려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L07_basic#6','sci',6,1,'u3','L07','g6_1_sci_u3_L07_basic','lesson_basic','SC6-1-u3-C22',2,'mc','auto','달맞이꽃을 나누어 관찰한 기록에서 뒤로 젖혀져 있는 부분은 어느 것인가요?',ARRAY['SC6-1-u3-X43']::text[],false,'{"seq":6,"concept":"SC6-1-u3-C22","difficulty":2,"kind":"mc","stem":"달맞이꽃을 나누어 관찰한 기록에서 뒤로 젖혀져 있는 부분은 어느 것인가요?","options":[{"t":"꽃받침","correct":true},{"t":"암술","mis":"SC6-1-u3-X43"},{"t":"수술","mis":"SC6-1-u3-X43"},{"t":"꽃잎","mis":"SC6-1-u3-X43"}],"explanation":["기록을 봐요.","두 개씩 합쳐져 있어요.","꽃받침이에요."],"asset":{"type":"passage","lines":["암술 — 하나이고 윗부분이 네 갈래로 갈라져 있다.","수술 — 여러 개이고 노란색이다.","꽃잎 — 넉 장이 각각 떨어져 있다.","꽃받침 — 두 개씩 합쳐져 뒤로 젖혀져 있다."],"title":"달맞이꽃을 나누어 관찰한 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L07_basic#7','sci',6,1,'u3','L07','g6_1_sci_u3_L07_basic','lesson_basic','SC6-1-u3-C23',2,'mc','auto','꽃가루받이를 돕는 것으로 알맞지 않은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X44']::text[],false,'{"seq":7,"concept":"SC6-1-u3-C23","difficulty":2,"kind":"mc","stem":"꽃가루받이를 돕는 것으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"땅속의 뿌리털","correct":true},{"t":"곤충","mis":"SC6-1-u3-X44"},{"t":"바람","mis":"SC6-1-u3-X44"},{"t":"새","mis":"SC6-1-u3-X44"}],"explanation":["꽃가루를 옮겨요.","곤충·새·바람·물이에요.","뿌리털은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L07_basic#8','sci',6,1,'u3','L07','g6_1_sci_u3_L07_basic','lesson_basic','SC6-1-u3-C22',2,'ox','auto','모든 꽃은 암술, 수술, 꽃잎, 꽃받침을 모두 가지고 있어요.',ARRAY['SC6-1-u3-X42']::text[],false,'{"seq":8,"concept":"SC6-1-u3-C22","difficulty":2,"kind":"ox","stem":"모든 꽃은 암술, 수술, 꽃잎, 꽃받침을 모두 가지고 있어요.","answer":"X","reason_options":[{"t":"꽃의 종류에 따라 이 가운데 일부가 없는 꽃도 있기 때문에","correct":true},{"t":"꽃은 모두 네 부분이 있어야 피기 때문에","mis":"SC6-1-u3-X42"}],"mis":"SC6-1-u3-X42","explanation":["꽃은 다양해요.","일부가 없는 꽃도 있어요.","틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L07_basic#9','sci',6,1,'u3','L07','g6_1_sci_u3_L07_basic','lesson_basic','SC6-1-u3-C25',2,'mc','auto','씨앗도서관에서 할 수 있는 일로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X47']::text[],false,'{"seq":9,"concept":"SC6-1-u3-C25","difficulty":2,"kind":"mc","stem":"씨앗도서관에서 할 수 있는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"씨를 빌려 식물을 기른 뒤 거둔 씨를 돌려준다","correct":true},{"t":"씨를 빌린 뒤 돌려주지 않아도 된다","mis":"SC6-1-u3-X47"},{"t":"책만 빌려주고 씨는 다루지 않는다","mis":"SC6-1-u3-X47"},{"t":"씨를 맛보며 종류를 맞혀 본다","mis":"SC6-1-u3-X47"}],"explanation":["씨를 빌려줘요.","기른 뒤 돌려줘요.","씨를 지키는 곳이에요."],"asset":{"type":"passage","lines":["책을 빌려주듯 씨를 빌려준다.","빌린 씨로 식물을 길러 씨를 거두어 다시 돌려준다.","기르면서 잎·줄기·꽃의 변화를 관찰 일지로 남길 수 있다.","여러 가지 씨를 보관하고 전시하며 토종 씨를 지킨다."],"title":"씨앗도서관 안내문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L07_basic#10','sci',6,1,'u3','L07','g6_1_sci_u3_L07_basic','lesson_basic','SC6-1-u3-C23',3,'error','auto','꽃가루받이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u3-X44']::text[],false,'{"seq":10,"concept":"SC6-1-u3-C23","difficulty":3,"kind":"error","stem":"꽃가루받이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은채 — 「암술에 있는 꽃가루가 수술로 옮겨 가는 걸 꽃가루받이라고 해.」","correct":true,"mis_target":"SC6-1-u3-X44"},{"t":"도윤 — 「꽃가루받이가 되면 씨가 만들어져.」","mis":"SC6-1-u3-X44"},{"t":"하늘 — 「벌이나 나비가 꽃가루를 옮기기도 해.」","mis":"SC6-1-u3-X44"}],"explanation":["꽃가루는 어디 있나요?","수술에서 암술로 가요.","은채의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L07_challenge#1','sci',6,1,'u3','L07','g6_1_sci_u3_L07_challenge','lesson_challenge','SC6-1-u3-C22',2,'match','auto','달맞이꽃을 나누어 관찰한 기록에서 부분과 생김새를 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC6-1-u3-C22","difficulty":2,"kind":"match","stem":"달맞이꽃을 나누어 관찰한 기록에서 부분과 생김새를 알맞게 이으세요.","pairs":[{"l":"암술","r":"하나이고 윗부분이 네 갈래"},{"l":"꽃잎","r":"넉 장이 각각 떨어져 있음"},{"l":"꽃받침","r":"두 개씩 합쳐져 뒤로 젖혀짐"}],"mis":"SC6-1-u3-X43","explanation":["기록을 봐요.","부분마다 생김새가 달라요.","하나씩 이어요."],"asset":{"type":"passage","lines":["암술 — 하나이고 윗부분이 네 갈래로 갈라져 있다.","수술 — 여러 개이고 노란색이다.","꽃잎 — 넉 장이 각각 떨어져 있다.","꽃받침 — 두 개씩 합쳐져 뒤로 젖혀져 있다."],"title":"달맞이꽃을 나누어 관찰한 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L07_challenge#2','sci',6,1,'u3','L07','g6_1_sci_u3_L07_challenge','lesson_challenge','SC6-1-u3-C24',2,'mc','auto','복숭아꽃이 열매가 되는 과정의 ㉠~㉢을 바른 차례로 늘어놓은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X44','SC6-1-u3-X46']::text[],false,'{"seq":2,"concept":"SC6-1-u3-C24","difficulty":2,"kind":"mc","stem":"복숭아꽃이 열매가 되는 과정의 ㉠~㉢을 바른 차례로 늘어놓은 것은 어느 것인가요?","options":[{"t":"㉡ → ㉢ → ㉠","correct":true},{"t":"㉠ → ㉡ → ㉢","mis":"SC6-1-u3-X44"},{"t":"㉢ → ㉡ → ㉠","mis":"SC6-1-u3-X44"},{"t":"㉡ → ㉠ → ㉢","mis":"SC6-1-u3-X46"}],"explanation":["꽃가루받이가 먼저예요.","그다음 씨가 생겨요.","씨와 함께 열매가 자라요."],"asset":{"type":"passage","lines":["㉠ 씨가 자라면서 씨를 둘러싼 부분도 함께 자라 열매가 된다.","㉡ 꽃가루가 곤충의 도움으로 암술에 옮겨 붙는다.","㉢ 암술 속에 씨가 생긴다."],"title":"복숭아꽃이 열매가 되는 과정(차례가 섞임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L07_challenge#3','sci',6,1,'u3','L07','g6_1_sci_u3_L07_challenge','lesson_challenge','SC6-1-u3-C23',3,'mc','auto','꽃잎의 색이 화려한 꽃이 꽃가루받이를 할 때 유리한 점으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X45','SC6-1-u3-X44','SC6-1-u3-X46']::text[],false,'{"seq":3,"concept":"SC6-1-u3-C23","difficulty":3,"kind":"mc","stem":"꽃잎의 색이 화려한 꽃이 꽃가루받이를 할 때 유리한 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"벌이나 나비를 끌어들이기 좋아 꽃가루받이가 될 가능성이 높아진다","correct":true},{"t":"화려할수록 양분을 더 많이 만든다","mis":"SC6-1-u3-X45"},{"t":"화려하면 꽃가루가 암술에서 수술로 간다","mis":"SC6-1-u3-X44"},{"t":"화려한 꽃은 열매가 씨를 만든다","mis":"SC6-1-u3-X46"}],"explanation":["누가 꽃을 찾아오나요?","벌과 나비예요.","꽃가루받이가 잘 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L07_challenge#4','sci',6,1,'u3','L07','g6_1_sci_u3_L07_challenge','lesson_challenge','SC6-1-u3-C24',3,'mc','auto','열매가 만들어지는 과정을 바르게 말한 것은 어느 것인가요?',ARRAY['SC6-1-u3-X44','SC6-1-u3-X46','SC6-1-u3-X43']::text[],false,'{"seq":4,"concept":"SC6-1-u3-C24","difficulty":3,"kind":"mc","stem":"열매가 만들어지는 과정을 바르게 말한 것은 어느 것인가요?","options":[{"t":"씨가 자라면서 씨를 둘러싼 부분도 함께 자라 열매가 된다","correct":true},{"t":"열매가 먼저 생기고 그 뒤에 꽃가루받이가 일어난다","mis":"SC6-1-u3-X44"},{"t":"열매가 스스로 씨를 만들어 낸다","mis":"SC6-1-u3-X46"},{"t":"꽃받침이 그대로 굵어져 씨가 된다","mis":"SC6-1-u3-X43"}],"explanation":["씨가 먼저 생겨요.","둘레가 함께 자라요.","그것이 열매예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L07_challenge#5','sci',6,1,'u3','L07','g6_1_sci_u3_L07_challenge','lesson_challenge','SC6-1-u3-C22',3,'error','auto','꽃의 구조를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u3-X43','SC6-1-u3-X42']::text[],false,'{"seq":5,"concept":"SC6-1-u3-C22","difficulty":3,"kind":"error","stem":"꽃의 구조를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서준 — 「꽃받침은 꽃의 가장 가운데에서 꽃가루를 만들어.」","correct":true,"mis_target":"SC6-1-u3-X43"},{"t":"유나 — 「암술 둘레를 수술이 둘러싸고 있어.」","mis":"SC6-1-u3-X43"},{"t":"하민 — 「꽃에 따라 일부가 없는 꽃도 있대.」","mis":"SC6-1-u3-X42"}],"explanation":["꽃받침은 어디 있나요?","꽃잎 아래쪽이에요.","서준의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L07_challenge#6','sci',6,1,'u3','L07','g6_1_sci_u3_L07_challenge','lesson_challenge','SC6-1-u3-C24',3,'ox','auto','열매는 씨를 보호하고, 씨가 익으면 멀리 퍼지게 해요.',ARRAY['SC6-1-u3-X46']::text[],false,'{"seq":6,"concept":"SC6-1-u3-C24","difficulty":3,"kind":"ox","stem":"열매는 씨를 보호하고, 씨가 익으면 멀리 퍼지게 해요.","answer":"O","reason_options":[{"t":"열매가 씨를 감싸 지키고 퍼뜨려 식물이 대를 이어 가기 때문에","correct":true},{"t":"열매는 꽃이 지고 남은 쓸모없는 부분이기 때문에","mis":"SC6-1-u3-X46"}],"mis":"SC6-1-u3-X46","explanation":["열매 속에 씨가 있어요.","지키고 퍼뜨려요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L07_challenge#7','sci',6,1,'u3','L07','g6_1_sci_u3_L07_challenge','lesson_challenge','SC6-1-u3-C25',3,'mc','auto','씨앗도서관 안내문을 읽고 할 수 있는 체험 계획으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X47']::text[],false,'{"seq":7,"concept":"SC6-1-u3-C25","difficulty":3,"kind":"mc","stem":"씨앗도서관 안내문을 읽고 할 수 있는 체험 계획으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"해바라기씨를 빌려 기르면서 관찰 일지를 쓰고, 거둔 씨를 돌려준다","correct":true},{"t":"씨를 빌려 맛을 본 뒤 버린다","mis":"SC6-1-u3-X47"},{"t":"씨를 많이 빌려 돌려주지 않고 모아 둔다","mis":"SC6-1-u3-X47"},{"t":"씨를 빌릴 때 꽃을 꺾어 함께 가져간다","mis":"SC6-1-u3-X47"}],"explanation":["씨를 빌려 길러요.","관찰 일지를 써요.","씨를 돌려줘요."],"asset":{"type":"passage","lines":["책을 빌려주듯 씨를 빌려준다.","빌린 씨로 식물을 길러 씨를 거두어 다시 돌려준다.","기르면서 잎·줄기·꽃의 변화를 관찰 일지로 남길 수 있다.","여러 가지 씨를 보관하고 전시하며 토종 씨를 지킨다."],"title":"씨앗도서관 안내문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L07_challenge#8','sci',6,1,'u3','L07','g6_1_sci_u3_L07_challenge','lesson_challenge','SC6-1-u3-C23',4,'mc','auto','어떤 꽃이 활짝 피었지만 둘레에 곤충도 새도 오지 않고 바람도 거의 없었어요. 이 꽃에서 가장 걱정되는 일은 어느 것인가요?',ARRAY['SC6-1-u3-X45','SC6-1-u3-X44','SC6-1-u3-X46']::text[],false,'{"seq":8,"concept":"SC6-1-u3-C23","difficulty":4,"kind":"mc","stem":"어떤 꽃이 활짝 피었지만 둘레에 곤충도 새도 오지 않고 바람도 거의 없었어요. 이 꽃에서 가장 걱정되는 일은 어느 것인가요?","options":[{"t":"꽃가루받이가 잘 이루어지지 않아 씨가 잘 만들어지지 않을 수 있다","correct":true},{"t":"꽃이 양분을 만들지 못해 잎이 시든다","mis":"SC6-1-u3-X45"},{"t":"열매가 먼저 생겨 씨가 너무 많아진다","mis":"SC6-1-u3-X44"},{"t":"꽃받침이 열매로 바뀌지 못한다","mis":"SC6-1-u3-X46"}],"explanation":["꽃가루를 누가 옮기나요?","옮겨 줄 것이 없어요.","씨가 잘 생기지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L07_challenge#9','sci',6,1,'u3','L07','g6_1_sci_u3_L07_challenge','lesson_challenge','SC6-1-u3-C22',4,'mc','auto','친구가 관찰한 꽃에는 꽃잎이 없었어요. 이 꽃을 두고 바르게 말한 것은 어느 것인가요?',ARRAY['SC6-1-u3-X42','SC6-1-u3-X43','SC6-1-u3-X45']::text[],false,'{"seq":9,"concept":"SC6-1-u3-C22","difficulty":4,"kind":"mc","stem":"친구가 관찰한 꽃에는 꽃잎이 없었어요. 이 꽃을 두고 바르게 말한 것은 어느 것인가요?","options":[{"t":"꽃의 구조 가운데 일부가 없는 꽃이다","correct":true},{"t":"꽃잎이 없으니 꽃이라고 할 수 없다","mis":"SC6-1-u3-X42"},{"t":"꽃받침이 꽃잎 자리에 있으니 수술이 없다","mis":"SC6-1-u3-X43"},{"t":"꽃잎이 없는 꽃은 씨를 절대 만들 수 없다","mis":"SC6-1-u3-X45"}],"explanation":["꽃은 다양해요.","일부가 없을 수 있어요.","그래도 꽃이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L07_challenge#10','sci',6,1,'u3','L07','g6_1_sci_u3_L07_challenge','lesson_challenge','SC6-1-u3-C23',4,'essay','teacher','「수술」, 「꽃가루」, 「암술」을 모두 넣어 꽃가루받이를 설명하고, 꽃가루받이가 이루어진 뒤 어떤 일이 일어나는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-1-u3-C23","difficulty":4,"kind":"essay","stem":"「수술」, 「꽃가루」, 「암술」을 모두 넣어 꽃가루받이를 설명하고, 꽃가루받이가 이루어진 뒤 어떤 일이 일어나는지 쓰세요.","answer_guide":{"answer":"예: 꽃가루받이는 수술에 있는 꽃가루가 암술에 옮겨 붙는 과정이다. 꽃가루받이가 이루어지면 암술 속에 씨가 만들어지고, 씨가 자라면서 둘레가 함께 자라 열매가 된다.","scoring_points":["수술의 꽃가루가 암술로 옮겨 붙는다고 썼는가","씨가 만들어진다고 썼는가","세 낱말을 모두 넣었는가"]},"explanation":["세 낱말을 넣어요.","수술에서 암술로요.","씨가 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L08_basic#1','sci',6,1,'u3','L08','g6_1_sci_u3_L08_basic','lesson_basic','SC6-1-u3-C27',1,'sa','auto','「뿌리에서 흡수한 물과 잎에서 만든 양분은 ( )을/를 통해 식물 전체로 이동합니다.」 빈칸에 알맞은 기관을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC6-1-u3-C27","difficulty":1,"kind":"sa","stem":"「뿌리에서 흡수한 물과 잎에서 만든 양분은 ( )을/를 통해 식물 전체로 이동합니다.」 빈칸에 알맞은 기관을 두 글자로 쓰세요.","answer":["줄기"],"explanation":["물과 양분의 통로예요.","두 글자예요.","줄기예요."],"mis":"SC6-1-u3-X49"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L08_basic#2','sci',6,1,'u3','L08','g6_1_sci_u3_L08_basic','lesson_basic','SC6-1-u3-C28',1,'mc','auto','식물에서 양분을 만들어 내는 기관은 어느 것인가요?',ARRAY['SC6-1-u3-X49']::text[],false,'{"seq":2,"concept":"SC6-1-u3-C28","difficulty":1,"kind":"mc","stem":"식물에서 양분을 만들어 내는 기관은 어느 것인가요?","options":[{"t":"잎","correct":true},{"t":"뿌리","mis":"SC6-1-u3-X49"},{"t":"줄기","mis":"SC6-1-u3-X49"},{"t":"꽃받침","mis":"SC6-1-u3-X49"}],"explanation":["광합성을 떠올려요.","잎에서 일어나요.","양분은 잎에서 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L08_basic#3','sci',6,1,'u3','L08','g6_1_sci_u3_L08_basic','lesson_basic','SC6-1-u3-C27',1,'mc','auto','식물에서 물은 어느 기관에서 출발하나요?',ARRAY['SC6-1-u3-X49']::text[],false,'{"seq":3,"concept":"SC6-1-u3-C27","difficulty":1,"kind":"mc","stem":"식물에서 물은 어느 기관에서 출발하나요?","options":[{"t":"뿌리","correct":true},{"t":"잎","mis":"SC6-1-u3-X49"},{"t":"꽃","mis":"SC6-1-u3-X49"},{"t":"열매","mis":"SC6-1-u3-X49"}],"explanation":["물을 흡수하는 곳이에요.","뿌리예요.","물은 뿌리에서 출발해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L08_basic#4','sci',6,1,'u3','L08','g6_1_sci_u3_L08_basic','lesson_basic','SC6-1-u3-C29',1,'ox','auto','식물의 각 기관은 하는 일이 다르지만 서로 연결되어 있어요.',ARRAY['SC6-1-u3-X48']::text[],false,'{"seq":4,"concept":"SC6-1-u3-C29","difficulty":1,"kind":"ox","stem":"식물의 각 기관은 하는 일이 다르지만 서로 연결되어 있어요.","answer":"O","reason_options":[{"t":"물과 양분이 기관 사이를 오가며 서로 영향을 주고받기 때문에","correct":true},{"t":"기관들은 따로따로 일하고 서로 상관없기 때문에","mis":"SC6-1-u3-X48"}],"mis":"SC6-1-u3-X48","explanation":["물과 양분이 오가요.","서로 영향을 줘요.","연결되어 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L08_basic#5','sci',6,1,'u3','L08','g6_1_sci_u3_L08_basic','lesson_basic','SC6-1-u3-C26',2,'match','auto','식물의 기관과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC6-1-u3-C26","difficulty":2,"kind":"match","stem":"식물의 기관과 하는 일을 알맞게 이으세요.","pairs":[{"l":"뿌리","r":"물을 흡수함"},{"l":"잎","r":"광합성으로 양분을 만듦"},{"l":"꽃","r":"꽃가루받이가 이루어지고 씨를 만듦"}],"mis":"SC6-1-u3-X48","explanation":["기관마다 일이 달라요.","뿌리·잎·꽃을 떠올려요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L08_basic#6','sci',6,1,'u3','L08','g6_1_sci_u3_L08_basic','lesson_basic','SC6-1-u3-C28',2,'mc','auto','잎에서 만들고 쓰고 남은 양분은 어떻게 되나요?',ARRAY['SC6-1-u3-X50','SC6-1-u3-X35']::text[],false,'{"seq":6,"concept":"SC6-1-u3-C28","difficulty":2,"kind":"mc","stem":"잎에서 만들고 쓰고 남은 양분은 어떻게 되나요?","options":[{"t":"뿌리, 줄기, 열매 등에 저장된다","correct":true},{"t":"모두 기공으로 빠져나간다","mis":"SC6-1-u3-X50"},{"t":"그대로 사라진다","mis":"SC6-1-u3-X50"},{"t":"잎에만 쌓여 다른 곳으로 가지 않는다","mis":"SC6-1-u3-X35"}],"explanation":["남은 양분이에요.","버려지지 않아요.","여러 기관에 저장돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L08_basic#7','sci',6,1,'u3','L08','g6_1_sci_u3_L08_basic','lesson_basic','SC6-1-u3-C27',2,'mc','auto','잎에 도달한 물의 일부는 어떻게 되나요?',ARRAY['SC6-1-u3-X49','SC6-1-u3-X50','SC6-1-u3-X48']::text[],false,'{"seq":7,"concept":"SC6-1-u3-C27","difficulty":2,"kind":"mc","stem":"잎에 도달한 물의 일부는 어떻게 되나요?","options":[{"t":"기공을 통해 식물 밖으로 빠져나간다","correct":true},{"t":"뿌리로 다시 내려가 땅에 버려진다","mis":"SC6-1-u3-X49"},{"t":"모두 열매에 저장된다","mis":"SC6-1-u3-X50"},{"t":"꽃가루로 바뀐다","mis":"SC6-1-u3-X48"}],"explanation":["잎까지 온 물이에요.","일부가 나가요.","기공을 통해 나가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L08_basic#8','sci',6,1,'u3','L08','g6_1_sci_u3_L08_basic','lesson_basic','SC6-1-u3-C29',2,'mc','auto','시계의 톱니바퀴 하나가 빠지면 시계가 멈추는 것처럼, 식물의 한 기관에 문제가 생기면 어떻게 될 수 있나요?',ARRAY['SC6-1-u3-X48','SC6-1-u3-X22']::text[],false,'{"seq":8,"concept":"SC6-1-u3-C29","difficulty":2,"kind":"mc","stem":"시계의 톱니바퀴 하나가 빠지면 시계가 멈추는 것처럼, 식물의 한 기관에 문제가 생기면 어떻게 될 수 있나요?","options":[{"t":"식물 전체의 생명활동에 문제가 생길 수 있다","correct":true},{"t":"다른 기관은 아무 영향을 받지 않는다","mis":"SC6-1-u3-X48"},{"t":"문제가 생긴 기관만 없어지고 나머지는 더 잘 자란다","mis":"SC6-1-u3-X48"},{"t":"잎이 대신 물을 흡수해 준다","mis":"SC6-1-u3-X22"}],"explanation":["톱니바퀴를 떠올려요.","기관은 연결되어 있어요.","전체에 영향을 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L08_basic#9','sci',6,1,'u3','L08','g6_1_sci_u3_L08_basic','lesson_basic','SC6-1-u3-C29',2,'ox','auto','물과 양분의 이동 놀이에서는 가위바위보를 이기는 것이 가장 중요해요.',ARRAY['SC6-1-u3-X51']::text[],false,'{"seq":9,"concept":"SC6-1-u3-C29","difficulty":2,"kind":"ox","stem":"물과 양분의 이동 놀이에서는 가위바위보를 이기는 것이 가장 중요해요.","answer":"X","reason_options":[{"t":"놀이를 하며 물과 양분이 이동하는 경로와 기관의 연결을 생각하는 것이 중요하기 때문에","correct":true},{"t":"빨리 도착한 말만 식물에서 쓰이기 때문에","mis":"SC6-1-u3-X51"}],"mis":"SC6-1-u3-X51","explanation":["놀이의 목적이 있어요.","경로를 따라가요.","이기는 것보다 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L08_basic#10','sci',6,1,'u3','L08','g6_1_sci_u3_L08_basic','lesson_basic','SC6-1-u3-C28',3,'error','auto','물과 양분의 이동 놀이를 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u3-X49','SC6-1-u3-X50']::text[],false,'{"seq":10,"concept":"SC6-1-u3-C28","difficulty":3,"kind":"error","stem":"물과 양분의 이동 놀이를 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라온 — 「양분 말은 뿌리에서 출발해서 잎으로 가야 해.」","correct":true,"mis_target":"SC6-1-u3-X49"},{"t":"시은 — 「물 말은 뿌리에서 출발해.」","mis":"SC6-1-u3-X49"},{"t":"준우 — 「양분 말은 열매나 뿌리 도착점까지 가.」","mis":"SC6-1-u3-X50"}],"explanation":["양분은 어디서 만들까요?","잎에서 출발해요.","라온의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["물 말은 뿌리의 출발점에서, 양분 말은 잎의 출발점에서 출발한다.","가위바위보로 이기면 정해진 칸만큼 움직인다.","물 말은 잎의 도착점까지, 양분 말은 열매나 뿌리의 도착점까지 간다.","물과 양분 말이 같은 칸에 들어갈 수 있다."],"title":"물과 양분의 이동 놀이 규칙"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L08_challenge#1','sci',6,1,'u3','L08','g6_1_sci_u3_L08_challenge','lesson_challenge','SC6-1-u3-C26',2,'mc','auto','줄기가 하는 일을 바르게 말한 것은 어느 것인가요?',ARRAY['SC6-1-u3-X22','SC6-1-u3-X48']::text[],false,'{"seq":1,"concept":"SC6-1-u3-C26","difficulty":2,"kind":"mc","stem":"줄기가 하는 일을 바르게 말한 것은 어느 것인가요?","options":[{"t":"물과 양분이 이동하는 통로 역할을 한다","correct":true},{"t":"물을 흡수하고 양분을 만든다","mis":"SC6-1-u3-X22"},{"t":"씨를 보호하고 멀리 퍼뜨린다","mis":"SC6-1-u3-X48"},{"t":"꽃가루받이가 이루어지는 곳이다","mis":"SC6-1-u3-X48"}],"explanation":["줄기를 떠올려요.","물과 양분이 지나가요.","통로 역할을 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L08_challenge#2','sci',6,1,'u3','L08','g6_1_sci_u3_L08_challenge','lesson_challenge','SC6-1-u3-C27',2,'mc','auto','물과 양분의 이동 놀이 규칙에서 물 말이 도착하는 곳은 어디인가요?',ARRAY['SC6-1-u3-X49','SC6-1-u3-X50']::text[],false,'{"seq":2,"concept":"SC6-1-u3-C27","difficulty":2,"kind":"mc","stem":"물과 양분의 이동 놀이 규칙에서 물 말이 도착하는 곳은 어디인가요?","options":[{"t":"잎","correct":true},{"t":"뿌리","mis":"SC6-1-u3-X49"},{"t":"열매","mis":"SC6-1-u3-X50"},{"t":"출발점과 같은 곳","mis":"SC6-1-u3-X49"}],"explanation":["물은 뿌리에서 출발해요.","줄기를 지나요.","잎에 도착해요."],"asset":{"type":"passage","lines":["물 말은 뿌리의 출발점에서, 양분 말은 잎의 출발점에서 출발한다.","가위바위보로 이기면 정해진 칸만큼 움직인다.","물 말은 잎의 도착점까지, 양분 말은 열매나 뿌리의 도착점까지 간다.","물과 양분 말이 같은 칸에 들어갈 수 있다."],"title":"물과 양분의 이동 놀이 규칙"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L08_challenge#3','sci',6,1,'u3','L08','g6_1_sci_u3_L08_challenge','lesson_challenge','SC6-1-u3-C28',3,'mc','auto','물과 양분의 이동 놀이 규칙에서 양분 말이 열매나 뿌리의 도착점까지 가는 까닭은 무엇인가요?',ARRAY['SC6-1-u3-X19','SC6-1-u3-X50','SC6-1-u3-X49']::text[],false,'{"seq":3,"concept":"SC6-1-u3-C28","difficulty":3,"kind":"mc","stem":"물과 양분의 이동 놀이 규칙에서 양분 말이 열매나 뿌리의 도착점까지 가는 까닭은 무엇인가요?","options":[{"t":"잎에서 만든 양분이 줄기를 통해 이동해 열매와 뿌리 등에 쓰이거나 저장되기 때문이다","correct":true},{"t":"열매와 뿌리에서 양분을 새로 만들기 때문이다","mis":"SC6-1-u3-X19"},{"t":"양분은 열매와 뿌리에서 버려지기 때문이다","mis":"SC6-1-u3-X50"},{"t":"양분은 물처럼 잎에서 밖으로 빠져나가기 때문이다","mis":"SC6-1-u3-X49"}],"explanation":["양분은 잎에서 출발해요.","줄기를 통해 가요.","쓰이고 저장돼요."],"asset":{"type":"passage","lines":["물 말은 뿌리의 출발점에서, 양분 말은 잎의 출발점에서 출발한다.","가위바위보로 이기면 정해진 칸만큼 움직인다.","물 말은 잎의 도착점까지, 양분 말은 열매나 뿌리의 도착점까지 간다.","물과 양분 말이 같은 칸에 들어갈 수 있다."],"title":"물과 양분의 이동 놀이 규칙"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L08_challenge#4','sci',6,1,'u3','L08','g6_1_sci_u3_L08_challenge','lesson_challenge','SC6-1-u3-C29',3,'mc','auto','잎이 줄기에게 쓴 감사 편지에서 잎이 고마워하는 일을 모두 바르게 고른 것은 어느 것인가요?',ARRAY['SC6-1-u3-X22','SC6-1-u3-X48','SC6-1-u3-X38']::text[],false,'{"seq":4,"concept":"SC6-1-u3-C29","difficulty":3,"kind":"mc","stem":"잎이 줄기에게 쓴 감사 편지에서 잎이 고마워하는 일을 모두 바르게 고른 것은 어느 것인가요?","options":[{"t":"물을 옮겨 준 일, 곧게 서서 햇빛을 잘 받게 해 준 일, 양분을 옮겨 준 일","correct":true},{"t":"물을 흡수해 준 일, 양분을 만들어 준 일","mis":"SC6-1-u3-X22"},{"t":"씨를 만들어 준 일, 열매를 퍼뜨려 준 일","mis":"SC6-1-u3-X48"},{"t":"기공으로 물을 내보내 준 일","mis":"SC6-1-u3-X38"}],"explanation":["편지를 읽어요.","줄기가 한 일을 찾아요.","옮기고 지지해요."],"asset":{"type":"passage","lines":["줄기에게","안녕? 나는 잎이야. 네 덕분에 나는 필요한 물을 받아.","또 네가 곧게 서 주어서 햇빛을 잘 받을 수 있어.","그래서 내가 만든 양분도 네 덕분에 식물 곳곳으로 갈 수 있지. 고마워!"],"title":"잎이 줄기에게 쓴 감사 편지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L08_challenge#5','sci',6,1,'u3','L08','g6_1_sci_u3_L08_challenge','lesson_challenge','SC6-1-u3-C29',3,'error','auto','식물의 기관을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u3-X48']::text[],false,'{"seq":5,"concept":"SC6-1-u3-C29","difficulty":3,"kind":"error","stem":"식물의 기관을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하율 — 「뿌리는 물만 흡수하면 되니까 잎이 상해도 아무 상관없어.」","correct":true,"mis_target":"SC6-1-u3-X48"},{"t":"예서 — 「잎이 양분을 만들어야 뿌리도 자랄 수 있어.」","mis":"SC6-1-u3-X48"},{"t":"도겸 — 「줄기가 막히면 물이 잎까지 못 가.」","mis":"SC6-1-u3-X48"}],"explanation":["기관은 연결되어 있어요.","잎이 상하면 전체가 영향을 받아요.","하율의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L08_challenge#6','sci',6,1,'u3','L08','g6_1_sci_u3_L08_challenge','lesson_challenge','SC6-1-u3-C28',3,'ox','auto','고구마와 감자에 저장된 양분은 원래 잎에서 만들어진 거예요.',ARRAY['SC6-1-u3-X19']::text[],false,'{"seq":6,"concept":"SC6-1-u3-C28","difficulty":3,"kind":"ox","stem":"고구마와 감자에 저장된 양분은 원래 잎에서 만들어진 거예요.","answer":"O","reason_options":[{"t":"잎에서 만든 양분이 줄기를 통해 이동해 뿌리와 줄기에 저장되었기 때문에","correct":true},{"t":"뿌리와 줄기가 스스로 양분을 만들어 저장했기 때문에","mis":"SC6-1-u3-X19"}],"mis":"SC6-1-u3-X19","explanation":["양분은 잎에서 만들어요.","줄기로 옮겨져요.","뿌리·줄기에 저장돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L08_challenge#7','sci',6,1,'u3','L08','g6_1_sci_u3_L08_challenge','lesson_challenge','SC6-1-u3-C26',3,'mc','auto','식물의 각 기관이 하는 일을 바르게 짝 지은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X19','SC6-1-u3-X45','SC6-1-u3-X48']::text[],false,'{"seq":7,"concept":"SC6-1-u3-C26","difficulty":3,"kind":"mc","stem":"식물의 각 기관이 하는 일을 바르게 짝 지은 것은 어느 것인가요?","options":[{"t":"잎 — 광합성과 증산 작용, 열매 — 씨를 보호하고 퍼뜨림","correct":true},{"t":"뿌리 — 양분을 만듦, 줄기 — 물을 흡수함","mis":"SC6-1-u3-X19"},{"t":"꽃 — 양분을 만듦, 열매 — 씨를 만듦","mis":"SC6-1-u3-X45"},{"t":"잎 — 물을 흡수함, 꽃 — 식물을 지지함","mis":"SC6-1-u3-X48"}],"explanation":["기관을 하나씩 떠올려요.","잎과 열매를 봐요.","알맞게 짝 지어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L08_challenge#8','sci',6,1,'u3','L08','g6_1_sci_u3_L08_challenge','lesson_challenge','SC6-1-u3-C27',4,'mc','auto','뿌리를 다친 화분의 잎이 며칠 뒤 시들었어요. 이 일을 가장 알맞게 설명한 것은 어느 것인가요?',ARRAY['SC6-1-u3-X48','SC6-1-u3-X37','SC6-1-u3-X49']::text[],false,'{"seq":8,"concept":"SC6-1-u3-C27","difficulty":4,"kind":"mc","stem":"뿌리를 다친 화분의 잎이 며칠 뒤 시들었어요. 이 일을 가장 알맞게 설명한 것은 어느 것인가요?","options":[{"t":"뿌리가 물을 흡수하지 못해 줄기를 거쳐 잎까지 물이 가지 못했기 때문이다","correct":true},{"t":"잎이 스스로 물을 흡수하지 못해서 시든 것일 뿐 뿌리와는 상관없다","mis":"SC6-1-u3-X48"},{"t":"뿌리가 다치면 잎이 공기 중의 수증기를 빨아들이기 때문이다","mis":"SC6-1-u3-X37"},{"t":"물은 원래 잎에서 출발하기 때문이다","mis":"SC6-1-u3-X49"}],"explanation":["뿌리가 다쳤어요.","물이 올라오지 못해요.","잎이 시들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L08_challenge#9','sci',6,1,'u3','L08','g6_1_sci_u3_L08_challenge','lesson_challenge','SC6-1-u3-C29',4,'mc','auto','식물 한 그루에서 물과 양분이 움직이는 모습을 가장 바르게 정리한 것은 어느 것인가요?',ARRAY['SC6-1-u3-X49','SC6-1-u3-X48','SC6-1-u3-X50']::text[],false,'{"seq":9,"concept":"SC6-1-u3-C29","difficulty":4,"kind":"mc","stem":"식물 한 그루에서 물과 양분이 움직이는 모습을 가장 바르게 정리한 것은 어느 것인가요?","options":[{"t":"물은 뿌리 → 줄기 → 잎으로 가고, 양분은 잎 → 줄기 → 식물 전체로 가 쓰이고 남으면 저장된다","correct":true},{"t":"물은 잎 → 줄기 → 뿌리로 가고, 양분은 뿌리 → 줄기 → 잎으로 간다","mis":"SC6-1-u3-X49"},{"t":"물과 양분은 각자 만들어진 기관에만 머문다","mis":"SC6-1-u3-X48"},{"t":"양분은 잎 → 줄기로 가서 모두 사라진다","mis":"SC6-1-u3-X50"}],"explanation":["물은 뿌리에서 출발해요.","양분은 잎에서 출발해요.","줄기가 이어 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L08_challenge#10','sci',6,1,'u3','L08','g6_1_sci_u3_L08_challenge','lesson_challenge','SC6-1-u3-C27',4,'essay','teacher','식물 안에서 물이 이동하는 과정과 관련지어, 식물의 각 기관이 서로 연결되어 있음을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-1-u3-C27","difficulty":4,"kind":"essay","stem":"식물 안에서 물이 이동하는 과정과 관련지어, 식물의 각 기관이 서로 연결되어 있음을 쓰세요.","answer_guide":{"answer":"예: 뿌리에서 흡수한 물은 줄기를 통해 식물 전체로 이동해 생명활동에 쓰이고, 잎에 도달한 물의 일부는 기공을 통해 식물 밖으로 나간다. 이처럼 식물의 각 기관은 서로 연결되어 있다.","scoring_points":["뿌리에서 흡수한다고 썼는가","줄기를 통해 이동한다고 썼는가","잎의 기공으로 나간다고 썼는가"]},"explanation":["물의 길을 떠올려요.","뿌리 → 줄기 → 잎이에요.","기관이 이어져 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L09_basic#1','sci',6,1,'u3','L09','g6_1_sci_u3_L09_basic','lesson_basic','SC6-1-u3-C30',1,'mc','auto','우리 반 식물도감에 들어갈 식물 목록을 정리하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X52']::text[],false,'{"seq":1,"concept":"SC6-1-u3-C30","difficulty":1,"kind":"mc","stem":"우리 반 식물도감에 들어갈 식물 목록을 정리하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"ㄱㄴㄷ 순으로 정리한다","correct":true},{"t":"좋아하는 친구 순으로 정리한다","mis":"SC6-1-u3-X52"},{"t":"꽃 색깔이 같은 것만 모은다","mis":"SC6-1-u3-X52"},{"t":"모두 같은 식물로 정한다","mis":"SC6-1-u3-X52"}],"explanation":["찾기 쉽게 해요.","ㄱㄴㄷ 순이에요.","도감처럼 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L09_basic#2','sci',6,1,'u3','L09','g6_1_sci_u3_L09_basic','lesson_basic','SC6-1-u3-C31',1,'ox','auto','스마트 기기로 조사한 자료를 쓸 때는 출처를 반드시 밝혀요.',ARRAY['SC6-1-u3-X53']::text[],false,'{"seq":2,"concept":"SC6-1-u3-C31","difficulty":1,"kind":"ox","stem":"스마트 기기로 조사한 자료를 쓸 때는 출처를 반드시 밝혀요.","answer":"O","reason_options":[{"t":"다른 사람이 만든 자료이고 정보를 확인할 수 있게 하려는 것이기 때문에","correct":true},{"t":"출처를 밝히면 소개 자료가 길어지기 때문에","mis":"SC6-1-u3-X53"}],"mis":"SC6-1-u3-X53","explanation":["조사한 자료예요.","어디서 왔는지 밝혀요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L09_basic#3','sci',6,1,'u3','L09','g6_1_sci_u3_L09_basic','lesson_basic','SC6-1-u3-C32',1,'mc','auto','꽃가루의 특징으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X55']::text[],false,'{"seq":3,"concept":"SC6-1-u3-C32","difficulty":1,"kind":"mc","stem":"꽃가루의 특징으로 알맞은 것은 어느 것인가요?","options":[{"t":"크기가 매우 작고 식물마다 모양이 다르다","correct":true},{"t":"크기가 커서 맨눈으로 모양을 쉽게 구별한다","mis":"SC6-1-u3-X55"},{"t":"모든 식물의 꽃가루는 모양이 같다","mis":"SC6-1-u3-X55"},{"t":"모양이 금방 바뀌어 오래 남지 않는다","mis":"SC6-1-u3-X55"}],"explanation":["꽃가루를 떠올려요.","아주 작아요.","식물마다 달라요."],"asset":{"type":"passage","lines":["꽃가루는 크기가 매우 작고 식물마다 모양이 다르다.","꽃가루는 모양이 잘 변하지 않고 오래 남는다.","해바라기 꽃가루로 3D 프린터 잉크 재료를 만드는 기술이 나왔다.","사건 증거품에 묻은 꽃가루로 사건 장소를 찾기도 한다.","오래된 땅속 꽃가루로 그때 자란 식물과 날씨를 알아낸다."],"title":"만능 재주꾼, 꽃가루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L09_basic#4','sci',6,1,'u3','L09','g6_1_sci_u3_L09_basic','lesson_basic','SC6-1-u3-C31',1,'mc','auto','스마트 기기를 쓰다가 기기에서 열이 나고 냄새가 나면 어떻게 해야 하나요?',ARRAY['SC6-1-u3-X53']::text[],false,'{"seq":4,"concept":"SC6-1-u3-C31","difficulty":1,"kind":"mc","stem":"스마트 기기를 쓰다가 기기에서 열이 나고 냄새가 나면 어떻게 해야 하나요?","options":[{"t":"바로 사용을 멈추고 선생님께 알린다","correct":true},{"t":"조사를 끝낼 때까지 계속 쓴다","mis":"SC6-1-u3-X53"},{"t":"기기를 물에 담가 식힌다","mis":"SC6-1-u3-X53"},{"t":"친구 기기와 바꾸어 몰래 쓴다","mis":"SC6-1-u3-X53"}],"explanation":["위험한 신호예요.","바로 멈춰요.","선생님께 알려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L09_basic#5','sci',6,1,'u3','L09','g6_1_sci_u3_L09_basic','lesson_basic','SC6-1-u3-C30',2,'mc','auto','우리 반 식물도감 카드에서 토끼풀의 특징으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X52']::text[],false,'{"seq":5,"concept":"SC6-1-u3-C30","difficulty":2,"kind":"mc","stem":"우리 반 식물도감 카드에서 토끼풀의 특징으로 알맞은 것은 어느 것인가요?","options":[{"t":"줄기가 땅 위를 기듯이 자라고 잎이 세 갈래로 갈라진다","correct":true},{"t":"바늘 모양 잎이 두 개씩 모여 난다","mis":"SC6-1-u3-X52"},{"t":"줄기나 잎을 자르면 노란 즙이 나온다","mis":"SC6-1-u3-X52"},{"t":"보라색 꽃의 꽃잎 모양이 서로 다르다","mis":"SC6-1-u3-X52"}],"explanation":["토끼풀 줄을 봐요.","땅 위를 기어요.","잎이 세 갈래예요."],"asset":{"type":"passage","lines":["소나무 — 바늘 모양 잎이 두 개씩 모여 난다. 봄에 노란 꽃가루가 날린다.","애기똥풀 — 노란 꽃이 핀다. 줄기나 잎을 자르면 노란 즙이 나온다.","제비꽃 — 보라색 꽃이 핀다. 꽃잎 모양이 서로 다르고 잎자루가 길다.","토끼풀 — 줄기가 땅 위를 기듯이 자라고 잎은 세 갈래로 갈라진다.","토끼풀 — 여러 송이의 꽃이 모여 한 송이 꽃처럼 보인다."],"title":"우리 반 식물도감 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L09_basic#6','sci',6,1,'u3','L09','g6_1_sci_u3_L09_basic','lesson_basic','SC6-1-u3-C30',2,'mc','auto','식물 소개 자료에 꼭 들어가야 할 내용으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X52']::text[],false,'{"seq":6,"concept":"SC6-1-u3-C30","difficulty":2,"kind":"mc","stem":"식물 소개 자료에 꼭 들어가야 할 내용으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"뿌리·줄기·잎·꽃 등의 구조와 기능에 관한 설명","correct":true},{"t":"식물을 파는 가게와 값","mis":"SC6-1-u3-X52"},{"t":"식물 사진 한 장만","mis":"SC6-1-u3-X52"},{"t":"그 식물을 좋아하는 친구 이름","mis":"SC6-1-u3-X52"}],"explanation":["도감은 무엇을 알려 주나요?","식물의 특징이에요.","구조와 기능을 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L09_basic#7','sci',6,1,'u3','L09','g6_1_sci_u3_L09_basic','lesson_basic','SC6-1-u3-C32',2,'mc','auto','만능 재주꾼, 꽃가루에서 꽃가루를 쓰는 예가 아닌 것은 어느 것인가요?',ARRAY['SC6-1-u3-X54']::text[],false,'{"seq":7,"concept":"SC6-1-u3-C32","difficulty":2,"kind":"mc","stem":"만능 재주꾼, 꽃가루에서 꽃가루를 쓰는 예가 아닌 것은 어느 것인가요?","options":[{"t":"꽃가루로 식물의 뿌리털을 만든다","correct":true},{"t":"3D 프린터 잉크 재료로 쓴다","mis":"SC6-1-u3-X54"},{"t":"사건 장소를 찾는 데 쓴다","mis":"SC6-1-u3-X54"},{"t":"옛날의 식물과 날씨를 알아내는 데 쓴다","mis":"SC6-1-u3-X54"}],"explanation":["글을 다시 읽어요.","쓰임이 여러 가지예요.","뿌리털과는 상관없어요."],"asset":{"type":"passage","lines":["꽃가루는 크기가 매우 작고 식물마다 모양이 다르다.","꽃가루는 모양이 잘 변하지 않고 오래 남는다.","해바라기 꽃가루로 3D 프린터 잉크 재료를 만드는 기술이 나왔다.","사건 증거품에 묻은 꽃가루로 사건 장소를 찾기도 한다.","오래된 땅속 꽃가루로 그때 자란 식물과 날씨를 알아낸다."],"title":"만능 재주꾼, 꽃가루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L09_basic#8','sci',6,1,'u3','L09','g6_1_sci_u3_L09_basic','lesson_basic','SC6-1-u3-C32',2,'ox','auto','꽃가루는 앨러지를 일으킬 뿐 우리 생활에 쓰이는 곳은 없어요.',ARRAY['SC6-1-u3-X54']::text[],false,'{"seq":8,"concept":"SC6-1-u3-C32","difficulty":2,"kind":"ox","stem":"꽃가루는 앨러지를 일으킬 뿐 우리 생활에 쓰이는 곳은 없어요.","answer":"X","reason_options":[{"t":"꽃가루는 잉크 재료, 사건 수사, 옛날 날씨 알아내기 등 여러 곳에 쓰이기 때문에","correct":true},{"t":"꽃가루는 크기가 커서 다루기 어렵기 때문에","mis":"SC6-1-u3-X54"}],"mis":"SC6-1-u3-X54","explanation":["꽃가루의 쓰임을 떠올려요.","여러 곳에 쓰여요.","틀린 말이에요."],"asset":{"type":"passage","lines":["꽃가루는 크기가 매우 작고 식물마다 모양이 다르다.","꽃가루는 모양이 잘 변하지 않고 오래 남는다.","해바라기 꽃가루로 3D 프린터 잉크 재료를 만드는 기술이 나왔다.","사건 증거품에 묻은 꽃가루로 사건 장소를 찾기도 한다.","오래된 땅속 꽃가루로 그때 자란 식물과 날씨를 알아낸다."],"title":"만능 재주꾼, 꽃가루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L09_basic#9','sci',6,1,'u3','L09','g6_1_sci_u3_L09_basic','lesson_basic','SC6-1-u3-C33',2,'mc','auto','여러 가지 식물을 조사해 보고 정리한 말로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X56','SC6-1-u3-X03','SC6-1-u3-X06']::text[],false,'{"seq":9,"concept":"SC6-1-u3-C33","difficulty":2,"kind":"mc","stem":"여러 가지 식물을 조사해 보고 정리한 말로 알맞은 것은 어느 것인가요?","options":[{"t":"식물마다 특징은 다르지만 뿌리·줄기·잎·꽃 등의 기관으로 이루어진 점은 비슷하다","correct":true},{"t":"식물마다 특징이 다르니 기관도 모두 전혀 다르다","mis":"SC6-1-u3-X56"},{"t":"모든 식물은 생김새가 똑같다","mis":"SC6-1-u3-X03"},{"t":"식물은 기관 없이 세포 하나로 이루어진다","mis":"SC6-1-u3-X06"}],"explanation":["도감을 떠올려요.","특징은 달라요.","기관은 비슷해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L09_basic#10','sci',6,1,'u3','L09','g6_1_sci_u3_L09_basic','lesson_basic','SC6-1-u3-C31',3,'error','auto','식물 소개 자료를 만들며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u3-X53','SC6-1-u3-X52']::text[],false,'{"seq":10,"concept":"SC6-1-u3-C31","difficulty":3,"kind":"error","stem":"식물 소개 자료를 만들며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태경 — 「누리집에 있는 글을 그대로 붙여 넣고 출처는 안 적어도 돼.」","correct":true,"mis_target":"SC6-1-u3-X53"},{"t":"수아 — 「올바른 정보인지 도감으로 한 번 더 확인하자.」","mis":"SC6-1-u3-X53"},{"t":"지민 — 「친구와 겹치지 않게 서로 다른 식물을 고르자.」","mis":"SC6-1-u3-X52"}],"explanation":["출처가 필요해요.","그대로 옮기지 않아요.","태경의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L09_challenge#1','sci',6,1,'u3','L09','g6_1_sci_u3_L09_challenge','lesson_challenge','SC6-1-u3-C30',2,'match','auto','우리 반 식물도감 카드에서 식물과 특징을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC6-1-u3-C30","difficulty":2,"kind":"match","stem":"우리 반 식물도감 카드에서 식물과 특징을 알맞게 이으세요.","pairs":[{"l":"소나무","r":"봄에 노란 꽃가루가 날림"},{"l":"애기똥풀","r":"줄기를 자르면 노란 즙이 나옴"},{"l":"제비꽃","r":"꽃잎 모양이 서로 다르고 잎자루가 김"}],"mis":"SC6-1-u3-X52","explanation":["카드를 봐요.","식물마다 특징이 달라요.","하나씩 이어요."],"asset":{"type":"passage","lines":["소나무 — 바늘 모양 잎이 두 개씩 모여 난다. 봄에 노란 꽃가루가 날린다.","애기똥풀 — 노란 꽃이 핀다. 줄기나 잎을 자르면 노란 즙이 나온다.","제비꽃 — 보라색 꽃이 핀다. 꽃잎 모양이 서로 다르고 잎자루가 길다.","토끼풀 — 줄기가 땅 위를 기듯이 자라고 잎은 세 갈래로 갈라진다.","토끼풀 — 여러 송이의 꽃이 모여 한 송이 꽃처럼 보인다."],"title":"우리 반 식물도감 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L09_challenge#2','sci',6,1,'u3','L09','g6_1_sci_u3_L09_challenge','lesson_challenge','SC6-1-u3-C30',2,'mc','auto','식물도감을 만들 때 친구들과 서로 다른 식물을 정해 조사하는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X52','SC6-1-u3-X53','SC6-1-u3-X56']::text[],false,'{"seq":2,"concept":"SC6-1-u3-C30","difficulty":2,"kind":"mc","stem":"식물도감을 만들 때 친구들과 서로 다른 식물을 정해 조사하는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"여러 가지 식물의 특징을 고루 담기 위해서","correct":true},{"t":"같은 식물을 여러 번 넣어야 도감이 두꺼워지기 때문에","mis":"SC6-1-u3-X52"},{"t":"출처를 밝히지 않아도 되기 때문에","mis":"SC6-1-u3-X53"},{"t":"식물마다 기관이 전혀 다르다는 것을 보이려고","mis":"SC6-1-u3-X56"}],"explanation":["도감은 여러 식물을 담아요.","겹치지 않게 해요.","고루 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L09_challenge#3','sci',6,1,'u3','L09','g6_1_sci_u3_L09_challenge','lesson_challenge','SC6-1-u3-C32',3,'mc','auto','오래된 땅속에서 찾은 꽃가루로 그때의 식물과 날씨를 알아낼 수 있는 까닭은 꽃가루의 어떤 특징 때문인가요?',ARRAY['SC6-1-u3-X55','SC6-1-u3-X54']::text[],false,'{"seq":3,"concept":"SC6-1-u3-C32","difficulty":3,"kind":"mc","stem":"오래된 땅속에서 찾은 꽃가루로 그때의 식물과 날씨를 알아낼 수 있는 까닭은 꽃가루의 어떤 특징 때문인가요?","options":[{"t":"모양이 잘 변하지 않고 식물마다 모양이 달라서","correct":true},{"t":"크기가 커서 쉽게 눈에 띄어서","mis":"SC6-1-u3-X55"},{"t":"모든 식물의 꽃가루가 같은 모양이어서","mis":"SC6-1-u3-X55"},{"t":"꽃가루가 앨러지를 일으켜서","mis":"SC6-1-u3-X54"}],"explanation":["오래 남아 있어요.","모양이 달라 구별돼요.","그래서 알 수 있어요."],"asset":{"type":"passage","lines":["꽃가루는 크기가 매우 작고 식물마다 모양이 다르다.","꽃가루는 모양이 잘 변하지 않고 오래 남는다.","해바라기 꽃가루로 3D 프린터 잉크 재료를 만드는 기술이 나왔다.","사건 증거품에 묻은 꽃가루로 사건 장소를 찾기도 한다.","오래된 땅속 꽃가루로 그때 자란 식물과 날씨를 알아낸다."],"title":"만능 재주꾼, 꽃가루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L09_challenge#4','sci',6,1,'u3','L09','g6_1_sci_u3_L09_challenge','lesson_challenge','SC6-1-u3-C32',3,'mc','auto','해바라기 꽃가루로 3D 프린터 잉크 재료를 만드는 기술이 의료용으로도 쓰일 수 있는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X54','SC6-1-u3-X55','SC6-1-u3-X45']::text[],false,'{"seq":4,"concept":"SC6-1-u3-C32","difficulty":3,"kind":"mc","stem":"해바라기 꽃가루로 3D 프린터 잉크 재료를 만드는 기술이 의료용으로도 쓰일 수 있는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"구하기 쉽고 독성이 없기 때문이다","correct":true},{"t":"꽃가루는 모두 앨러지를 일으키기 때문이다","mis":"SC6-1-u3-X54"},{"t":"꽃가루가 아주 크고 모양이 같기 때문이다","mis":"SC6-1-u3-X55"},{"t":"꽃가루가 양분을 만들기 때문이다","mis":"SC6-1-u3-X45"}],"explanation":["사람 몸에 써요.","해롭지 않아야 해요.","독성이 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L09_challenge#5','sci',6,1,'u3','L09','g6_1_sci_u3_L09_challenge','lesson_challenge','SC6-1-u3-C30',3,'mc','auto','토끼풀 소개 자료에 「여러 송이의 꽃이 모여 한 송이 꽃처럼 보인다」를 넣었어요. 이것은 어떤 내용을 담은 것인가요?',ARRAY['SC6-1-u3-X52','SC6-1-u3-X53']::text[],false,'{"seq":5,"concept":"SC6-1-u3-C30","difficulty":3,"kind":"mc","stem":"토끼풀 소개 자료에 「여러 송이의 꽃이 모여 한 송이 꽃처럼 보인다」를 넣었어요. 이것은 어떤 내용을 담은 것인가요?","options":[{"t":"다른 식물과 견주어 특이한 꽃의 구조","correct":true},{"t":"토끼풀을 파는 곳","mis":"SC6-1-u3-X52"},{"t":"토끼풀을 좋아하는 까닭","mis":"SC6-1-u3-X52"},{"t":"출처를 밝히지 않은 소문","mis":"SC6-1-u3-X53"}],"explanation":["꽃의 생김새예요.","특이한 점이에요.","구조를 담았어요."],"asset":{"type":"passage","lines":["소나무 — 바늘 모양 잎이 두 개씩 모여 난다. 봄에 노란 꽃가루가 날린다.","애기똥풀 — 노란 꽃이 핀다. 줄기나 잎을 자르면 노란 즙이 나온다.","제비꽃 — 보라색 꽃이 핀다. 꽃잎 모양이 서로 다르고 잎자루가 길다.","토끼풀 — 줄기가 땅 위를 기듯이 자라고 잎은 세 갈래로 갈라진다.","토끼풀 — 여러 송이의 꽃이 모여 한 송이 꽃처럼 보인다."],"title":"우리 반 식물도감 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L09_challenge#6','sci',6,1,'u3','L09','g6_1_sci_u3_L09_challenge','lesson_challenge','SC6-1-u3-C32',3,'error','auto','꽃가루를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u3-X54']::text[],false,'{"seq":6,"concept":"SC6-1-u3-C32","difficulty":3,"kind":"error","stem":"꽃가루를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"로아 — 「꽃가루는 콧물만 나게 하니까 세상에서 없어지면 좋겠어.」","correct":true,"mis_target":"SC6-1-u3-X54"},{"t":"건우 — 「꽃가루받이에 꽃가루가 꼭 필요해.」","mis":"SC6-1-u3-X54"},{"t":"채린 — 「꽃가루로 사건 장소를 찾기도 한대.」","mis":"SC6-1-u3-X54"}],"explanation":["꽃가루가 하는 일이 있어요.","쓰임도 많아요.","로아의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L09_challenge#7','sci',6,1,'u3','L09','g6_1_sci_u3_L09_challenge','lesson_challenge','SC6-1-u3-C30',3,'ox','auto','식물 소개 자료에는 식물의 생김새 사진만 넣으면 충분해요.',ARRAY['SC6-1-u3-X52']::text[],false,'{"seq":7,"concept":"SC6-1-u3-C30","difficulty":3,"kind":"ox","stem":"식물 소개 자료에는 식물의 생김새 사진만 넣으면 충분해요.","answer":"X","reason_options":[{"t":"식물의 구조와 기능이 잘 드러나도록 설명도 함께 넣어야 하기 때문에","correct":true},{"t":"사진을 넣으면 출처를 밝히지 않아도 되기 때문에","mis":"SC6-1-u3-X52"}],"mis":"SC6-1-u3-X52","explanation":["도감은 무엇을 알려 주나요?","구조와 기능이에요.","설명도 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L09_challenge#8','sci',6,1,'u3','L09','g6_1_sci_u3_L09_challenge','lesson_challenge','SC6-1-u3-C31',4,'mc','auto','친구가 공유 플랫폼에 올린 식물 소개 자료를 보고 남길 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X53','SC6-1-u3-X52']::text[],false,'{"seq":8,"concept":"SC6-1-u3-C31","difficulty":4,"kind":"mc","stem":"친구가 공유 플랫폼에 올린 식물 소개 자료를 보고 남길 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「채송화 꽃이 밤에 오므라든다는 걸 처음 알았어. 사진도 잘 골랐다.」","correct":true},{"t":"「출처는 필요 없으니 지우는 게 좋겠어.」","mis":"SC6-1-u3-X53"},{"t":"「내가 조사한 식물이랑 똑같이 고쳐.」","mis":"SC6-1-u3-X52"},{"t":"「사진만 있으면 되지, 설명은 왜 넣었어?」","mis":"SC6-1-u3-X52"}],"explanation":["새로 안 점을 말해요.","잘한 점을 찾아요.","고운 말로 남겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L09_challenge#9','sci',6,1,'u3','L09','g6_1_sci_u3_L09_challenge','lesson_challenge','SC6-1-u3-C33',4,'mc','auto','사과나무와 토끼풀을 견주어 바르게 말한 것은 어느 것인가요?',ARRAY['SC6-1-u3-X56','SC6-1-u3-X06']::text[],false,'{"seq":9,"concept":"SC6-1-u3-C33","difficulty":4,"kind":"mc","stem":"사과나무와 토끼풀을 견주어 바르게 말한 것은 어느 것인가요?","options":[{"t":"생김새와 크기는 매우 다르지만 둘 다 뿌리·줄기·잎·꽃 등의 기관으로 이루어져 있다","correct":true},{"t":"크기가 다르니 사과나무만 기관이 있다","mis":"SC6-1-u3-X56"},{"t":"토끼풀은 너무 작아 세포로 이루어져 있지 않다","mis":"SC6-1-u3-X06"},{"t":"두 식물은 뿌리가 하는 일이 정반대다","mis":"SC6-1-u3-X56"}],"explanation":["크기는 달라요.","기관을 떠올려요.","기관은 비슷해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_L09_challenge#10','sci',6,1,'u3','L09','g6_1_sci_u3_L09_challenge','lesson_challenge','SC6-1-u3-C32',4,'essay','teacher','내가 과학자라면 꽃가루의 특징을 이용해 무엇을 만들거나 연구하고 싶은지, 그 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-1-u3-C32","difficulty":4,"kind":"essay","stem":"내가 과학자라면 꽃가루의 특징을 이용해 무엇을 만들거나 연구하고 싶은지, 그 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 꽃가루는 식물마다 모양이 다르고 잘 변하지 않으니, 우리 동네 땅속 꽃가루를 모아 옛날에 어떤 식물이 자랐는지 알아보는 지도를 만들고 싶다.","scoring_points":["꽃가루의 특징(작음·모양이 다름·잘 변하지 않음 등)을 썼는가","그 특징을 이용한 쓰임을 썼는가"]},"explanation":["꽃가루의 특징을 떠올려요.","쓰임을 상상해요.","까닭과 함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_a#1','sci',6,1,'u3','','g6_1_sci_u3_review_a','unit_review','SC6-1-u3-C1',1,'mc','auto','초록잎반 탐구 일지 ①에서 다른 모둠이 한 질문은 식물의 무엇에 관한 것인가요?',ARRAY['SC6-1-u3-X01']::text[],false,'{"seq":1,"concept":"SC6-1-u3-C1","difficulty":1,"kind":"mc","stem":"초록잎반 탐구 일지 ①에서 다른 모둠이 한 질문은 식물의 무엇에 관한 것인가요?","options":[{"t":"생김새","correct":true},{"t":"값","mis":"SC6-1-u3-X01"},{"t":"맛","mis":"SC6-1-u3-X01"},{"t":"기르는 사람","mis":"SC6-1-u3-X01"}],"explanation":["질문을 읽어요.","키와 꽃 색이에요.","생김새를 물었어요."],"asset":{"type":"passage","lines":["우리 모둠은 화단의 해바라기를 다섯 고개 문제로 냈다.","사진은 꽃잎 부분만 잘라서 보여 주었다.","다른 모둠은 「나보다 키가 큰가요?」, 「꽃은 무슨 색인가요?」 등을 물었다.","앱으로 알아낸 이름은 식물도감으로 다시 확인했다."],"title":"① 다섯 고개 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_a#2','sci',6,1,'u3','','g6_1_sci_u3_review_a','unit_review','SC6-1-u3-C13',1,'mc','auto','초록잎반 탐구 일지 ④에서 감자는 식물의 어느 부분이라고 했나요?',ARRAY['SC6-1-u3-X25']::text[],false,'{"seq":2,"concept":"SC6-1-u3-C13","difficulty":1,"kind":"mc","stem":"초록잎반 탐구 일지 ④에서 감자는 식물의 어느 부분이라고 했나요?","options":[{"t":"줄기","correct":true},{"t":"뿌리","mis":"SC6-1-u3-X25"},{"t":"잎","mis":"SC6-1-u3-X25"},{"t":"열매","mis":"SC6-1-u3-X25"}],"explanation":["선생님 말씀을 봐요.","땅속 줄기예요.","감자는 줄기예요."],"asset":{"type":"passage","lines":["붉은색 색소를 녹인 물에 백합을 하루 동안 두었다.","흰 꽃잎과 초록 잎이 붉은빛을 띠었다.","줄기 가로 단면에는 붉은 점이, 세로 단면에는 붉은 선이 보였다.","급식에 나온 감자는 땅속 줄기라고 선생님께서 말씀하셨다."],"title":"④ 줄기 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_a#3','sci',6,1,'u3','','g6_1_sci_u3_review_a','unit_review','SC6-1-u3-C5',1,'mc','auto','초록잎반 탐구 일지 ②에서 양파 표피세포마다 하나씩 보인 둥근 것은 어느 것인가요?',ARRAY['SC6-1-u3-X08']::text[],false,'{"seq":3,"concept":"SC6-1-u3-C5","difficulty":1,"kind":"mc","stem":"초록잎반 탐구 일지 ②에서 양파 표피세포마다 하나씩 보인 둥근 것은 어느 것인가요?","options":[{"t":"핵","correct":true},{"t":"세포벽","mis":"SC6-1-u3-X08"},{"t":"기공","mis":"SC6-1-u3-X08"},{"t":"뿌리털","mis":"SC6-1-u3-X08"}],"explanation":["세포 안의 둥근 것이에요.","하나씩 보였어요.","핵이에요."],"asset":{"type":"passage","lines":["사철나무잎 뒷면에 투명 매니큐어를 얇게 발라 표본을 만들었다.","각진 세포들이 붙어 있고 세포의 경계가 뚜렷했다.","양파 표피세포는 세포마다 둥근 핵이 하나씩 보였다.","쉬는 시간에 달걀 하나도 하나의 세포라는 이야기를 들었다."],"title":"② 현미경으로 세포 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_a#4','sci',6,1,'u3','','g6_1_sci_u3_review_a','unit_review','SC6-1-u3-C3',1,'mc','auto','초록잎반 탐구 일지 ⑦에서 꽃가루 앨러지가 있는 친구가 보안경과 마스크를 쓴 까닭은 무엇인가요?',ARRAY['SC6-1-u3-X47','SC6-1-u3-X04']::text[],false,'{"seq":4,"concept":"SC6-1-u3-C3","difficulty":1,"kind":"mc","stem":"초록잎반 탐구 일지 ⑦에서 꽃가루 앨러지가 있는 친구가 보안경과 마스크를 쓴 까닭은 무엇인가요?","options":[{"t":"꽃가루 때문에 몸에 이상이 생기지 않도록 하려고","correct":true},{"t":"꽃을 더 가까이에서 맛보려고","mis":"SC6-1-u3-X47"},{"t":"꽃을 꺾어 가져가려고","mis":"SC6-1-u3-X04"},{"t":"꽃의 색을 바꾸려고","mis":"SC6-1-u3-X04"}],"explanation":["앨러지가 있어요.","꽃가루를 막아요.","안전을 지켜요."],"asset":{"type":"passage","lines":["제라늄꽃을 암술·수술·꽃잎·꽃받침으로 나누어 흰 종이에 놓았다.","꽃가루 앨러지가 있는 친구는 보안경과 마스크를 썼다.","벌이 꽃 사이를 날아다니며 꽃가루를 묻히는 영상을 보았다.","복숭아 열매를 잘라 속에 든 씨를 찾아보았다."],"title":"⑦ 꽃 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_a#5','sci',6,1,'u3','','g6_1_sci_u3_review_a','unit_review','SC6-1-u3-C2',1,'mc','auto','초록잎반 탐구 일지 ①에서 다섯 고개 문제로 낸 식물은 어느 것인가요?',ARRAY['SC6-1-u3-X03']::text[],false,'{"seq":5,"concept":"SC6-1-u3-C2","difficulty":1,"kind":"mc","stem":"초록잎반 탐구 일지 ①에서 다섯 고개 문제로 낸 식물은 어느 것인가요?","options":[{"t":"해바라기","correct":true},{"t":"소나무","mis":"SC6-1-u3-X03"},{"t":"무궁화","mis":"SC6-1-u3-X03"},{"t":"애기똥풀","mis":"SC6-1-u3-X03"}],"explanation":["일지를 읽어요.","화단의 해바라기예요.","해바라기를 냈어요."],"asset":{"type":"passage","lines":["우리 모둠은 화단의 해바라기를 다섯 고개 문제로 냈다.","사진은 꽃잎 부분만 잘라서 보여 주었다.","다른 모둠은 「나보다 키가 큰가요?」, 「꽃은 무슨 색인가요?」 등을 물었다.","앱으로 알아낸 이름은 식물도감으로 다시 확인했다."],"title":"① 다섯 고개 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_a#6','sci',6,1,'u3','','g6_1_sci_u3_review_a','unit_review','SC6-1-u3-C8',1,'mc','auto','초록잎반 탐구 일지 ③에서 강아지풀 뿌리의 생김새로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X14']::text[],false,'{"seq":6,"concept":"SC6-1-u3-C8","difficulty":1,"kind":"mc","stem":"초록잎반 탐구 일지 ③에서 강아지풀 뿌리의 생김새로 알맞은 것은 어느 것인가요?","options":[{"t":"가는 뿌리가 수염처럼 나 있다","correct":true},{"t":"굵고 곧은 뿌리에 가는 뿌리가 나 있다","mis":"SC6-1-u3-X14"},{"t":"뿌리가 없다","mis":"SC6-1-u3-X14"},{"t":"모든 식물의 뿌리와 똑같다","mis":"SC6-1-u3-X14"}],"explanation":["짝꿍 화분을 봐요.","수염처럼 났어요.","가는 뿌리예요."],"asset":{"type":"passage","lines":["파 ㉮는 뿌리를 자르고 파 ㉯는 뿌리를 그대로 두었다.","두 파를 같은 양의 물에 넣어 햇빛 드는 창가에 3일 두었다.","㉮ 쪽 물은 조금, ㉯ 쪽 물은 많이 줄었다.","짝꿍 화분의 강아지풀은 가는 뿌리가 수염처럼 나 있었다."],"title":"③ 뿌리 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_a#7','sci',6,1,'u3','','g6_1_sci_u3_review_a','unit_review','SC6-1-u3-C30',1,'mc','auto','초록잎반 탐구 일지 ⑧에서 식물도감에 올린 식물이 아닌 것은 어느 것인가요?',ARRAY['SC6-1-u3-X52']::text[],false,'{"seq":7,"concept":"SC6-1-u3-C30","difficulty":1,"kind":"mc","stem":"초록잎반 탐구 일지 ⑧에서 식물도감에 올린 식물이 아닌 것은 어느 것인가요?","options":[{"t":"해바라기","correct":true},{"t":"토끼풀","mis":"SC6-1-u3-X52"},{"t":"소나무","mis":"SC6-1-u3-X52"},{"t":"나팔꽃","mis":"SC6-1-u3-X52"}],"explanation":["일지를 읽어요.","세 식물을 올렸어요.","해바라기는 없어요."],"asset":{"type":"passage","lines":["짝과 물과 양분의 이동 놀이를 했다(물은 뿌리, 양분은 잎에서 출발).","우리 반 식물도감에 토끼풀·소나무·나팔꽃 소개 자료를 올렸다.","조사한 자료마다 출처를 적었다.","꽃가루로 옛날의 식물과 날씨를 알아낸다는 글을 읽었다."],"title":"⑧ 연결 놀이와 식물도감"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_a#8','sci',6,1,'u3','','g6_1_sci_u3_review_a','unit_review','SC6-1-u3-C21',1,'mc','auto','증산 작용이 식물에서 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X37','SC6-1-u3-X41']::text[],false,'{"seq":8,"concept":"SC6-1-u3-C21","difficulty":1,"kind":"mc","stem":"증산 작용이 식물에서 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"식물의 온도를 조절한다","correct":true},{"t":"공기 중의 수증기를 빨아들인다","mis":"SC6-1-u3-X37"},{"t":"씨를 퍼뜨린다","mis":"SC6-1-u3-X41"},{"t":"양분을 만든다","mis":"SC6-1-u3-X41"}],"explanation":["물이 수증기로 나가요.","온도를 낮춰요.","온도를 조절해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_a#9','sci',6,1,'u3','','g6_1_sci_u3_review_a','unit_review','SC6-1-u3-C1',2,'mc','auto','초록잎반 탐구 일지 ①에서 사진의 꽃잎 부분만 보여 준 까닭은 무엇인가요?',ARRAY['SC6-1-u3-X02','SC6-1-u3-X03','SC6-1-u3-X01']::text[],false,'{"seq":9,"concept":"SC6-1-u3-C1","difficulty":2,"kind":"mc","stem":"초록잎반 탐구 일지 ①에서 사진의 꽃잎 부분만 보여 준 까닭은 무엇인가요?","options":[{"t":"일부분만 보고 질문으로 이름을 알아맞히는 놀이이기 때문이다","correct":true},{"t":"사진 전체를 보여 주면 질문을 하지 않아도 되어서 좋기 때문이다","mis":"SC6-1-u3-X02"},{"t":"해바라기에는 꽃잎 말고 다른 부분이 없기 때문이다","mis":"SC6-1-u3-X03"},{"t":"값을 물어볼 수 있게 하려고","mis":"SC6-1-u3-X01"}],"explanation":["맞히는 놀이예요.","일부분만 보여 줘요.","질문으로 좁혀요."],"asset":{"type":"passage","lines":["우리 모둠은 화단의 해바라기를 다섯 고개 문제로 냈다.","사진은 꽃잎 부분만 잘라서 보여 주었다.","다른 모둠은 「나보다 키가 큰가요?」, 「꽃은 무슨 색인가요?」 등을 물었다.","앱으로 알아낸 이름은 식물도감으로 다시 확인했다."],"title":"① 다섯 고개 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_a#10','sci',6,1,'u3','','g6_1_sci_u3_review_a','unit_review','SC6-1-u3-C13',2,'ox','auto','초록잎반 탐구 일지 ④처럼 감자가 줄기라면, 비슷하게 생긴 고구마도 줄기예요.',ARRAY['SC6-1-u3-X25']::text[],false,'{"seq":10,"concept":"SC6-1-u3-C13","difficulty":2,"kind":"ox","stem":"초록잎반 탐구 일지 ④처럼 감자가 줄기라면, 비슷하게 생긴 고구마도 줄기예요.","answer":"X","reason_options":[{"t":"고구마는 뿌리에 양분을 저장한 것이고 감자는 줄기에 저장한 것이기 때문에","correct":true},{"t":"땅속에 있는 것은 모두 줄기이기 때문에","mis":"SC6-1-u3-X25"}],"mis":"SC6-1-u3-X25","explanation":["비슷해 보여도 달라요.","고구마는 뿌리예요.","틀린 말이에요."],"asset":{"type":"passage","lines":["붉은색 색소를 녹인 물에 백합을 하루 동안 두었다.","흰 꽃잎과 초록 잎이 붉은빛을 띠었다.","줄기 가로 단면에는 붉은 점이, 세로 단면에는 붉은 선이 보였다.","급식에 나온 감자는 땅속 줄기라고 선생님께서 말씀하셨다."],"title":"④ 줄기 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_a#11','sci',6,1,'u3','','g6_1_sci_u3_review_a','unit_review','SC6-1-u3-C3',2,'mc','auto','초록잎반 탐구 일지 ①에서 앱으로 알아낸 이름을 식물도감으로 다시 확인한 까닭은 무엇인가요?',ARRAY['SC6-1-u3-X05','SC6-1-u3-X01']::text[],false,'{"seq":11,"concept":"SC6-1-u3-C3","difficulty":2,"kind":"mc","stem":"초록잎반 탐구 일지 ①에서 앱으로 알아낸 이름을 식물도감으로 다시 확인한 까닭은 무엇인가요?","options":[{"t":"앱의 결과가 틀릴 수도 있어 정확한 정보인지 확인하려고","correct":true},{"t":"앱은 늘 맞으니 확인은 필요 없지만 재미로","mis":"SC6-1-u3-X05"},{"t":"도감에서 식물의 값을 알아보려고","mis":"SC6-1-u3-X01"},{"t":"수업과 상관없는 자료를 찾아보려고","mis":"SC6-1-u3-X05"}],"explanation":["앱도 틀릴 수 있어요.","도감으로 확인해요.","정확한 정보를 써요."],"asset":{"type":"passage","lines":["우리 모둠은 화단의 해바라기를 다섯 고개 문제로 냈다.","사진은 꽃잎 부분만 잘라서 보여 주었다.","다른 모둠은 「나보다 키가 큰가요?」, 「꽃은 무슨 색인가요?」 등을 물었다.","앱으로 알아낸 이름은 식물도감으로 다시 확인했다."],"title":"① 다섯 고개 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_a#12','sci',6,1,'u3','','g6_1_sci_u3_review_a','unit_review','SC6-1-u3-C20',2,'mc','auto','초록잎반 탐구 일지 ⑥의 종이를 잎 뒷면에 붙인 까닭은 무엇인가요?',ARRAY['SC6-1-u3-X37','SC6-1-u3-X38','SC6-1-u3-X39']::text[],false,'{"seq":12,"concept":"SC6-1-u3-C20","difficulty":2,"kind":"mc","stem":"초록잎반 탐구 일지 ⑥의 종이를 잎 뒷면에 붙인 까닭은 무엇인가요?","options":[{"t":"기공이 대부분 잎 뒷면에 있기 때문이다","correct":true},{"t":"잎 뒷면이 물을 흡수하는 곳이기 때문이다","mis":"SC6-1-u3-X37"},{"t":"증산 작용은 잎 앞면에서만 일어나기 때문이다","mis":"SC6-1-u3-X38"},{"t":"뒷면에 붙이면 종이가 붉게 변하지 않기 때문이다","mis":"SC6-1-u3-X39"}],"explanation":["기공은 어디 있나요?","대부분 뒷면이에요.","그래서 뒷면이에요."],"asset":{"type":"passage","lines":["푸른색 염화 코발트 종이 한 장은 빈 페트리 접시에, 한 장은 잎 뒷면에 붙였다.","10분 뒤 잎 뒷면의 종이만 붉은색으로 변했다.","현미경으로 잎 표면을 보니 두 세포 사이에 아주 작은 구멍이 있었다.","식물원 온실에 들어가니 바깥보다 훨씬 습했다."],"title":"⑥ 증산 작용 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_a#13','sci',6,1,'u3','','g6_1_sci_u3_review_a','unit_review','SC6-1-u3-C29',2,'mc','auto','초록잎반 탐구 일지 ⑧의 놀이를 할 때 가장 중요하게 생각할 점은 어느 것인가요?',ARRAY['SC6-1-u3-X51','SC6-1-u3-X48']::text[],false,'{"seq":13,"concept":"SC6-1-u3-C29","difficulty":2,"kind":"mc","stem":"초록잎반 탐구 일지 ⑧의 놀이를 할 때 가장 중요하게 생각할 점은 어느 것인가요?","options":[{"t":"물과 양분이 지나가는 기관과 그 연결을 생각하며 따라가는 것","correct":true},{"t":"가위바위보에서 이기는 것","mis":"SC6-1-u3-X51"},{"t":"물과 양분 말이 같은 칸에 못 가게 막는 것","mis":"SC6-1-u3-X51"},{"t":"기관마다 따로따로 생각하는 것","mis":"SC6-1-u3-X48"}],"explanation":["놀이의 목적이에요.","경로를 따라가요.","연결을 생각해요."],"asset":{"type":"passage","lines":["짝과 물과 양분의 이동 놀이를 했다(물은 뿌리, 양분은 잎에서 출발).","우리 반 식물도감에 토끼풀·소나무·나팔꽃 소개 자료를 올렸다.","조사한 자료마다 출처를 적었다.","꽃가루로 옛날의 식물과 날씨를 알아낸다는 글을 읽었다."],"title":"⑧ 연결 놀이와 식물도감"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_a#14','sci',6,1,'u3','','g6_1_sci_u3_review_a','unit_review','SC6-1-u3-C4',2,'mc','auto','생물을 첨성대에 빗대어 말한 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X06','SC6-1-u3-X07']::text[],false,'{"seq":14,"concept":"SC6-1-u3-C4","difficulty":2,"kind":"mc","stem":"생물을 첨성대에 빗대어 말한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"첨성대가 돌로 이루어진 것처럼 생물은 세포로 이루어져 있다","correct":true},{"t":"첨성대 모양이 돌 모양과 같듯 생물 모양은 세포 모양과 같다","mis":"SC6-1-u3-X06"},{"t":"첨성대의 돌이 모두 같듯 한 생물의 세포는 모두 같다","mis":"SC6-1-u3-X07"},{"t":"생물마다 기본 단위가 모두 다르다","mis":"SC6-1-u3-X06"}],"explanation":["돌을 쌓았어요.","전체 모양은 달라요.","생물은 세포로 이루어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_a#15','sci',6,1,'u3','','g6_1_sci_u3_review_a','unit_review','SC6-1-u3-C14',2,'mc','auto','초록잎반 탐구 일지 ⑤의 잎에서 잎몸과 줄기를 이어 주는 부분은 어느 것인가요?',ARRAY['SC6-1-u3-X28']::text[],false,'{"seq":15,"concept":"SC6-1-u3-C14","difficulty":2,"kind":"mc","stem":"초록잎반 탐구 일지 ⑤의 잎에서 잎몸과 줄기를 이어 주는 부분은 어느 것인가요?","options":[{"t":"잎자루","correct":true},{"t":"잎맥","mis":"SC6-1-u3-X28"},{"t":"잎몸","mis":"SC6-1-u3-X28"},{"t":"기공","mis":"SC6-1-u3-X28"}],"explanation":["잎과 줄기 사이예요.","자루 부분이에요.","잎자루예요."],"asset":{"type":"passage","lines":["봉선화 잎 하나에 알루미늄 포일을 씌우고 하루 동안 햇빛에 두었다.","두 잎의 초록색을 빼고 녹말을 만나면 색이 변하는 용액을 떨어뜨렸다.","포일을 씌우지 않은 잎만 청람색으로 변했다.","잎은 잎몸과 잎자루로 되어 있고 잎몸에는 잎맥이 퍼져 있었다."],"title":"⑤ 잎 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_a#16','sci',6,1,'u3','','g6_1_sci_u3_review_a','unit_review','SC6-1-u3-C20',2,'mc','auto','기공에 관해 바르게 말한 것은 어느 것인가요?',ARRAY['SC6-1-u3-X37','SC6-1-u3-X38']::text[],false,'{"seq":16,"concept":"SC6-1-u3-C20","difficulty":2,"kind":"mc","stem":"기공에 관해 바르게 말한 것은 어느 것인가요?","options":[{"t":"잎에 도달한 물의 일부가 수증기가 되어 빠져나가는 아주 작은 구멍이다","correct":true},{"t":"뿌리에서 물을 흡수하는 구멍이다","mis":"SC6-1-u3-X37"},{"t":"줄기에 많이 모여 있는 구멍이다","mis":"SC6-1-u3-X38"},{"t":"양분이 저장되는 주머니이다","mis":"SC6-1-u3-X38"}],"explanation":["잎의 작은 구멍이에요.","물이 나가요.","기공이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_a#17','sci',6,1,'u3','','g6_1_sci_u3_review_a','unit_review','SC6-1-u3-C1',3,'error','auto','초록잎반 탐구 일지 ①을 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u3-X01','SC6-1-u3-X02','SC6-1-u3-X05']::text[],false,'{"seq":17,"concept":"SC6-1-u3-C1","difficulty":3,"kind":"error","stem":"초록잎반 탐구 일지 ①을 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서율 — 「다음엔 「이 식물은 얼마예요?」라고도 물어보자.」","correct":true,"mis_target":"SC6-1-u3-X01"},{"t":"하은 — 「꽃잎 부분만 보여 줘서 맞히기가 재미있었어.」","mis":"SC6-1-u3-X02"},{"t":"도현 — 「앱으로 알아낸 이름을 도감으로 확인한 건 잘했어.」","mis":"SC6-1-u3-X05"}],"explanation":["질문 약속이 있어요.","생김새만 물어요.","서율의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["우리 모둠은 화단의 해바라기를 다섯 고개 문제로 냈다.","사진은 꽃잎 부분만 잘라서 보여 주었다.","다른 모둠은 「나보다 키가 큰가요?」, 「꽃은 무슨 색인가요?」 등을 물었다.","앱으로 알아낸 이름은 식물도감으로 다시 확인했다."],"title":"① 다섯 고개 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_a#18','sci',6,1,'u3','','g6_1_sci_u3_review_a','unit_review','SC6-1-u3-C16',3,'error','auto','초록잎반 탐구 일지 ⑤를 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u3-X33','SC6-1-u3-X32','SC6-1-u3-X31']::text[],false,'{"seq":18,"concept":"SC6-1-u3-C16","difficulty":3,"kind":"error","stem":"초록잎반 탐구 일지 ⑤를 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"유진 — 「에탄올이 든 시험관에 코를 대고 냄새를 맡아 봤어.」","correct":true,"mis_target":"SC6-1-u3-X33"},{"t":"하루 — 「포일은 빛을 막으려고 씌웠어.」","mis":"SC6-1-u3-X32"},{"t":"도아 — 「햇빛을 받은 잎에서 양분이 만들어졌어.」","mis":"SC6-1-u3-X31"}],"explanation":["실험 안전이에요.","기체를 마시지 않아요.","유진의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["봉선화 잎 하나에 알루미늄 포일을 씌우고 하루 동안 햇빛에 두었다.","두 잎의 초록색을 빼고 녹말을 만나면 색이 변하는 용액을 떨어뜨렸다.","포일을 씌우지 않은 잎만 청람색으로 변했다.","잎은 잎몸과 잎자루로 되어 있고 잎몸에는 잎맥이 퍼져 있었다."],"title":"⑤ 잎 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_a#19','sci',6,1,'u3','','g6_1_sci_u3_review_a','unit_review','SC6-1-u3-C16',3,'mc','auto','초록잎반 탐구 일지 ⑤의 결과로 알 수 있는 것은 어느 것인가요?',ARRAY['SC6-1-u3-X31','SC6-1-u3-X30','SC6-1-u3-X35']::text[],false,'{"seq":19,"concept":"SC6-1-u3-C16","difficulty":3,"kind":"mc","stem":"초록잎반 탐구 일지 ⑤의 결과로 알 수 있는 것은 어느 것인가요?","options":[{"t":"햇빛을 받은 잎에서 녹말과 같은 양분이 만들어진다","correct":true},{"t":"포일을 씌운 잎에서 양분이 더 많이 만들어진다","mis":"SC6-1-u3-X31"},{"t":"빛과 상관없이 잎은 늘 양분을 만든다","mis":"SC6-1-u3-X30"},{"t":"잎에서 만든 양분은 잎에서만 쓰인다","mis":"SC6-1-u3-X35"}],"explanation":["청람색 잎을 봐요.","햇빛을 받았어요.","양분이 만들어졌어요."],"asset":{"type":"passage","lines":["봉선화 잎 하나에 알루미늄 포일을 씌우고 하루 동안 햇빛에 두었다.","두 잎의 초록색을 빼고 녹말을 만나면 색이 변하는 용액을 떨어뜨렸다.","포일을 씌우지 않은 잎만 청람색으로 변했다.","잎은 잎몸과 잎자루로 되어 있고 잎몸에는 잎맥이 퍼져 있었다."],"title":"⑤ 잎 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_a#20','sci',6,1,'u3','','g6_1_sci_u3_review_a','unit_review','SC6-1-u3-C7',3,'mc','auto','초록잎반 탐구 일지 ②의 표본을 만들 때 가장 알맞은 차례는 어느 것인가요?',ARRAY['SC6-1-u3-X12','SC6-1-u3-X13']::text[],false,'{"seq":20,"concept":"SC6-1-u3-C7","difficulty":3,"kind":"mc","stem":"초록잎반 탐구 일지 ②의 표본을 만들 때 가장 알맞은 차례는 어느 것인가요?","options":[{"t":"매니큐어를 얇게 바름 → 완전히 마르면 테이프를 붙여 문지름 → 떼어 받침 유리에 붙임","correct":true},{"t":"테이프를 붙임 → 매니큐어를 바름 → 받침 유리에 붙임","mis":"SC6-1-u3-X12"},{"t":"매니큐어를 두껍게 바름 → 마르기 전 테이프를 붙임 → 받침 유리에 붙임","mis":"SC6-1-u3-X12"},{"t":"받침 유리에 붙임 → 매니큐어를 바름 → 냄새를 맡아 확인함","mis":"SC6-1-u3-X13"}],"explanation":["매니큐어가 먼저예요.","마른 뒤 테이프예요.","받침 유리에 붙여요."],"asset":{"type":"passage","lines":["사철나무잎 뒷면에 투명 매니큐어를 얇게 발라 표본을 만들었다.","각진 세포들이 붙어 있고 세포의 경계가 뚜렷했다.","양파 표피세포는 세포마다 둥근 핵이 하나씩 보였다.","쉬는 시간에 달걀 하나도 하나의 세포라는 이야기를 들었다."],"title":"② 현미경으로 세포 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_a#21','sci',6,1,'u3','','g6_1_sci_u3_review_a','unit_review','SC6-1-u3-C29',3,'mc','auto','잎이 줄기에게 감사 편지를 쓴다면 들어갈 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X22','SC6-1-u3-X27','SC6-1-u3-X48']::text[],false,'{"seq":21,"concept":"SC6-1-u3-C29","difficulty":3,"kind":"mc","stem":"잎이 줄기에게 감사 편지를 쓴다면 들어갈 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「네가 뿌리의 물을 옮겨 주고 곧게 서 줘서 내가 햇빛을 받고 양분을 만들 수 있어.」","correct":true},{"t":"「네가 물을 흡수해 줘서 고마워.」","mis":"SC6-1-u3-X22"},{"t":"「네가 양분을 만들어 줘서 고마워.」","mis":"SC6-1-u3-X27"},{"t":"「우리는 서로 상관없지만 그래도 고마워.」","mis":"SC6-1-u3-X48"}],"explanation":["줄기가 하는 일이에요.","물을 옮기고 지지해요.","잎이 양분을 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_a#22','sci',6,1,'u3','','g6_1_sci_u3_review_a','unit_review','SC6-1-u3-C14',3,'mc','auto','초록잎반 탐구 일지 ⑤의 잎을 관찰한 내용을 바르게 정리한 것은 어느 것인가요?',ARRAY['SC6-1-u3-X28']::text[],false,'{"seq":22,"concept":"SC6-1-u3-C14","difficulty":3,"kind":"mc","stem":"초록잎반 탐구 일지 ⑤의 잎을 관찰한 내용을 바르게 정리한 것은 어느 것인가요?","options":[{"t":"잎몸과 잎자루로 되어 있고 잎몸에 잎맥이 퍼져 있다","correct":true},{"t":"잎자루에 잎맥이 퍼져 있고 잎몸은 없다","mis":"SC6-1-u3-X28"},{"t":"잎몸이 잎과 줄기를 잇는 자루이다","mis":"SC6-1-u3-X28"},{"t":"잎은 꽃잎과 꽃받침으로 되어 있다","mis":"SC6-1-u3-X28"}],"explanation":["일지를 읽어요.","잎몸과 잎자루예요.","잎맥은 잎몸에 있어요."],"asset":{"type":"passage","lines":["봉선화 잎 하나에 알루미늄 포일을 씌우고 하루 동안 햇빛에 두었다.","두 잎의 초록색을 빼고 녹말을 만나면 색이 변하는 용액을 떨어뜨렸다.","포일을 씌우지 않은 잎만 청람색으로 변했다.","잎은 잎몸과 잎자루로 되어 있고 잎몸에는 잎맥이 퍼져 있었다."],"title":"⑤ 잎 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_a#23','sci',6,1,'u3','','g6_1_sci_u3_review_a','unit_review','SC6-1-u3-C9',4,'essay','teacher','초록잎반 탐구 일지 ③에서 3일 뒤 물이 더 많이 줄어든 눈금실린더를 쓰고, 그렇게 된 까닭을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SC6-1-u3-C9","difficulty":4,"kind":"essay","stem":"초록잎반 탐구 일지 ③에서 3일 뒤 물이 더 많이 줄어든 눈금실린더를 쓰고, 그렇게 된 까닭을 쓰세요.","answer_guide":{"answer":"예: 뿌리를 자르지 않은 파 ㉯가 든 눈금실린더의 물이 더 많이 줄었다. 식물의 뿌리는 물을 흡수하기 때문이다.","scoring_points":["㉯(뿌리를 자르지 않은 파) 쪽이라고 썼는가","뿌리가 물을 흡수한다는 까닭을 썼는가"]},"explanation":["일지를 봐요.","㉯ 쪽이에요.","뿌리가 물을 흡수해요."],"asset":{"type":"passage","lines":["파 ㉮는 뿌리를 자르고 파 ㉯는 뿌리를 그대로 두었다.","두 파를 같은 양의 물에 넣어 햇빛 드는 창가에 3일 두었다.","㉮ 쪽 물은 조금, ㉯ 쪽 물은 많이 줄었다.","짝꿍 화분의 강아지풀은 가는 뿌리가 수염처럼 나 있었다."],"title":"③ 뿌리 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_a#24','sci',6,1,'u3','','g6_1_sci_u3_review_a','unit_review','SC6-1-u3-C21',4,'mc','auto','물이 부족한 곳에 사는 식물 ㉮는 잎이 좁고, 물이 많은 곳에 사는 식물 ㉯는 잎이 넓어요. 이를 바르게 설명한 것은 어느 것인가요?',ARRAY['SC6-1-u3-X37','SC6-1-u3-X41','SC6-1-u3-X40']::text[],false,'{"seq":24,"concept":"SC6-1-u3-C21","difficulty":4,"kind":"mc","stem":"물이 부족한 곳에 사는 식물 ㉮는 잎이 좁고, 물이 많은 곳에 사는 식물 ㉯는 잎이 넓어요. 이를 바르게 설명한 것은 어느 것인가요?","options":[{"t":"㉮는 잎이 좁아 증산 작용으로 물을 덜 잃어 살아가기에 유리하다","correct":true},{"t":"㉮는 잎이 좁아 공기 중 수증기를 더 많이 빨아들인다","mis":"SC6-1-u3-X37"},{"t":"증산 작용은 물을 버리기만 하니 둘 다 잎이 없을수록 좋다","mis":"SC6-1-u3-X41"},{"t":"증발과 증산 작용은 다른 현상이라 잎 넓이와 상관없다","mis":"SC6-1-u3-X40"}],"explanation":["물이 부족해요.","좁은 잎은 물을 덜 잃어요.","그래서 유리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_a#25','sci',6,1,'u3','','g6_1_sci_u3_review_a','unit_review','SC6-1-u3-C29',4,'mc','auto','어느 화분의 줄기가 꺾여 물이 이동하는 통로가 막혔어요. 이 식물에서 일어날 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X48','SC6-1-u3-X22','SC6-1-u3-X49']::text[],false,'{"seq":25,"concept":"SC6-1-u3-C29","difficulty":4,"kind":"mc","stem":"어느 화분의 줄기가 꺾여 물이 이동하는 통로가 막혔어요. 이 식물에서 일어날 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"뿌리의 물이 잎에 닿지 못하고, 잎에서 만든 양분도 뿌리로 가지 못해 식물 전체가 약해진다","correct":true},{"t":"줄기만 다쳤으니 잎과 뿌리는 아무 영향이 없다","mis":"SC6-1-u3-X48"},{"t":"잎이 직접 물을 흡수해 금방 괜찮아진다","mis":"SC6-1-u3-X22"},{"t":"양분은 원래 뿌리에서 만들어지니 상관없다","mis":"SC6-1-u3-X49"}],"explanation":["통로가 막혔어요.","물과 양분이 못 가요.","전체가 약해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_b#1','sci',6,1,'u3','','g6_1_sci_u3_review_b','unit_review','SC6-1-u3-C4',1,'sa','auto','초록잎반 탐구 일지 ②에서 관찰한 사철나무잎과 양파는 모두 무엇으로 이루어져 있나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC6-1-u3-C4","difficulty":1,"kind":"sa","stem":"초록잎반 탐구 일지 ②에서 관찰한 사철나무잎과 양파는 모두 무엇으로 이루어져 있나요? 두 글자로 쓰세요.","answer":["세포"],"explanation":["현미경으로 봤어요.","기본 단위예요.","세포예요."],"asset":{"type":"passage","lines":["사철나무잎 뒷면에 투명 매니큐어를 얇게 발라 표본을 만들었다.","각진 세포들이 붙어 있고 세포의 경계가 뚜렷했다.","양파 표피세포는 세포마다 둥근 핵이 하나씩 보였다.","쉬는 시간에 달걀 하나도 하나의 세포라는 이야기를 들었다."],"title":"② 현미경으로 세포 관찰"},"mis":"SC6-1-u3-X06"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_b#2','sci',6,1,'u3','','g6_1_sci_u3_review_b','unit_review','SC6-1-u3-C15',1,'sa','auto','초록잎반 탐구 일지 ⑤의 실험은 식물이 빛을 이용해 양분을 만드는 일을 알아본 것이에요. 이 일을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC6-1-u3-C15","difficulty":1,"kind":"sa","stem":"초록잎반 탐구 일지 ⑤의 실험은 식물이 빛을 이용해 양분을 만드는 일을 알아본 것이에요. 이 일을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["광합성"],"explanation":["빛으로 양분을 만들어요.","세 글자예요.","광합성이에요."],"asset":{"type":"passage","lines":["봉선화 잎 하나에 알루미늄 포일을 씌우고 하루 동안 햇빛에 두었다.","두 잎의 초록색을 빼고 녹말을 만나면 색이 변하는 용액을 떨어뜨렸다.","포일을 씌우지 않은 잎만 청람색으로 변했다.","잎은 잎몸과 잎자루로 되어 있고 잎몸에는 잎맥이 퍼져 있었다."],"title":"⑤ 잎 실험"},"mis":"SC6-1-u3-X29"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_b#3','sci',6,1,'u3','','g6_1_sci_u3_review_b','unit_review','SC6-1-u3-C9',1,'ox','auto','초록잎반 탐구 일지 ③에서 다르게 한 조건은 뿌리가 있는지예요.',ARRAY['SC6-1-u3-X17']::text[],false,'{"seq":3,"concept":"SC6-1-u3-C9","difficulty":1,"kind":"ox","stem":"초록잎반 탐구 일지 ③에서 다르게 한 조건은 뿌리가 있는지예요.","answer":"O","reason_options":[{"t":"물의 양과 놓아둔 곳은 같게 하고 뿌리만 다르게 했기 때문에","correct":true},{"t":"물의 양도 두 파가 다르게 넣었기 때문에","mis":"SC6-1-u3-X17"}],"mis":"SC6-1-u3-X17","explanation":["무엇을 다르게 했나요?","뿌리만 달라요.","맞는 말이에요."],"asset":{"type":"passage","lines":["파 ㉮는 뿌리를 자르고 파 ㉯는 뿌리를 그대로 두었다.","두 파를 같은 양의 물에 넣어 햇빛 드는 창가에 3일 두었다.","㉮ 쪽 물은 조금, ㉯ 쪽 물은 많이 줄었다.","짝꿍 화분의 강아지풀은 가는 뿌리가 수염처럼 나 있었다."],"title":"③ 뿌리 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_b#4','sci',6,1,'u3','','g6_1_sci_u3_review_b','unit_review','SC6-1-u3-C18',1,'mc','auto','초록잎반 탐구 일지 ⑥에서 온실 안이 바깥보다 습했던 까닭과 관계있는 것은 어느 것인가요?',ARRAY['SC6-1-u3-X37']::text[],false,'{"seq":4,"concept":"SC6-1-u3-C18","difficulty":1,"kind":"mc","stem":"초록잎반 탐구 일지 ⑥에서 온실 안이 바깥보다 습했던 까닭과 관계있는 것은 어느 것인가요?","options":[{"t":"증산 작용","correct":true},{"t":"광합성","mis":"SC6-1-u3-X37"},{"t":"뿌리의 지지","mis":"SC6-1-u3-X37"},{"t":"꽃가루받이","mis":"SC6-1-u3-X37"}],"explanation":["식물이 많아요.","잎에서 수증기가 나와요.","증산 작용이에요."],"asset":{"type":"passage","lines":["푸른색 염화 코발트 종이 한 장은 빈 페트리 접시에, 한 장은 잎 뒷면에 붙였다.","10분 뒤 잎 뒷면의 종이만 붉은색으로 변했다.","현미경으로 잎 표면을 보니 두 세포 사이에 아주 작은 구멍이 있었다.","식물원 온실에 들어가니 바깥보다 훨씬 습했다."],"title":"⑥ 증산 작용 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_b#5','sci',6,1,'u3','','g6_1_sci_u3_review_b','unit_review','SC6-1-u3-C6',1,'mc','auto','초록잎반 탐구 일지 ②의 이야기에서 맨눈으로 볼 수 있는 하나의 세포로 나온 것은 어느 것인가요?',ARRAY['SC6-1-u3-X11','SC6-1-u3-X10']::text[],false,'{"seq":5,"concept":"SC6-1-u3-C6","difficulty":1,"kind":"mc","stem":"초록잎반 탐구 일지 ②의 이야기에서 맨눈으로 볼 수 있는 하나의 세포로 나온 것은 어느 것인가요?","options":[{"t":"달걀","correct":true},{"t":"양파 표피세포","mis":"SC6-1-u3-X11"},{"t":"사철나무잎 세포","mis":"SC6-1-u3-X11"},{"t":"맨눈으로 보이는 세포는 없다","mis":"SC6-1-u3-X10"}],"explanation":["쉬는 시간 이야기예요.","달걀은 하나의 세포예요.","맨눈으로 보여요."],"asset":{"type":"passage","lines":["사철나무잎 뒷면에 투명 매니큐어를 얇게 발라 표본을 만들었다.","각진 세포들이 붙어 있고 세포의 경계가 뚜렷했다.","양파 표피세포는 세포마다 둥근 핵이 하나씩 보였다.","쉬는 시간에 달걀 하나도 하나의 세포라는 이야기를 들었다."],"title":"② 현미경으로 세포 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_b#6','sci',6,1,'u3','','g6_1_sci_u3_review_b','unit_review','SC6-1-u3-C12',1,'ox','auto','줄기는 뿌리와 잎, 꽃 등을 연결해요.',ARRAY['SC6-1-u3-X48']::text[],false,'{"seq":6,"concept":"SC6-1-u3-C12","difficulty":1,"kind":"ox","stem":"줄기는 뿌리와 잎, 꽃 등을 연결해요.","answer":"O","reason_options":[{"t":"줄기를 통해 뿌리의 물이 잎과 꽃으로 가기 때문에","correct":true},{"t":"줄기는 다른 기관과 떨어져 있기 때문에","mis":"SC6-1-u3-X48"}],"mis":"SC6-1-u3-X48","explanation":["줄기의 자리를 봐요.","뿌리와 잎 사이예요.","연결해 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_b#7','sci',6,1,'u3','','g6_1_sci_u3_review_b','unit_review','SC6-1-u3-C32',1,'mc','auto','초록잎반 탐구 일지 ⑧의 글에서 꽃가루로 알아낸다고 한 것은 어느 것인가요?',ARRAY['SC6-1-u3-X54']::text[],false,'{"seq":7,"concept":"SC6-1-u3-C32","difficulty":1,"kind":"mc","stem":"초록잎반 탐구 일지 ⑧의 글에서 꽃가루로 알아낸다고 한 것은 어느 것인가요?","options":[{"t":"옛날의 식물과 날씨","correct":true},{"t":"오늘 먹을 급식 메뉴","mis":"SC6-1-u3-X54"},{"t":"식물의 값","mis":"SC6-1-u3-X54"},{"t":"꽃가루가 앨러지를 일으키는 까닭만","mis":"SC6-1-u3-X54"}],"explanation":["글을 읽어요.","옛날을 알아내요.","식물과 날씨예요."],"asset":{"type":"passage","lines":["짝과 물과 양분의 이동 놀이를 했다(물은 뿌리, 양분은 잎에서 출발).","우리 반 식물도감에 토끼풀·소나무·나팔꽃 소개 자료를 올렸다.","조사한 자료마다 출처를 적었다.","꽃가루로 옛날의 식물과 날씨를 알아낸다는 글을 읽었다."],"title":"⑧ 연결 놀이와 식물도감"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_b#8','sci',6,1,'u3','','g6_1_sci_u3_review_b','unit_review','SC6-1-u3-C17',1,'mc','auto','잎에서 만든 양분이 식물 전체로 가는 길은 어느 것인가요?',ARRAY['SC6-1-u3-X35']::text[],false,'{"seq":8,"concept":"SC6-1-u3-C17","difficulty":1,"kind":"mc","stem":"잎에서 만든 양분이 식물 전체로 가는 길은 어느 것인가요?","options":[{"t":"줄기","correct":true},{"t":"기공","mis":"SC6-1-u3-X35"},{"t":"뿌리털","mis":"SC6-1-u3-X35"},{"t":"꽃받침","mis":"SC6-1-u3-X35"}],"explanation":["양분이 움직여요.","통로를 지나요.","줄기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_b#9','sci',6,1,'u3','','g6_1_sci_u3_review_b','unit_review','SC6-1-u3-C5',2,'mc','auto','초록잎반 탐구 일지 ②에서 사철나무잎 세포의 경계가 뚜렷했던 까닭은 무엇인가요?',ARRAY['SC6-1-u3-X09','SC6-1-u3-X08']::text[],false,'{"seq":9,"concept":"SC6-1-u3-C5","difficulty":2,"kind":"mc","stem":"초록잎반 탐구 일지 ②에서 사철나무잎 세포의 경계가 뚜렷했던 까닭은 무엇인가요?","options":[{"t":"세포막 바깥을 세포벽이 둘러싸고 있기 때문이다","correct":true},{"t":"세포마다 핵이 여러 개 있기 때문이다","mis":"SC6-1-u3-X09"},{"t":"세포막이 없기 때문이다","mis":"SC6-1-u3-X09"},{"t":"세포벽이 세포 안쪽 가운데에 있기 때문이다","mis":"SC6-1-u3-X08"}],"explanation":["식물 세포예요.","세포벽이 있어요.","그래서 뚜렷해요."],"asset":{"type":"passage","lines":["사철나무잎 뒷면에 투명 매니큐어를 얇게 발라 표본을 만들었다.","각진 세포들이 붙어 있고 세포의 경계가 뚜렷했다.","양파 표피세포는 세포마다 둥근 핵이 하나씩 보였다.","쉬는 시간에 달걀 하나도 하나의 세포라는 이야기를 들었다."],"title":"② 현미경으로 세포 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_b#10','sci',6,1,'u3','','g6_1_sci_u3_review_b','unit_review','SC6-1-u3-C16',2,'mc','auto','초록잎반 탐구 일지 ⑤에서 포일을 씌운 잎을 함께 준비한 까닭은 무엇인가요?',ARRAY['SC6-1-u3-X32','SC6-1-u3-X31','SC6-1-u3-X33']::text[],false,'{"seq":10,"concept":"SC6-1-u3-C16","difficulty":2,"kind":"mc","stem":"초록잎반 탐구 일지 ⑤에서 포일을 씌운 잎을 함께 준비한 까닭은 무엇인가요?","options":[{"t":"빛을 받지 못한 잎과 견주어 빛이 하는 일을 알아보려고","correct":true},{"t":"포일이 잎의 양분을 늘려 주기 때문에","mis":"SC6-1-u3-X32"},{"t":"포일을 씌운 잎이 청람색으로 더 잘 변하기 때문에","mis":"SC6-1-u3-X31"},{"t":"에탄올을 덜 쓰려고","mis":"SC6-1-u3-X33"}],"explanation":["포일은 빛을 막아요.","빛만 다르게 해요.","두 잎을 견줘요."],"asset":{"type":"passage","lines":["봉선화 잎 하나에 알루미늄 포일을 씌우고 하루 동안 햇빛에 두었다.","두 잎의 초록색을 빼고 녹말을 만나면 색이 변하는 용액을 떨어뜨렸다.","포일을 씌우지 않은 잎만 청람색으로 변했다.","잎은 잎몸과 잎자루로 되어 있고 잎몸에는 잎맥이 퍼져 있었다."],"title":"⑤ 잎 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_b#11','sci',6,1,'u3','','g6_1_sci_u3_review_b','unit_review','SC6-1-u3-C6',2,'mc','auto','초록잎반 탐구 일지 ②의 달걀 이야기로 바로잡을 수 있는 생각은 어느 것인가요?',ARRAY['SC6-1-u3-X11','SC6-1-u3-X06','SC6-1-u3-X08']::text[],false,'{"seq":11,"concept":"SC6-1-u3-C6","difficulty":2,"kind":"mc","stem":"초록잎반 탐구 일지 ②의 달걀 이야기로 바로잡을 수 있는 생각은 어느 것인가요?","options":[{"t":"모든 세포는 맨눈으로 볼 수 없다","correct":true},{"t":"대부분의 세포는 아주 작다","mis":"SC6-1-u3-X11"},{"t":"생물은 세포로 이루어져 있다","mis":"SC6-1-u3-X06"},{"t":"식물 세포에는 세포벽이 있다","mis":"SC6-1-u3-X08"}],"explanation":["달걀도 세포예요.","맨눈으로 보여요.","「모든」이 틀렸어요."],"asset":{"type":"passage","lines":["사철나무잎 뒷면에 투명 매니큐어를 얇게 발라 표본을 만들었다.","각진 세포들이 붙어 있고 세포의 경계가 뚜렷했다.","양파 표피세포는 세포마다 둥근 핵이 하나씩 보였다.","쉬는 시간에 달걀 하나도 하나의 세포라는 이야기를 들었다."],"title":"② 현미경으로 세포 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_b#12','sci',6,1,'u3','','g6_1_sci_u3_review_b','unit_review','SC6-1-u3-C23',2,'mc','auto','초록잎반 탐구 일지 ⑦의 벌처럼 꽃가루받이를 돕는 것끼리 모은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X44','SC6-1-u3-X46']::text[],false,'{"seq":12,"concept":"SC6-1-u3-C23","difficulty":2,"kind":"mc","stem":"초록잎반 탐구 일지 ⑦의 벌처럼 꽃가루받이를 돕는 것끼리 모은 것은 어느 것인가요?","options":[{"t":"곤충, 새, 바람, 물","correct":true},{"t":"뿌리털, 기공, 잎맥","mis":"SC6-1-u3-X44"},{"t":"세포벽, 핵, 세포막","mis":"SC6-1-u3-X44"},{"t":"열매, 씨, 꽃받침","mis":"SC6-1-u3-X46"}],"explanation":["꽃가루를 옮겨요.","곤충·새·바람·물이에요.","알맞게 모았어요."],"asset":{"type":"passage","lines":["제라늄꽃을 암술·수술·꽃잎·꽃받침으로 나누어 흰 종이에 놓았다.","꽃가루 앨러지가 있는 친구는 보안경과 마스크를 썼다.","벌이 꽃 사이를 날아다니며 꽃가루를 묻히는 영상을 보았다.","복숭아 열매를 잘라 속에 든 씨를 찾아보았다."],"title":"⑦ 꽃 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_b#13','sci',6,1,'u3','','g6_1_sci_u3_review_b','unit_review','SC6-1-u3-C32',2,'mc','auto','꽃가루를 바르게 이해한 말은 어느 것인가요?',ARRAY['SC6-1-u3-X54','SC6-1-u3-X55']::text[],false,'{"seq":13,"concept":"SC6-1-u3-C32","difficulty":2,"kind":"mc","stem":"꽃가루를 바르게 이해한 말은 어느 것인가요?","options":[{"t":"꽃가루는 앨러지를 일으키기도 하지만 우리 생활 여러 곳에 쓰인다","correct":true},{"t":"꽃가루는 앨러지만 일으키는 쓸모없는 것이다","mis":"SC6-1-u3-X54"},{"t":"꽃가루는 크고 모양이 모두 같다","mis":"SC6-1-u3-X55"},{"t":"꽃가루는 금방 모양이 변해 남지 않는다","mis":"SC6-1-u3-X55"}],"explanation":["꽃가루의 쓰임이에요.","여러 곳에 쓰여요.","바르게 이해해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_b#14','sci',6,1,'u3','','g6_1_sci_u3_review_b','unit_review','SC6-1-u3-C12',2,'mc','auto','줄기가 하는 일이 아닌 것은 어느 것인가요?',ARRAY['SC6-1-u3-X22','SC6-1-u3-X26','SC6-1-u3-X48']::text[],false,'{"seq":14,"concept":"SC6-1-u3-C12","difficulty":2,"kind":"mc","stem":"줄기가 하는 일이 아닌 것은 어느 것인가요?","options":[{"t":"물을 흡수한다","correct":true},{"t":"물이 이동하는 통로가 된다","mis":"SC6-1-u3-X22"},{"t":"식물을 지지한다","mis":"SC6-1-u3-X26"},{"t":"뿌리와 잎, 꽃을 연결한다","mis":"SC6-1-u3-X48"}],"explanation":["줄기의 일을 떠올려요.","흡수는 뿌리예요.","물 흡수가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_b#15','sci',6,1,'u3','','g6_1_sci_u3_review_b','unit_review','SC6-1-u3-C21',2,'mc','auto','증발과 증산 작용을 바르게 말한 것은 어느 것인가요?',ARRAY['SC6-1-u3-X40','SC6-1-u3-X37']::text[],false,'{"seq":15,"concept":"SC6-1-u3-C21","difficulty":2,"kind":"mc","stem":"증발과 증산 작용을 바르게 말한 것은 어느 것인가요?","options":[{"t":"둘 다 물이 수증기가 되는 일이고, 증산 작용은 식물의 잎에서 일어난다","correct":true},{"t":"증발과 증산 작용은 전혀 다른 현상이다","mis":"SC6-1-u3-X40"},{"t":"증산 작용은 수증기가 잎으로 들어오는 일이다","mis":"SC6-1-u3-X37"},{"t":"증발은 잎의 기공에서만 일어난다","mis":"SC6-1-u3-X40"}],"explanation":["물이 수증기가 돼요.","그 점은 같아요.","증산은 잎에서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_b#16','sci',6,1,'u3','','g6_1_sci_u3_review_b','unit_review','SC6-1-u3-C8',2,'mc','auto','뿌리털이 많이 난 뿌리가 좋은 까닭은 무엇인가요?',ARRAY['SC6-1-u3-X15','SC6-1-u3-X14']::text[],false,'{"seq":16,"concept":"SC6-1-u3-C8","difficulty":2,"kind":"mc","stem":"뿌리털이 많이 난 뿌리가 좋은 까닭은 무엇인가요?","options":[{"t":"물을 잘 흡수할 수 있기 때문이다","correct":true},{"t":"양분을 많이 만들 수 있기 때문이다","mis":"SC6-1-u3-X15"},{"t":"뿌리털은 하는 일이 없어 상관없다","mis":"SC6-1-u3-X15"},{"t":"모든 식물이 같은 뿌리를 가지기 때문이다","mis":"SC6-1-u3-X14"}],"explanation":["뿌리털이에요.","물에 닿는 곳이 많아요.","물을 잘 흡수해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_b#17','sci',6,1,'u3','','g6_1_sci_u3_review_b','unit_review','SC6-1-u3-C5',3,'error','auto','초록잎반 탐구 일지 ②를 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u3-X09','SC6-1-u3-X08']::text[],false,'{"seq":17,"concept":"SC6-1-u3-C5","difficulty":3,"kind":"error","stem":"초록잎반 탐구 일지 ②를 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준호 — 「식물 세포는 세포벽만 있고 세포막은 없어.」","correct":true,"mis_target":"SC6-1-u3-X09"},{"t":"예린 — 「세포마다 둥근 핵이 하나씩 있었어.」","mis":"SC6-1-u3-X09"},{"t":"시우 — 「세포벽 덕분에 경계가 뚜렷했어.」","mis":"SC6-1-u3-X08"}],"explanation":["세포의 구조예요.","세포막도 있어요.","준호의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["사철나무잎 뒷면에 투명 매니큐어를 얇게 발라 표본을 만들었다.","각진 세포들이 붙어 있고 세포의 경계가 뚜렷했다.","양파 표피세포는 세포마다 둥근 핵이 하나씩 보였다.","쉬는 시간에 달걀 하나도 하나의 세포라는 이야기를 들었다."],"title":"② 현미경으로 세포 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_b#18','sci',6,1,'u3','','g6_1_sci_u3_review_b','unit_review','SC6-1-u3-C21',3,'error','auto','초록잎반 탐구 일지 ⑥을 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u3-X41','SC6-1-u3-X39','SC6-1-u3-X37']::text[],false,'{"seq":18,"concept":"SC6-1-u3-C21","difficulty":3,"kind":"error","stem":"초록잎반 탐구 일지 ⑥을 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은솔 — 「증산 작용은 물을 버리기만 하는 쓸모없는 일이야.」","correct":true,"mis_target":"SC6-1-u3-X41"},{"t":"다온 — 「잎 뒷면에서 물이 빠져나와 종이가 붉어졌어.」","mis":"SC6-1-u3-X39"},{"t":"리하 — 「온실이 습한 것도 증산 작용 때문이야.」","mis":"SC6-1-u3-X37"}],"explanation":["증산 작용이 하는 일이 있어요.","물을 끌어올리고 온도를 조절해요.","은솔의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["푸른색 염화 코발트 종이 한 장은 빈 페트리 접시에, 한 장은 잎 뒷면에 붙였다.","10분 뒤 잎 뒷면의 종이만 붉은색으로 변했다.","현미경으로 잎 표면을 보니 두 세포 사이에 아주 작은 구멍이 있었다.","식물원 온실에 들어가니 바깥보다 훨씬 습했다."],"title":"⑥ 증산 작용 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_b#19','sci',6,1,'u3','','g6_1_sci_u3_review_b','unit_review','SC6-1-u3-C19',3,'mc','auto','초록잎반 탐구 일지 ⑥의 결과로 알 수 있는 것은 어느 것인가요?',ARRAY['SC6-1-u3-X37','SC6-1-u3-X39','SC6-1-u3-X38']::text[],false,'{"seq":19,"concept":"SC6-1-u3-C19","difficulty":3,"kind":"mc","stem":"초록잎반 탐구 일지 ⑥의 결과로 알 수 있는 것은 어느 것인가요?","options":[{"t":"잎을 통해 물이 식물 밖으로 빠져나간다","correct":true},{"t":"공기 중의 수증기가 잎으로 들어간다","mis":"SC6-1-u3-X37"},{"t":"페트리 접시에서도 물이 나온다","mis":"SC6-1-u3-X39"},{"t":"증산 작용은 줄기에서 일어난다","mis":"SC6-1-u3-X38"}],"explanation":["잎 뒷면 종이만 붉어요.","잎에서 물이 나왔어요.","물이 빠져나가요."],"asset":{"type":"passage","lines":["푸른색 염화 코발트 종이 한 장은 빈 페트리 접시에, 한 장은 잎 뒷면에 붙였다.","10분 뒤 잎 뒷면의 종이만 붉은색으로 변했다.","현미경으로 잎 표면을 보니 두 세포 사이에 아주 작은 구멍이 있었다.","식물원 온실에 들어가니 바깥보다 훨씬 습했다."],"title":"⑥ 증산 작용 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_b#20','sci',6,1,'u3','','g6_1_sci_u3_review_b','unit_review','SC6-1-u3-C10',3,'mc','auto','당근과 고구마의 공통점으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X25','SC6-1-u3-X19','SC6-1-u3-X20']::text[],false,'{"seq":20,"concept":"SC6-1-u3-C10","difficulty":3,"kind":"mc","stem":"당근과 고구마의 공통점으로 알맞은 것은 어느 것인가요?","options":[{"t":"뿌리에 양분을 저장한다","correct":true},{"t":"줄기에 양분을 저장한다","mis":"SC6-1-u3-X25"},{"t":"뿌리에서 양분을 만든다","mis":"SC6-1-u3-X19"},{"t":"뿌리에는 아무것도 저장하지 않는다","mis":"SC6-1-u3-X20"}],"explanation":["둘 다 땅속에 있어요.","굵은 뿌리예요.","양분을 저장해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_b#21','sci',6,1,'u3','','g6_1_sci_u3_review_b','unit_review','SC6-1-u3-C15',3,'mc','auto','광합성에 관해 바르게 말한 것을 모두 고른 것은 어느 것인가요?',ARRAY['SC6-1-u3-X29','SC6-1-u3-X30','SC6-1-u3-X35']::text[],false,'{"seq":21,"concept":"SC6-1-u3-C15","difficulty":3,"kind":"mc","stem":"광합성에 관해 바르게 말한 것을 모두 고른 것은 어느 것인가요?","options":[{"t":"빛이 필요하다, 이산화 탄소와 물로 양분을 만든다","correct":true},{"t":"잎에서만 일어난다, 물을 만든다","mis":"SC6-1-u3-X29"},{"t":"산소와 이산화 탄소로 양분을 만든다","mis":"SC6-1-u3-X30"},{"t":"양분은 잎에서만 쓰인다","mis":"SC6-1-u3-X35"}],"explanation":["광합성을 떠올려요.","빛이 필요해요.","재료는 이산화 탄소와 물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_b#22','sci',6,1,'u3','','g6_1_sci_u3_review_b','unit_review','SC6-1-u3-C20',3,'mc','auto','초록잎반 탐구 일지 ⑥에서 종이를 잎 뒷면이 아니라 앞면에 붙였다면 결과가 어떠했을지 가장 알맞게 예상한 것은 어느 것인가요?',ARRAY['SC6-1-u3-X38','SC6-1-u3-X37','SC6-1-u3-X39']::text[],false,'{"seq":22,"concept":"SC6-1-u3-C20","difficulty":3,"kind":"mc","stem":"초록잎반 탐구 일지 ⑥에서 종이를 잎 뒷면이 아니라 앞면에 붙였다면 결과가 어떠했을지 가장 알맞게 예상한 것은 어느 것인가요?","options":[{"t":"기공이 적은 앞면이라 뒷면보다 색 변화가 늦거나 적었을 것이다","correct":true},{"t":"앞면에서 증산 작용이 더 많이 일어나 더 빨리 붉어졌을 것이다","mis":"SC6-1-u3-X38"},{"t":"잎이 공기의 수증기를 빨아들여 종이가 더 푸르러졌을 것이다","mis":"SC6-1-u3-X37"},{"t":"페트리 접시의 종이도 함께 붉어졌을 것이다","mis":"SC6-1-u3-X39"}],"explanation":["기공은 어디 많나요?","대부분 뒷면이에요.","앞면은 변화가 적어요."],"asset":{"type":"passage","lines":["푸른색 염화 코발트 종이 한 장은 빈 페트리 접시에, 한 장은 잎 뒷면에 붙였다.","10분 뒤 잎 뒷면의 종이만 붉은색으로 변했다.","현미경으로 잎 표면을 보니 두 세포 사이에 아주 작은 구멍이 있었다.","식물원 온실에 들어가니 바깥보다 훨씬 습했다."],"title":"⑥ 증산 작용 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_b#23','sci',6,1,'u3','','g6_1_sci_u3_review_b','unit_review','SC6-1-u3-C16',4,'essay','teacher','초록잎반 탐구 일지 ⑤의 실험이 무엇을 알아보는 실험인지 쓰고, 포일을 씌우지 않은 잎에서 나타난 변화와 알 수 있는 사실을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SC6-1-u3-C16","difficulty":4,"kind":"essay","stem":"초록잎반 탐구 일지 ⑤의 실험이 무엇을 알아보는 실험인지 쓰고, 포일을 씌우지 않은 잎에서 나타난 변화와 알 수 있는 사실을 쓰세요.","answer_guide":{"answer":"예: 식물이 광합성으로 만드는 양분을 확인하는 실험이다. 포일을 씌우지 않은 잎은 청람색으로 변했고, 햇빛을 받은 잎에서 녹말과 같은 양분이 만들어진다는 것을 알 수 있다.","scoring_points":["광합성으로 만든 양분을 확인하는 실험이라고 썼는가","청람색으로 변했다고 썼는가","햇빛을 받은 잎에서 양분이 만들어진다고 썼는가"]},"explanation":["실험의 목적이에요.","청람색 변화예요.","빛을 받은 잎이 양분을 만들어요."],"asset":{"type":"passage","lines":["봉선화 잎 하나에 알루미늄 포일을 씌우고 하루 동안 햇빛에 두었다.","두 잎의 초록색을 빼고 녹말을 만나면 색이 변하는 용액을 떨어뜨렸다.","포일을 씌우지 않은 잎만 청람색으로 변했다.","잎은 잎몸과 잎자루로 되어 있고 잎몸에는 잎맥이 퍼져 있었다."],"title":"⑤ 잎 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_b#24','sci',6,1,'u3','','g6_1_sci_u3_review_b','unit_review','SC6-1-u3-C28',4,'mc','auto','감자를 심어 기를 때 잎이 많이 상하면 땅속 감자가 잘 굵어지지 않는다고 해요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X25','SC6-1-u3-X50','SC6-1-u3-X19']::text[],false,'{"seq":24,"concept":"SC6-1-u3-C28","difficulty":4,"kind":"mc","stem":"감자를 심어 기를 때 잎이 많이 상하면 땅속 감자가 잘 굵어지지 않는다고 해요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"잎에서 만든 양분이 줄기로 옮겨져 감자에 저장되는데, 잎이 상하면 양분을 덜 만들기 때문이다","correct":true},{"t":"감자는 뿌리라서 잎과 상관없이 스스로 양분을 만들기 때문이다","mis":"SC6-1-u3-X25"},{"t":"잎이 상하면 남은 양분이 모두 버려지기 때문이다","mis":"SC6-1-u3-X50"},{"t":"감자에 저장되는 양분은 원래 뿌리에서 만들어지기 때문이다","mis":"SC6-1-u3-X19"}],"explanation":["양분은 잎에서 만들어요.","줄기로 옮겨 저장해요.","잎이 상하면 양분이 줄어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_b#25','sci',6,1,'u3','','g6_1_sci_u3_review_b','unit_review','SC6-1-u3-C26',4,'mc','auto','사과나무의 기관 하나를 바꿀 수 있다면 어떻게 바꾸겠느냐는 물음에 가장 알맞게 답한 것은 어느 것인가요?',ARRAY['SC6-1-u3-X22','SC6-1-u3-X45','SC6-1-u3-X46']::text[],false,'{"seq":25,"concept":"SC6-1-u3-C26","difficulty":4,"kind":"mc","stem":"사과나무의 기관 하나를 바꿀 수 있다면 어떻게 바꾸겠느냐는 물음에 가장 알맞게 답한 것은 어느 것인가요?","options":[{"t":"「잎을 더 넓게 만들어 빛을 많이 받게 하면 광합성으로 양분을 더 많이 만들 수 있을 거야.」","correct":true},{"t":"「뿌리를 없애도 줄기가 물을 흡수하니 괜찮아.」","mis":"SC6-1-u3-X22"},{"t":"「꽃을 더 화려하게 하면 꽃이 양분을 만들 거야.」","mis":"SC6-1-u3-X45"},{"t":"「열매를 크게 하면 열매가 씨를 더 많이 만들 거야.」","mis":"SC6-1-u3-X46"}],"explanation":["기관이 하는 일을 떠올려요.","잎은 양분을 만들어요.","하는 일과 이어 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_c#1','sci',6,1,'u3','','g6_1_sci_u3_review_c','unit_review','SC6-1-u3-C10',1,'mc','auto','초록잎반 탐구 일지 ③의 결과로 알 수 있는 뿌리가 하는 일은 어느 것인가요?',ARRAY['SC6-1-u3-X19','SC6-1-u3-X15','SC6-1-u3-X16']::text[],false,'{"seq":1,"concept":"SC6-1-u3-C10","difficulty":1,"kind":"mc","stem":"초록잎반 탐구 일지 ③의 결과로 알 수 있는 뿌리가 하는 일은 어느 것인가요?","options":[{"t":"물을 흡수한다","correct":true},{"t":"양분을 만든다","mis":"SC6-1-u3-X19"},{"t":"꽃가루를 만든다","mis":"SC6-1-u3-X15"},{"t":"물을 수증기로 내보낸다","mis":"SC6-1-u3-X16"}],"explanation":["㉯ 쪽 물이 많이 줄었어요.","뿌리가 있는 쪽이에요.","물을 흡수해요."],"asset":{"type":"passage","lines":["파 ㉮는 뿌리를 자르고 파 ㉯는 뿌리를 그대로 두었다.","두 파를 같은 양의 물에 넣어 햇빛 드는 창가에 3일 두었다.","㉮ 쪽 물은 조금, ㉯ 쪽 물은 많이 줄었다.","짝꿍 화분의 강아지풀은 가는 뿌리가 수염처럼 나 있었다."],"title":"③ 뿌리 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_c#2','sci',6,1,'u3','','g6_1_sci_u3_review_c','unit_review','SC6-1-u3-C20',1,'mc','auto','초록잎반 탐구 일지 ⑥에서 잎 표면의 두 세포 사이에 있는 아주 작은 구멍의 이름은 어느 것인가요?',ARRAY['SC6-1-u3-X38']::text[],false,'{"seq":2,"concept":"SC6-1-u3-C20","difficulty":1,"kind":"mc","stem":"초록잎반 탐구 일지 ⑥에서 잎 표면의 두 세포 사이에 있는 아주 작은 구멍의 이름은 어느 것인가요?","options":[{"t":"기공","correct":true},{"t":"잎맥","mis":"SC6-1-u3-X38"},{"t":"뿌리털","mis":"SC6-1-u3-X38"},{"t":"핵","mis":"SC6-1-u3-X38"}],"explanation":["아주 작은 구멍이에요.","물이 빠져나가요.","기공이에요."],"asset":{"type":"passage","lines":["푸른색 염화 코발트 종이 한 장은 빈 페트리 접시에, 한 장은 잎 뒷면에 붙였다.","10분 뒤 잎 뒷면의 종이만 붉은색으로 변했다.","현미경으로 잎 표면을 보니 두 세포 사이에 아주 작은 구멍이 있었다.","식물원 온실에 들어가니 바깥보다 훨씬 습했다."],"title":"⑥ 증산 작용 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_c#3','sci',6,1,'u3','','g6_1_sci_u3_review_c','unit_review','SC6-1-u3-C14',1,'mc','auto','초록잎반 탐구 일지 ⑤에서 잎몸에 퍼져 있다고 한 것은 어느 것인가요?',ARRAY['SC6-1-u3-X28']::text[],false,'{"seq":3,"concept":"SC6-1-u3-C14","difficulty":1,"kind":"mc","stem":"초록잎반 탐구 일지 ⑤에서 잎몸에 퍼져 있다고 한 것은 어느 것인가요?","options":[{"t":"잎맥","correct":true},{"t":"잎자루","mis":"SC6-1-u3-X28"},{"t":"꽃받침","mis":"SC6-1-u3-X28"},{"t":"세포벽","mis":"SC6-1-u3-X28"}],"explanation":["일지를 읽어요.","잎몸에 퍼져 있어요.","잎맥이에요."],"asset":{"type":"passage","lines":["봉선화 잎 하나에 알루미늄 포일을 씌우고 하루 동안 햇빛에 두었다.","두 잎의 초록색을 빼고 녹말을 만나면 색이 변하는 용액을 떨어뜨렸다.","포일을 씌우지 않은 잎만 청람색으로 변했다.","잎은 잎몸과 잎자루로 되어 있고 잎몸에는 잎맥이 퍼져 있었다."],"title":"⑤ 잎 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_c#4','sci',6,1,'u3','','g6_1_sci_u3_review_c','unit_review','SC6-1-u3-C27',1,'sa','auto','초록잎반 탐구 일지 ⑧의 놀이에서 물 말이 출발하는 기관의 이름을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC6-1-u3-C27","difficulty":1,"kind":"sa","stem":"초록잎반 탐구 일지 ⑧의 놀이에서 물 말이 출발하는 기관의 이름을 두 글자로 쓰세요.","answer":["뿌리"],"explanation":["물을 흡수하는 곳이에요.","두 글자예요.","뿌리예요."],"asset":{"type":"passage","lines":["짝과 물과 양분의 이동 놀이를 했다(물은 뿌리, 양분은 잎에서 출발).","우리 반 식물도감에 토끼풀·소나무·나팔꽃 소개 자료를 올렸다.","조사한 자료마다 출처를 적었다.","꽃가루로 옛날의 식물과 날씨를 알아낸다는 글을 읽었다."],"title":"⑧ 연결 놀이와 식물도감"},"mis":"SC6-1-u3-X49"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_c#5','sci',6,1,'u3','','g6_1_sci_u3_review_c','unit_review','SC6-1-u3-C19',1,'mc','auto','초록잎반 탐구 일지 ⑥에서 10분 뒤 붉게 변한 종이는 어느 것인가요?',ARRAY['SC6-1-u3-X39','SC6-1-u3-X37']::text[],false,'{"seq":5,"concept":"SC6-1-u3-C19","difficulty":1,"kind":"mc","stem":"초록잎반 탐구 일지 ⑥에서 10분 뒤 붉게 변한 종이는 어느 것인가요?","options":[{"t":"잎 뒷면에 붙인 종이","correct":true},{"t":"빈 페트리 접시에 붙인 종이","mis":"SC6-1-u3-X39"},{"t":"두 종이 모두","mis":"SC6-1-u3-X39"},{"t":"두 종이 모두 그대로","mis":"SC6-1-u3-X37"}],"explanation":["일지를 읽어요.","잎 뒷면의 종이예요.","그것만 붉어졌어요."],"asset":{"type":"passage","lines":["푸른색 염화 코발트 종이 한 장은 빈 페트리 접시에, 한 장은 잎 뒷면에 붙였다.","10분 뒤 잎 뒷면의 종이만 붉은색으로 변했다.","현미경으로 잎 표면을 보니 두 세포 사이에 아주 작은 구멍이 있었다.","식물원 온실에 들어가니 바깥보다 훨씬 습했다."],"title":"⑥ 증산 작용 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_c#6','sci',6,1,'u3','','g6_1_sci_u3_review_c','unit_review','SC6-1-u3-C16',1,'mc','auto','초록잎반 탐구 일지 ⑤에서 청람색으로 변한 잎은 어느 것인가요?',ARRAY['SC6-1-u3-X31']::text[],false,'{"seq":6,"concept":"SC6-1-u3-C16","difficulty":1,"kind":"mc","stem":"초록잎반 탐구 일지 ⑤에서 청람색으로 변한 잎은 어느 것인가요?","options":[{"t":"포일을 씌우지 않은 잎","correct":true},{"t":"포일을 씌운 잎","mis":"SC6-1-u3-X31"},{"t":"두 잎 모두","mis":"SC6-1-u3-X31"},{"t":"두 잎 모두 변하지 않음","mis":"SC6-1-u3-X31"}],"explanation":["일지를 읽어요.","햇빛을 받은 잎이에요.","포일을 씌우지 않은 잎이에요."],"asset":{"type":"passage","lines":["봉선화 잎 하나에 알루미늄 포일을 씌우고 하루 동안 햇빛에 두었다.","두 잎의 초록색을 빼고 녹말을 만나면 색이 변하는 용액을 떨어뜨렸다.","포일을 씌우지 않은 잎만 청람색으로 변했다.","잎은 잎몸과 잎자루로 되어 있고 잎몸에는 잎맥이 퍼져 있었다."],"title":"⑤ 잎 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_c#7','sci',6,1,'u3','','g6_1_sci_u3_review_c','unit_review','SC6-1-u3-C23',1,'sa','auto','「꽃은 ( )을/를 만듭니다.」 빈칸에 알맞은 말을 한 글자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"SC6-1-u3-C23","difficulty":1,"kind":"sa","stem":"「꽃은 ( )을/를 만듭니다.」 빈칸에 알맞은 말을 한 글자로 쓰세요.","answer":["씨"],"explanation":["꽃가루받이 뒤에 생겨요.","한 글자예요.","씨예요."],"mis":"SC6-1-u3-X45"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_c#8','sci',6,1,'u3','','g6_1_sci_u3_review_c','unit_review','SC6-1-u3-C28',1,'mc','auto','쓰고 남은 양분이 저장되는 곳으로 알맞지 않은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X50']::text[],false,'{"seq":8,"concept":"SC6-1-u3-C28","difficulty":1,"kind":"mc","stem":"쓰고 남은 양분이 저장되는 곳으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"기공","correct":true},{"t":"뿌리","mis":"SC6-1-u3-X50"},{"t":"줄기","mis":"SC6-1-u3-X50"},{"t":"열매","mis":"SC6-1-u3-X50"}],"explanation":["저장하는 곳이에요.","뿌리·줄기·열매예요.","기공은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_c#9','sci',6,1,'u3','','g6_1_sci_u3_review_c','unit_review','SC6-1-u3-C9',2,'mc','auto','초록잎반 탐구 일지 ③에서 두 파를 같은 양의 물에 넣고 같은 곳에 둔 까닭은 무엇인가요?',ARRAY['SC6-1-u3-X17','SC6-1-u3-X18','SC6-1-u3-X19']::text[],false,'{"seq":9,"concept":"SC6-1-u3-C9","difficulty":2,"kind":"mc","stem":"초록잎반 탐구 일지 ③에서 두 파를 같은 양의 물에 넣고 같은 곳에 둔 까닭은 무엇인가요?","options":[{"t":"뿌리가 있는지만 다르게 해서 그 차이를 알아보려고","correct":true},{"t":"물의 양이 다르면 결과가 더 뚜렷하기 때문에","mis":"SC6-1-u3-X17"},{"t":"예상한 대로 결과를 맞추려고","mis":"SC6-1-u3-X18"},{"t":"뿌리가 양분을 만드는지 보려고","mis":"SC6-1-u3-X19"}],"explanation":["조건을 같게 해요.","뿌리만 다르게요.","그래야 비교돼요."],"asset":{"type":"passage","lines":["파 ㉮는 뿌리를 자르고 파 ㉯는 뿌리를 그대로 두었다.","두 파를 같은 양의 물에 넣어 햇빛 드는 창가에 3일 두었다.","㉮ 쪽 물은 조금, ㉯ 쪽 물은 많이 줄었다.","짝꿍 화분의 강아지풀은 가는 뿌리가 수염처럼 나 있었다."],"title":"③ 뿌리 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_c#10','sci',6,1,'u3','','g6_1_sci_u3_review_c','unit_review','SC6-1-u3-C19',2,'mc','auto','초록잎반 탐구 일지 ⑥에서 빈 페트리 접시에도 종이를 붙인 까닭은 무엇인가요?',ARRAY['SC6-1-u3-X39','SC6-1-u3-X37','SC6-1-u3-X38']::text[],false,'{"seq":10,"concept":"SC6-1-u3-C19","difficulty":2,"kind":"mc","stem":"초록잎반 탐구 일지 ⑥에서 빈 페트리 접시에도 종이를 붙인 까닭은 무엇인가요?","options":[{"t":"잎에 붙인 종이와 견주어 잎에서 물이 나왔는지 알아보려고","correct":true},{"t":"페트리 접시에서도 증산 작용이 일어나기 때문에","mis":"SC6-1-u3-X39"},{"t":"공기 중의 수증기가 잎으로 들어가는지 보려고","mis":"SC6-1-u3-X37"},{"t":"줄기에서 증산 작용이 일어나는지 보려고","mis":"SC6-1-u3-X38"}],"explanation":["잎 없이 붙였어요.","견주기 위한 종이예요.","잎에서 물이 나왔어요."],"asset":{"type":"passage","lines":["푸른색 염화 코발트 종이 한 장은 빈 페트리 접시에, 한 장은 잎 뒷면에 붙였다.","10분 뒤 잎 뒷면의 종이만 붉은색으로 변했다.","현미경으로 잎 표면을 보니 두 세포 사이에 아주 작은 구멍이 있었다.","식물원 온실에 들어가니 바깥보다 훨씬 습했다."],"title":"⑥ 증산 작용 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_c#11','sci',6,1,'u3','','g6_1_sci_u3_review_c','unit_review','SC6-1-u3-C10',2,'mc','auto','초록잎반 탐구 일지 ③의 파를 화분에 옮겨 심었더니 바람에도 잘 쓰러지지 않았어요. 이와 관계있는 뿌리의 일은 어느 것인가요?',ARRAY['SC6-1-u3-X19','SC6-1-u3-X15','SC6-1-u3-X21']::text[],false,'{"seq":11,"concept":"SC6-1-u3-C10","difficulty":2,"kind":"mc","stem":"초록잎반 탐구 일지 ③의 파를 화분에 옮겨 심었더니 바람에도 잘 쓰러지지 않았어요. 이와 관계있는 뿌리의 일은 어느 것인가요?","options":[{"t":"식물을 지지하는 일","correct":true},{"t":"양분을 만드는 일","mis":"SC6-1-u3-X19"},{"t":"물을 내보내는 일","mis":"SC6-1-u3-X15"},{"t":"뿌리가 하는 일은 물 흡수뿐이다","mis":"SC6-1-u3-X21"}],"explanation":["쓰러지지 않아요.","뿌리가 붙잡아요.","지지해요."],"asset":{"type":"passage","lines":["파 ㉮는 뿌리를 자르고 파 ㉯는 뿌리를 그대로 두었다.","두 파를 같은 양의 물에 넣어 햇빛 드는 창가에 3일 두었다.","㉮ 쪽 물은 조금, ㉯ 쪽 물은 많이 줄었다.","짝꿍 화분의 강아지풀은 가는 뿌리가 수염처럼 나 있었다."],"title":"③ 뿌리 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_c#12','sci',6,1,'u3','','g6_1_sci_u3_review_c','unit_review','SC6-1-u3-C27',2,'mc','auto','뿌리에서 흡수한 물이 잎에 도달한 뒤의 일로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X49','SC6-1-u3-X50','SC6-1-u3-X48']::text[],false,'{"seq":12,"concept":"SC6-1-u3-C27","difficulty":2,"kind":"mc","stem":"뿌리에서 흡수한 물이 잎에 도달한 뒤의 일로 알맞은 것은 어느 것인가요?","options":[{"t":"일부는 기공을 통해 식물 밖으로 빠져나간다","correct":true},{"t":"모두 뿌리로 되돌아간다","mis":"SC6-1-u3-X49"},{"t":"모두 열매에 저장된다","mis":"SC6-1-u3-X50"},{"t":"잎에서 꽃가루로 바뀐다","mis":"SC6-1-u3-X48"}],"explanation":["잎까지 왔어요.","일부가 나가요.","기공으로 나가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_c#13','sci',6,1,'u3','','g6_1_sci_u3_review_c','unit_review','SC6-1-u3-C24',2,'mc','auto','초록잎반 탐구 일지 ⑦에서 복숭아 열매가 만들어진 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X44','SC6-1-u3-X46']::text[],false,'{"seq":13,"concept":"SC6-1-u3-C24","difficulty":2,"kind":"mc","stem":"초록잎반 탐구 일지 ⑦에서 복숭아 열매가 만들어진 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"꽃가루받이 → 암술 속에 씨가 생김 → 씨와 함께 둘레가 자라 열매가 됨","correct":true},{"t":"열매가 생김 → 꽃가루받이 → 씨가 생김","mis":"SC6-1-u3-X44"},{"t":"씨가 생김 → 열매가 씨를 만듦 → 꽃가루받이","mis":"SC6-1-u3-X46"},{"t":"꽃받침이 자라 열매 → 열매가 씨를 만듦 → 꽃가루받이","mis":"SC6-1-u3-X46"}],"explanation":["꽃가루받이가 먼저예요.","씨가 생겨요.","열매가 돼요."],"asset":{"type":"passage","lines":["제라늄꽃을 암술·수술·꽃잎·꽃받침으로 나누어 흰 종이에 놓았다.","꽃가루 앨러지가 있는 친구는 보안경과 마스크를 썼다.","벌이 꽃 사이를 날아다니며 꽃가루를 묻히는 영상을 보았다.","복숭아 열매를 잘라 속에 든 씨를 찾아보았다."],"title":"⑦ 꽃 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_c#14','sci',6,1,'u3','','g6_1_sci_u3_review_c','unit_review','SC6-1-u3-C17',2,'mc','auto','잎이 납작하고 넓으면 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X22','SC6-1-u3-X36']::text[],false,'{"seq":14,"concept":"SC6-1-u3-C17","difficulty":2,"kind":"mc","stem":"잎이 납작하고 넓으면 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"빛을 넓게 받아 광합성이 잘 일어난다","correct":true},{"t":"땅속의 물을 더 잘 흡수한다","mis":"SC6-1-u3-X22"},{"t":"잎 모양은 하는 일과 상관없다","mis":"SC6-1-u3-X36"},{"t":"씨를 더 멀리 퍼뜨린다","mis":"SC6-1-u3-X36"}],"explanation":["잎은 빛을 받아요.","넓으면 많이 받아요.","광합성이 잘 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_c#15','sci',6,1,'u3','','g6_1_sci_u3_review_c','unit_review','SC6-1-u3-C26',2,'mc','auto','잎이 하는 일을 모두 바르게 말한 것은 어느 것인가요?',ARRAY['SC6-1-u3-X48','SC6-1-u3-X45']::text[],false,'{"seq":15,"concept":"SC6-1-u3-C26","difficulty":2,"kind":"mc","stem":"잎이 하는 일을 모두 바르게 말한 것은 어느 것인가요?","options":[{"t":"광합성으로 양분을 만들고, 증산 작용으로 물을 식물 밖으로 내보낸다","correct":true},{"t":"물을 흡수하고 씨를 만든다","mis":"SC6-1-u3-X48"},{"t":"식물을 지지하고 양분을 저장한다","mis":"SC6-1-u3-X48"},{"t":"꽃가루받이를 하고 씨를 퍼뜨린다","mis":"SC6-1-u3-X45"}],"explanation":["잎을 떠올려요.","양분을 만들어요.","물을 내보내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_c#16','sci',6,1,'u3','','g6_1_sci_u3_review_c','unit_review','SC6-1-u3-C28',2,'mc','auto','잎에서 만든 양분에 관한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X35','SC6-1-u3-X50','SC6-1-u3-X49']::text[],false,'{"seq":16,"concept":"SC6-1-u3-C28","difficulty":2,"kind":"mc","stem":"잎에서 만든 양분에 관한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"줄기를 통해 식물 전체로 가서 쓰이고 남은 것은 저장된다","correct":true},{"t":"잎에서만 쓰인다","mis":"SC6-1-u3-X35"},{"t":"남으면 모두 버려진다","mis":"SC6-1-u3-X50"},{"t":"뿌리에서 만들어져 잎으로 온다","mis":"SC6-1-u3-X49"}],"explanation":["양분이 움직여요.","줄기를 통해 가요.","남으면 저장해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_c#17','sci',6,1,'u3','','g6_1_sci_u3_review_c','unit_review','SC6-1-u3-C9',3,'error','auto','초록잎반 탐구 일지 ③을 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u3-X16','SC6-1-u3-X17']::text[],false,'{"seq":17,"concept":"SC6-1-u3-C9","difficulty":3,"kind":"error","stem":"초록잎반 탐구 일지 ③을 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지원 — 「뿌리를 자른 ㉮ 쪽 물이 더 많이 줄었으니 자른 쪽이 물을 더 먹은 거야.」","correct":true,"mis_target":"SC6-1-u3-X16"},{"t":"가람 — 「㉯ 쪽이 많이 줄었으니 뿌리가 물을 흡수한 거야.」","mis":"SC6-1-u3-X16"},{"t":"수빈 — 「물의 양과 놓아둔 곳은 같게 했어.」","mis":"SC6-1-u3-X17"}],"explanation":["일지를 다시 봐요.","㉯ 쪽이 많이 줄었어요.","지원의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["파 ㉮는 뿌리를 자르고 파 ㉯는 뿌리를 그대로 두었다.","두 파를 같은 양의 물에 넣어 햇빛 드는 창가에 3일 두었다.","㉮ 쪽 물은 조금, ㉯ 쪽 물은 많이 줄었다.","짝꿍 화분의 강아지풀은 가는 뿌리가 수염처럼 나 있었다."],"title":"③ 뿌리 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_c#18','sci',6,1,'u3','','g6_1_sci_u3_review_c','unit_review','SC6-1-u3-C22',3,'error','auto','초록잎반 탐구 일지 ⑦을 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u3-X42','SC6-1-u3-X43','SC6-1-u3-X44']::text[],false,'{"seq":18,"concept":"SC6-1-u3-C22","difficulty":3,"kind":"error","stem":"초록잎반 탐구 일지 ⑦을 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서진 — 「모든 꽃은 제라늄처럼 네 부분이 꼭 다 있어.」","correct":true,"mis_target":"SC6-1-u3-X42"},{"t":"채아 — 「암술 둘레를 수술이 둘러싸고 있었어.」","mis":"SC6-1-u3-X43"},{"t":"윤호 — 「벌이 꽃가루받이를 도와.」","mis":"SC6-1-u3-X44"}],"explanation":["꽃은 다양해요.","일부가 없는 꽃도 있어요.","서진의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["제라늄꽃을 암술·수술·꽃잎·꽃받침으로 나누어 흰 종이에 놓았다.","꽃가루 앨러지가 있는 친구는 보안경과 마스크를 썼다.","벌이 꽃 사이를 날아다니며 꽃가루를 묻히는 영상을 보았다.","복숭아 열매를 잘라 속에 든 씨를 찾아보았다."],"title":"⑦ 꽃 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_c#19','sci',6,1,'u3','','g6_1_sci_u3_review_c','unit_review','SC6-1-u3-C11',3,'mc','auto','초록잎반 탐구 일지 ④에서 가로 단면의 붉은 점과 세로 단면의 붉은 선은 같은 것을 다르게 본 거예요. 무엇인가요?',ARRAY['SC6-1-u3-X23','SC6-1-u3-X22','SC6-1-u3-X24']::text[],false,'{"seq":19,"concept":"SC6-1-u3-C11","difficulty":3,"kind":"mc","stem":"초록잎반 탐구 일지 ④에서 가로 단면의 붉은 점과 세로 단면의 붉은 선은 같은 것을 다르게 본 거예요. 무엇인가요?","options":[{"t":"물이 이동하는 통로","correct":true},{"t":"양분이 저장된 주머니","mis":"SC6-1-u3-X23"},{"t":"줄기가 물을 흡수하는 구멍","mis":"SC6-1-u3-X22"},{"t":"색소가 멈춰 있는 곳","mis":"SC6-1-u3-X24"}],"explanation":["자른 방향만 달라요.","같은 길이에요.","물이 이동하는 통로예요."],"asset":{"type":"passage","lines":["붉은색 색소를 녹인 물에 백합을 하루 동안 두었다.","흰 꽃잎과 초록 잎이 붉은빛을 띠었다.","줄기 가로 단면에는 붉은 점이, 세로 단면에는 붉은 선이 보였다.","급식에 나온 감자는 땅속 줄기라고 선생님께서 말씀하셨다."],"title":"④ 줄기 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_c#20','sci',6,1,'u3','','g6_1_sci_u3_review_c','unit_review','SC6-1-u3-C18',3,'mc','auto','뿌리에서 흡수한 물이 수증기가 되어 나가기까지의 길로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X37','SC6-1-u3-X38','SC6-1-u3-X49']::text[],false,'{"seq":20,"concept":"SC6-1-u3-C18","difficulty":3,"kind":"mc","stem":"뿌리에서 흡수한 물이 수증기가 되어 나가기까지의 길로 알맞은 것은 어느 것인가요?","options":[{"t":"뿌리 → 줄기 → 잎 → 기공","correct":true},{"t":"기공 → 잎 → 줄기 → 뿌리","mis":"SC6-1-u3-X37"},{"t":"뿌리 → 기공 → 줄기 → 잎","mis":"SC6-1-u3-X38"},{"t":"잎 → 뿌리 → 줄기 → 기공","mis":"SC6-1-u3-X49"}],"explanation":["물은 뿌리에서 출발해요.","줄기를 지나 잎에 가요.","기공으로 나가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_c#21','sci',6,1,'u3','','g6_1_sci_u3_review_c','unit_review','SC6-1-u3-C23',3,'mc','auto','꽃잎이 화려한 꽃이 꽃가루받이에 유리한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X45','SC6-1-u3-X44','SC6-1-u3-X46']::text[],false,'{"seq":21,"concept":"SC6-1-u3-C23","difficulty":3,"kind":"mc","stem":"꽃잎이 화려한 꽃이 꽃가루받이에 유리한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"벌이나 나비를 끌어들이기 좋기 때문이다","correct":true},{"t":"화려한 꽃이 양분을 더 많이 만들기 때문이다","mis":"SC6-1-u3-X45"},{"t":"화려한 꽃은 암술에서 수술로 꽃가루를 옮기기 때문이다","mis":"SC6-1-u3-X44"},{"t":"화려한 꽃은 열매가 씨를 만들기 때문이다","mis":"SC6-1-u3-X46"}],"explanation":["누가 꽃을 찾나요?","벌과 나비예요.","꽃가루받이가 잘 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_c#22','sci',6,1,'u3','','g6_1_sci_u3_review_c','unit_review','SC6-1-u3-C2',3,'mc','auto','초록잎반 탐구 일지 ①의 해바라기 사진으로 뿌리에 관한 다섯 고개 질문을 만들기 어려운 까닭은 무엇인가요?',ARRAY['SC6-1-u3-X03','SC6-1-u3-X14','SC6-1-u3-X01']::text[],false,'{"seq":22,"concept":"SC6-1-u3-C2","difficulty":3,"kind":"mc","stem":"초록잎반 탐구 일지 ①의 해바라기 사진으로 뿌리에 관한 다섯 고개 질문을 만들기 어려운 까닭은 무엇인가요?","options":[{"t":"뿌리는 땅속에 있어 사진에 보이지 않기 때문이다","correct":true},{"t":"해바라기는 뿌리가 없는 식물이기 때문이다","mis":"SC6-1-u3-X03"},{"t":"뿌리는 모든 식물이 똑같이 생겼기 때문이다","mis":"SC6-1-u3-X14"},{"t":"뿌리를 묻는 것은 구조에 관한 질문이 아니기 때문이다","mis":"SC6-1-u3-X01"}],"explanation":["뿌리는 어디 있나요?","땅속이라 안 보여요.","사진으로 묻기 어려워요."],"asset":{"type":"passage","lines":["우리 모둠은 화단의 해바라기를 다섯 고개 문제로 냈다.","사진은 꽃잎 부분만 잘라서 보여 주었다.","다른 모둠은 「나보다 키가 큰가요?」, 「꽃은 무슨 색인가요?」 등을 물었다.","앱으로 알아낸 이름은 식물도감으로 다시 확인했다."],"title":"① 다섯 고개 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_c#23','sci',6,1,'u3','','g6_1_sci_u3_review_c','unit_review','SC6-1-u3-C24',4,'essay','teacher','초록잎반 탐구 일지 ⑦을 바탕으로, 복숭아꽃이 피고 나서 열매 속에 씨가 들기까지 일어나는 일을 차례대로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SC6-1-u3-C24","difficulty":4,"kind":"essay","stem":"초록잎반 탐구 일지 ⑦을 바탕으로, 복숭아꽃이 피고 나서 열매 속에 씨가 들기까지 일어나는 일을 차례대로 쓰세요.","answer_guide":{"answer":"예: 벌 같은 곤충이 수술의 꽃가루를 암술에 옮겨 꽃가루받이가 이루어진다. 그러면 암술 속에 씨가 생기고, 씨가 자라면서 씨를 둘러싼 부분도 함께 자라 열매가 된다.","scoring_points":["꽃가루받이를 썼는가","암술 속에 씨가 생긴다고 썼는가","씨와 함께 둘레가 자라 열매가 된다고 썼는가"]},"explanation":["꽃가루받이가 먼저예요.","씨가 생겨요.","열매가 돼요."],"asset":{"type":"passage","lines":["제라늄꽃을 암술·수술·꽃잎·꽃받침으로 나누어 흰 종이에 놓았다.","꽃가루 앨러지가 있는 친구는 보안경과 마스크를 썼다.","벌이 꽃 사이를 날아다니며 꽃가루를 묻히는 영상을 보았다.","복숭아 열매를 잘라 속에 든 씨를 찾아보았다."],"title":"⑦ 꽃 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_c#24','sci',6,1,'u3','','g6_1_sci_u3_review_c','unit_review','SC6-1-u3-C13',4,'mc','auto','나팔꽃, 딸기, 감자, 봉선화의 줄기를 바르게 정리한 것은 어느 것인가요?',ARRAY['SC6-1-u3-X26','SC6-1-u3-X25']::text[],false,'{"seq":24,"concept":"SC6-1-u3-C13","difficulty":4,"kind":"mc","stem":"나팔꽃, 딸기, 감자, 봉선화의 줄기를 바르게 정리한 것은 어느 것인가요?","options":[{"t":"나팔꽃은 감고 올라가고, 딸기는 땅 위를 기며, 감자는 양분을 저장하고, 봉선화는 곧게 선다","correct":true},{"t":"네 식물의 줄기는 모두 곧게 선다","mis":"SC6-1-u3-X26"},{"t":"감자와 딸기는 뿌리이고 나머지는 줄기다","mis":"SC6-1-u3-X25"},{"t":"나팔꽃은 땅 위를 기고 딸기는 감고 올라간다","mis":"SC6-1-u3-X26"}],"explanation":["식물마다 떠올려요.","줄기 모양이 달라요.","알맞게 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_c#25','sci',6,1,'u3','','g6_1_sci_u3_review_c','unit_review','SC6-1-u3-C31',4,'essay','teacher','우리 반 식물도감에 올릴 식물 소개 자료를 만든다고 할 때, 넣을 내용 두 가지와 조사하면서 지킬 점 한 가지를 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC6-1-u3-C31","difficulty":4,"kind":"essay","stem":"우리 반 식물도감에 올릴 식물 소개 자료를 만든다고 할 때, 넣을 내용 두 가지와 조사하면서 지킬 점 한 가지를 쓰세요.","answer_guide":{"answer":"예: 식물의 사진이나 그림, 뿌리·줄기·잎·꽃의 구조와 기능을 넣는다. 조사한 자료가 올바른 정보인지 확인하고 출처를 밝힌다.","scoring_points":["구조와 기능을 넣는다고 썼는가","사진·그림 등 다른 내용을 하나 더 썼는가","확인·출처 등 지킬 점을 썼는가"]},"explanation":["도감 내용을 떠올려요.","구조와 기능이에요.","출처를 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_d#1','sci',6,1,'u3','','g6_1_sci_u3_review_d','unit_review','SC6-1-u3-C11',1,'ox','auto','초록잎반 탐구 일지 ④에서 줄기 단면에 붉게 물든 부분은 물이 이동한 통로예요.',ARRAY['SC6-1-u3-X23']::text[],false,'{"seq":1,"concept":"SC6-1-u3-C11","difficulty":1,"kind":"ox","stem":"초록잎반 탐구 일지 ④에서 줄기 단면에 붉게 물든 부분은 물이 이동한 통로예요.","answer":"O","reason_options":[{"t":"색소 물이 그 길을 따라 잎과 꽃까지 올라갔기 때문에","correct":true},{"t":"붉은 부분은 양분을 모아 둔 곳이기 때문에","mis":"SC6-1-u3-X23"}],"mis":"SC6-1-u3-X23","explanation":["붉은 물이 지나갔어요.","그 길이 물들었어요.","물이 이동한 통로예요."],"asset":{"type":"passage","lines":["붉은색 색소를 녹인 물에 백합을 하루 동안 두었다.","흰 꽃잎과 초록 잎이 붉은빛을 띠었다.","줄기 가로 단면에는 붉은 점이, 세로 단면에는 붉은 선이 보였다.","급식에 나온 감자는 땅속 줄기라고 선생님께서 말씀하셨다."],"title":"④ 줄기 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_d#2','sci',6,1,'u3','','g6_1_sci_u3_review_d','unit_review','SC6-1-u3-C23',1,'mc','auto','초록잎반 탐구 일지 ⑦의 영상에서 벌이 하는 일과 관계있는 것은 어느 것인가요?',ARRAY['SC6-1-u3-X45']::text[],false,'{"seq":2,"concept":"SC6-1-u3-C23","difficulty":1,"kind":"mc","stem":"초록잎반 탐구 일지 ⑦의 영상에서 벌이 하는 일과 관계있는 것은 어느 것인가요?","options":[{"t":"꽃가루받이","correct":true},{"t":"광합성","mis":"SC6-1-u3-X45"},{"t":"증산 작용","mis":"SC6-1-u3-X45"},{"t":"물 흡수","mis":"SC6-1-u3-X45"}],"explanation":["벌이 꽃가루를 묻혀요.","다른 꽃으로 옮겨요.","꽃가루받이를 도와요."],"asset":{"type":"passage","lines":["제라늄꽃을 암술·수술·꽃잎·꽃받침으로 나누어 흰 종이에 놓았다.","꽃가루 앨러지가 있는 친구는 보안경과 마스크를 썼다.","벌이 꽃 사이를 날아다니며 꽃가루를 묻히는 영상을 보았다.","복숭아 열매를 잘라 속에 든 씨를 찾아보았다."],"title":"⑦ 꽃 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_d#3','sci',6,1,'u3','','g6_1_sci_u3_review_d','unit_review','SC6-1-u3-C24',1,'mc','auto','초록잎반 탐구 일지 ⑦에서 복숭아 열매 속의 씨를 지키는 것은 어느 것인가요?',ARRAY['SC6-1-u3-X46']::text[],false,'{"seq":3,"concept":"SC6-1-u3-C24","difficulty":1,"kind":"mc","stem":"초록잎반 탐구 일지 ⑦에서 복숭아 열매 속의 씨를 지키는 것은 어느 것인가요?","options":[{"t":"열매","correct":true},{"t":"꽃잎","mis":"SC6-1-u3-X46"},{"t":"뿌리","mis":"SC6-1-u3-X46"},{"t":"수술","mis":"SC6-1-u3-X46"}],"explanation":["씨를 둘러싸요.","열매예요.","열매는 씨를 보호해요."],"asset":{"type":"passage","lines":["제라늄꽃을 암술·수술·꽃잎·꽃받침으로 나누어 흰 종이에 놓았다.","꽃가루 앨러지가 있는 친구는 보안경과 마스크를 썼다.","벌이 꽃 사이를 날아다니며 꽃가루를 묻히는 영상을 보았다.","복숭아 열매를 잘라 속에 든 씨를 찾아보았다."],"title":"⑦ 꽃 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_d#4','sci',6,1,'u3','','g6_1_sci_u3_review_d','unit_review','SC6-1-u3-C31',1,'ox','auto','초록잎반 탐구 일지 ⑧에서 조사한 자료마다 출처를 적은 것은 알맞은 행동이에요.',ARRAY['SC6-1-u3-X53']::text[],false,'{"seq":4,"concept":"SC6-1-u3-C31","difficulty":1,"kind":"ox","stem":"초록잎반 탐구 일지 ⑧에서 조사한 자료마다 출처를 적은 것은 알맞은 행동이에요.","answer":"O","reason_options":[{"t":"자료를 만든 사람을 밝히고 정보를 확인할 수 있게 해 주기 때문에","correct":true},{"t":"출처를 적어야 자료가 길어 보이기 때문에","mis":"SC6-1-u3-X53"}],"mis":"SC6-1-u3-X53","explanation":["조사한 자료예요.","출처를 밝혀요.","알맞은 행동이에요."],"asset":{"type":"passage","lines":["짝과 물과 양분의 이동 놀이를 했다(물은 뿌리, 양분은 잎에서 출발).","우리 반 식물도감에 토끼풀·소나무·나팔꽃 소개 자료를 올렸다.","조사한 자료마다 출처를 적었다.","꽃가루로 옛날의 식물과 날씨를 알아낸다는 글을 읽었다."],"title":"⑧ 연결 놀이와 식물도감"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_d#5','sci',6,1,'u3','','g6_1_sci_u3_review_d','unit_review','SC6-1-u3-C26',1,'mc','auto','식물에서 물과 양분이 이동하는 통로 역할을 하는 기관은 어느 것인가요?',ARRAY['SC6-1-u3-X48']::text[],false,'{"seq":5,"concept":"SC6-1-u3-C26","difficulty":1,"kind":"mc","stem":"식물에서 물과 양분이 이동하는 통로 역할을 하는 기관은 어느 것인가요?","options":[{"t":"줄기","correct":true},{"t":"꽃","mis":"SC6-1-u3-X48"},{"t":"열매","mis":"SC6-1-u3-X48"},{"t":"꽃받침","mis":"SC6-1-u3-X48"}],"explanation":["물과 양분이 지나가요.","뿌리와 잎 사이예요.","줄기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_d#6','sci',6,1,'u3','','g6_1_sci_u3_review_d','unit_review','SC6-1-u3-C22',1,'mc','auto','초록잎반 탐구 일지 ⑦에서 제라늄꽃을 나눈 네 부분이 아닌 것은 어느 것인가요?',ARRAY['SC6-1-u3-X42','SC6-1-u3-X43']::text[],false,'{"seq":6,"concept":"SC6-1-u3-C22","difficulty":1,"kind":"mc","stem":"초록잎반 탐구 일지 ⑦에서 제라늄꽃을 나눈 네 부분이 아닌 것은 어느 것인가요?","options":[{"t":"뿌리털","correct":true},{"t":"암술","mis":"SC6-1-u3-X42"},{"t":"꽃받침","mis":"SC6-1-u3-X43"},{"t":"수술","mis":"SC6-1-u3-X43"}],"explanation":["일지를 읽어요.","꽃의 네 부분이에요.","뿌리털은 아니에요."],"asset":{"type":"passage","lines":["제라늄꽃을 암술·수술·꽃잎·꽃받침으로 나누어 흰 종이에 놓았다.","꽃가루 앨러지가 있는 친구는 보안경과 마스크를 썼다.","벌이 꽃 사이를 날아다니며 꽃가루를 묻히는 영상을 보았다.","복숭아 열매를 잘라 속에 든 씨를 찾아보았다."],"title":"⑦ 꽃 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_d#7','sci',6,1,'u3','','g6_1_sci_u3_review_d','unit_review','SC6-1-u3-C7',1,'mc','auto','초록잎반 탐구 일지 ②에서 매니큐어를 얇게 바른 까닭은 무엇인가요?',ARRAY['SC6-1-u3-X12','SC6-1-u3-X13','SC6-1-u3-X08']::text[],false,'{"seq":7,"concept":"SC6-1-u3-C7","difficulty":1,"kind":"mc","stem":"초록잎반 탐구 일지 ②에서 매니큐어를 얇게 바른 까닭은 무엇인가요?","options":[{"t":"빛이 통과해야 세포가 잘 보이기 때문이다","correct":true},{"t":"두껍게 바를수록 잘 보이기 때문이다","mis":"SC6-1-u3-X12"},{"t":"냄새를 맡기 좋게 하려고","mis":"SC6-1-u3-X13"},{"t":"세포벽을 새로 만들려고","mis":"SC6-1-u3-X08"}],"explanation":["빛이 통과해야 해요.","얇게 발라요.","잘 보여요."],"asset":{"type":"passage","lines":["사철나무잎 뒷면에 투명 매니큐어를 얇게 발라 표본을 만들었다.","각진 세포들이 붙어 있고 세포의 경계가 뚜렷했다.","양파 표피세포는 세포마다 둥근 핵이 하나씩 보였다.","쉬는 시간에 달걀 하나도 하나의 세포라는 이야기를 들었다."],"title":"② 현미경으로 세포 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_d#8','sci',6,1,'u3','','g6_1_sci_u3_review_d','unit_review','SC6-1-u3-C29',1,'ox','auto','식물의 한 기관에 문제가 생기면 식물 전체에 영향을 줄 수 있어요.',ARRAY['SC6-1-u3-X48']::text[],false,'{"seq":8,"concept":"SC6-1-u3-C29","difficulty":1,"kind":"ox","stem":"식물의 한 기관에 문제가 생기면 식물 전체에 영향을 줄 수 있어요.","answer":"O","reason_options":[{"t":"기관들이 서로 연결되어 영향을 주고받기 때문에","correct":true},{"t":"기관들은 따로따로 일하기 때문에","mis":"SC6-1-u3-X48"}],"mis":"SC6-1-u3-X48","explanation":["톱니바퀴를 떠올려요.","연결되어 있어요.","전체에 영향을 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_d#9','sci',6,1,'u3','','g6_1_sci_u3_review_d','unit_review','SC6-1-u3-C11',2,'mc','auto','초록잎반 탐구 일지 ④에서 꽃과 잎까지 붉은빛을 띤 것으로 알 수 있는 것은 어느 것인가요?',ARRAY['SC6-1-u3-X24','SC6-1-u3-X22','SC6-1-u3-X27']::text[],false,'{"seq":9,"concept":"SC6-1-u3-C11","difficulty":2,"kind":"mc","stem":"초록잎반 탐구 일지 ④에서 꽃과 잎까지 붉은빛을 띤 것으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"줄기를 통해 이동한 물이 잎과 꽃까지 간다","correct":true},{"t":"색소 물은 줄기에서 멈춘다","mis":"SC6-1-u3-X24"},{"t":"꽃과 잎이 공기에서 색소를 흡수했다","mis":"SC6-1-u3-X22"},{"t":"줄기가 붉은 양분을 만들었다","mis":"SC6-1-u3-X27"}],"explanation":["색소 물이 올라갔어요.","잎과 꽃까지 갔어요.","줄기가 물을 옮겨요."],"asset":{"type":"passage","lines":["붉은색 색소를 녹인 물에 백합을 하루 동안 두었다.","흰 꽃잎과 초록 잎이 붉은빛을 띠었다.","줄기 가로 단면에는 붉은 점이, 세로 단면에는 붉은 선이 보였다.","급식에 나온 감자는 땅속 줄기라고 선생님께서 말씀하셨다."],"title":"④ 줄기 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_d#10','sci',6,1,'u3','','g6_1_sci_u3_review_d','unit_review','SC6-1-u3-C22',2,'mc','auto','초록잎반 탐구 일지 ⑦에서 제라늄꽃의 네 부분 가운데 가장 가운데에 있는 것은 어느 것인가요?',ARRAY['SC6-1-u3-X43','SC6-1-u3-X42']::text[],false,'{"seq":10,"concept":"SC6-1-u3-C22","difficulty":2,"kind":"mc","stem":"초록잎반 탐구 일지 ⑦에서 제라늄꽃의 네 부분 가운데 가장 가운데에 있는 것은 어느 것인가요?","options":[{"t":"암술","correct":true},{"t":"꽃받침","mis":"SC6-1-u3-X43"},{"t":"꽃잎","mis":"SC6-1-u3-X43"},{"t":"네 부분은 자리가 정해져 있지 않다","mis":"SC6-1-u3-X42"}],"explanation":["꽃의 가운데예요.","수술이 둘러싸요.","암술이에요."],"asset":{"type":"passage","lines":["제라늄꽃을 암술·수술·꽃잎·꽃받침으로 나누어 흰 종이에 놓았다.","꽃가루 앨러지가 있는 친구는 보안경과 마스크를 썼다.","벌이 꽃 사이를 날아다니며 꽃가루를 묻히는 영상을 보았다.","복숭아 열매를 잘라 속에 든 씨를 찾아보았다."],"title":"⑦ 꽃 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_d#11','sci',6,1,'u3','','g6_1_sci_u3_review_d','unit_review','SC6-1-u3-C15',2,'mc','auto','초록잎반 탐구 일지 ⑤의 봉선화 줄기 가운데 초록색인 부분에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['SC6-1-u3-X29','SC6-1-u3-X30','SC6-1-u3-X34']::text[],false,'{"seq":11,"concept":"SC6-1-u3-C15","difficulty":2,"kind":"mc","stem":"초록잎반 탐구 일지 ⑤의 봉선화 줄기 가운데 초록색인 부분에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"광합성은 주로 잎에서 일어나지만 초록색인 다른 부분에서도 일어날 수 있다","correct":true},{"t":"광합성은 잎에서만 일어나므로 줄기와는 상관없다","mis":"SC6-1-u3-X29"},{"t":"초록색 줄기는 빛 없이 양분을 만든다","mis":"SC6-1-u3-X30"},{"t":"봉선화는 햇빛을 많이 받을수록 무조건 좋다","mis":"SC6-1-u3-X34"}],"explanation":["초록색 부분이에요.","주로 잎에서 일어나요.","잎에서만은 아니에요."],"asset":{"type":"passage","lines":["봉선화 잎 하나에 알루미늄 포일을 씌우고 하루 동안 햇빛에 두었다.","두 잎의 초록색을 빼고 녹말을 만나면 색이 변하는 용액을 떨어뜨렸다.","포일을 씌우지 않은 잎만 청람색으로 변했다.","잎은 잎몸과 잎자루로 되어 있고 잎몸에는 잎맥이 퍼져 있었다."],"title":"⑤ 잎 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_d#12','sci',6,1,'u3','','g6_1_sci_u3_review_d','unit_review','SC6-1-u3-C30',2,'mc','auto','초록잎반 탐구 일지 ⑧의 나팔꽃 소개 자료에 넣기에 가장 알맞은 내용은 어느 것인가요?',ARRAY['SC6-1-u3-X52']::text[],false,'{"seq":12,"concept":"SC6-1-u3-C30","difficulty":2,"kind":"mc","stem":"초록잎반 탐구 일지 ⑧의 나팔꽃 소개 자료에 넣기에 가장 알맞은 내용은 어느 것인가요?","options":[{"t":"줄기가 다른 식물이나 물체를 감고 올라간다","correct":true},{"t":"나팔꽃을 파는 가게 이름","mis":"SC6-1-u3-X52"},{"t":"나팔꽃을 좋아하는 친구 이름","mis":"SC6-1-u3-X52"},{"t":"나팔꽃 사진 한 장만","mis":"SC6-1-u3-X52"}],"explanation":["도감에 넣을 내용이에요.","구조와 기능이에요.","감고 올라가는 줄기예요."],"asset":{"type":"passage","lines":["짝과 물과 양분의 이동 놀이를 했다(물은 뿌리, 양분은 잎에서 출발).","우리 반 식물도감에 토끼풀·소나무·나팔꽃 소개 자료를 올렸다.","조사한 자료마다 출처를 적었다.","꽃가루로 옛날의 식물과 날씨를 알아낸다는 글을 읽었다."],"title":"⑧ 연결 놀이와 식물도감"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_d#13','sci',6,1,'u3','','g6_1_sci_u3_review_d','unit_review','SC6-1-u3-C25',2,'ox','auto','꽃을 관찰할 때는 꽃잎을 맛보아 맛을 기록해요.',ARRAY['SC6-1-u3-X47']::text[],false,'{"seq":13,"concept":"SC6-1-u3-C25","difficulty":2,"kind":"ox","stem":"꽃을 관찰할 때는 꽃잎을 맛보아 맛을 기록해요.","answer":"X","reason_options":[{"t":"관찰하는 꽃을 맛보는 것은 위험할 수 있어 하지 않기 때문에","correct":true},{"t":"맛을 보아야 꽃가루받이를 알 수 있기 때문에","mis":"SC6-1-u3-X47"}],"mis":"SC6-1-u3-X47","explanation":["꽃 관찰 안전이에요.","맛보지 않아요.","틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_d#14','sci',6,1,'u3','','g6_1_sci_u3_review_d','unit_review','SC6-1-u3-C31',2,'mc','auto','스마트 기기로 식물을 조사할 때 알맞지 않은 행동은 어느 것인가요?',ARRAY['SC6-1-u3-X53']::text[],false,'{"seq":14,"concept":"SC6-1-u3-C31","difficulty":2,"kind":"mc","stem":"스마트 기기로 식물을 조사할 때 알맞지 않은 행동은 어느 것인가요?","options":[{"t":"수업과 상관없는 누리집에 들어가 본다","correct":true},{"t":"올바른 정보인지 확인한다","mis":"SC6-1-u3-X53"},{"t":"출처를 적는다","mis":"SC6-1-u3-X53"},{"t":"기기에서 열이 나면 바로 멈춘다","mis":"SC6-1-u3-X53"}],"explanation":["조사 태도예요.","수업 자료만 찾아요.","상관없는 곳은 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_d#15','sci',6,1,'u3','','g6_1_sci_u3_review_d','unit_review','SC6-1-u3-C33',2,'mc','auto','해바라기와 소나무를 견주어 바르게 말한 것은 어느 것인가요?',ARRAY['SC6-1-u3-X56','SC6-1-u3-X03','SC6-1-u3-X06']::text[],false,'{"seq":15,"concept":"SC6-1-u3-C33","difficulty":2,"kind":"mc","stem":"해바라기와 소나무를 견주어 바르게 말한 것은 어느 것인가요?","options":[{"t":"생김새는 달라도 둘 다 뿌리·줄기·잎 등의 기관으로 이루어져 있다","correct":true},{"t":"생김새가 다르니 기관도 전혀 다르다","mis":"SC6-1-u3-X56"},{"t":"두 식물은 생김새가 똑같다","mis":"SC6-1-u3-X03"},{"t":"소나무는 세포로 이루어져 있지 않다","mis":"SC6-1-u3-X06"}],"explanation":["생김새는 달라요.","기관을 떠올려요.","기관은 비슷해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_d#16','sci',6,1,'u3','','g6_1_sci_u3_review_d','unit_review','SC6-1-u3-C9',2,'ox','auto','실험 결과가 예상과 달라도 있는 그대로 기록해요.',ARRAY['SC6-1-u3-X18']::text[],false,'{"seq":16,"concept":"SC6-1-u3-C9","difficulty":2,"kind":"ox","stem":"실험 결과가 예상과 달라도 있는 그대로 기록해요.","answer":"O","reason_options":[{"t":"결과를 바꾸면 실험으로 알아낸 사실을 믿을 수 없기 때문에","correct":true},{"t":"예상과 같게 고쳐 적어야 좋은 실험이기 때문에","mis":"SC6-1-u3-X18"}],"mis":"SC6-1-u3-X18","explanation":["결과를 기록해요.","있는 그대로 적어요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_d#17','sci',6,1,'u3','','g6_1_sci_u3_review_d','unit_review','SC6-1-u3-C12',3,'error','auto','초록잎반 탐구 일지 ④를 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u3-X22','SC6-1-u3-X23','SC6-1-u3-X25']::text[],false,'{"seq":17,"concept":"SC6-1-u3-C12","difficulty":3,"kind":"error","stem":"초록잎반 탐구 일지 ④를 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태윤 — 「줄기가 물을 흡수해서 꽃과 잎으로 보낸 거야.」","correct":true,"mis_target":"SC6-1-u3-X22"},{"t":"나경 — 「줄기 속 통로를 따라 물이 이동했어.」","mis":"SC6-1-u3-X23"},{"t":"민찬 — 「감자는 줄기에 양분을 저장한 거래.」","mis":"SC6-1-u3-X25"}],"explanation":["흡수는 어디서 하나요?","뿌리가 해요.","태윤의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["붉은색 색소를 녹인 물에 백합을 하루 동안 두었다.","흰 꽃잎과 초록 잎이 붉은빛을 띠었다.","줄기 가로 단면에는 붉은 점이, 세로 단면에는 붉은 선이 보였다.","급식에 나온 감자는 땅속 줄기라고 선생님께서 말씀하셨다."],"title":"④ 줄기 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_d#18','sci',6,1,'u3','','g6_1_sci_u3_review_d','unit_review','SC6-1-u3-C28',3,'error','auto','초록잎반 탐구 일지 ⑧의 놀이를 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u3-X49','SC6-1-u3-X50']::text[],false,'{"seq":18,"concept":"SC6-1-u3-C28","difficulty":3,"kind":"error","stem":"초록잎반 탐구 일지 ⑧의 놀이를 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하윤 — 「양분 말은 뿌리에서 출발해서 잎에 도착해.」","correct":true,"mis_target":"SC6-1-u3-X49"},{"t":"주안 — 「물 말은 뿌리에서 줄기를 지나 잎으로 가.」","mis":"SC6-1-u3-X49"},{"t":"라엘 — 「남은 양분은 열매나 뿌리에 저장돼.」","mis":"SC6-1-u3-X50"}],"explanation":["양분은 어디서 만들어요?","잎에서 출발해요.","하윤의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["짝과 물과 양분의 이동 놀이를 했다(물은 뿌리, 양분은 잎에서 출발).","우리 반 식물도감에 토끼풀·소나무·나팔꽃 소개 자료를 올렸다.","조사한 자료마다 출처를 적었다.","꽃가루로 옛날의 식물과 날씨를 알아낸다는 글을 읽었다."],"title":"⑧ 연결 놀이와 식물도감"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_d#19','sci',6,1,'u3','','g6_1_sci_u3_review_d','unit_review','SC6-1-u3-C24',3,'mc','auto','초록잎반 탐구 일지 ⑦에서 복숭아 열매 속에 씨가 들어 있는 것과 관계있는 열매의 일은 어느 것인가요?',ARRAY['SC6-1-u3-X46','SC6-1-u3-X45','SC6-1-u3-X44']::text[],false,'{"seq":19,"concept":"SC6-1-u3-C24","difficulty":3,"kind":"mc","stem":"초록잎반 탐구 일지 ⑦에서 복숭아 열매 속에 씨가 들어 있는 것과 관계있는 열매의 일은 어느 것인가요?","options":[{"t":"씨를 보호하는 일","correct":true},{"t":"씨를 만드는 일","mis":"SC6-1-u3-X46"},{"t":"양분을 만드는 일","mis":"SC6-1-u3-X45"},{"t":"꽃가루를 옮기는 일","mis":"SC6-1-u3-X44"}],"explanation":["씨가 속에 있어요.","열매가 감싸요.","씨를 보호해요."],"asset":{"type":"passage","lines":["제라늄꽃을 암술·수술·꽃잎·꽃받침으로 나누어 흰 종이에 놓았다.","꽃가루 앨러지가 있는 친구는 보안경과 마스크를 썼다.","벌이 꽃 사이를 날아다니며 꽃가루를 묻히는 영상을 보았다.","복숭아 열매를 잘라 속에 든 씨를 찾아보았다."],"title":"⑦ 꽃 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_d#20','sci',6,1,'u3','','g6_1_sci_u3_review_d','unit_review','SC6-1-u3-C32',3,'mc','auto','초록잎반 탐구 일지 ⑧의 글처럼 꽃가루로 옛날 날씨를 알아낼 수 있는 까닭은 무엇인가요?',ARRAY['SC6-1-u3-X55','SC6-1-u3-X54']::text[],false,'{"seq":20,"concept":"SC6-1-u3-C32","difficulty":3,"kind":"mc","stem":"초록잎반 탐구 일지 ⑧의 글처럼 꽃가루로 옛날 날씨를 알아낼 수 있는 까닭은 무엇인가요?","options":[{"t":"꽃가루는 모양이 잘 변하지 않고 식물마다 모양이 달라서","correct":true},{"t":"꽃가루는 모두 같은 모양이어서","mis":"SC6-1-u3-X55"},{"t":"꽃가루가 크고 금방 사라져서","mis":"SC6-1-u3-X55"},{"t":"꽃가루는 앨러지만 일으켜서","mis":"SC6-1-u3-X54"}],"explanation":["오래 남아요.","모양이 달라요.","그래서 알 수 있어요."],"asset":{"type":"passage","lines":["짝과 물과 양분의 이동 놀이를 했다(물은 뿌리, 양분은 잎에서 출발).","우리 반 식물도감에 토끼풀·소나무·나팔꽃 소개 자료를 올렸다.","조사한 자료마다 출처를 적었다.","꽃가루로 옛날의 식물과 날씨를 알아낸다는 글을 읽었다."],"title":"⑧ 연결 놀이와 식물도감"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_d#21','sci',6,1,'u3','','g6_1_sci_u3_review_d','unit_review','SC6-1-u3-C30',3,'mc','auto','식물도감 소개 자료를 평가할 때 가장 잘 만든 자료는 어느 것인가요?',ARRAY['SC6-1-u3-X52','SC6-1-u3-X53']::text[],false,'{"seq":21,"concept":"SC6-1-u3-C30","difficulty":3,"kind":"mc","stem":"식물도감 소개 자료를 평가할 때 가장 잘 만든 자료는 어느 것인가요?","options":[{"t":"사진과 함께 뿌리·줄기·잎·꽃의 특징을 설명하고 출처를 적은 자료","correct":true},{"t":"사진만 크게 넣고 설명은 뺀 자료","mis":"SC6-1-u3-X52"},{"t":"설명을 누리집에서 그대로 옮기고 출처는 뺀 자료","mis":"SC6-1-u3-X53"},{"t":"친구와 같은 식물을 똑같이 옮겨 적은 자료","mis":"SC6-1-u3-X52"}],"explanation":["구조와 기능을 담아요.","출처를 적어요.","잘 만든 자료예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_d#22','sci',6,1,'u3','','g6_1_sci_u3_review_d','unit_review','SC6-1-u3-C27',3,'mc','auto','초록잎반 탐구 일지 ⑧의 놀이를 실제 식물에 견주어 바르게 설명한 것은 어느 것인가요?',ARRAY['SC6-1-u3-X49','SC6-1-u3-X19','SC6-1-u3-X48']::text[],false,'{"seq":22,"concept":"SC6-1-u3-C27","difficulty":3,"kind":"mc","stem":"초록잎반 탐구 일지 ⑧의 놀이를 실제 식물에 견주어 바르게 설명한 것은 어느 것인가요?","options":[{"t":"물 말이 뿌리에서 잎으로 가는 것은 흡수한 물이 줄기를 지나 잎에 닿는 것과 같다","correct":true},{"t":"물 말이 잎에서 출발해 뿌리로 가는 것과 같다","mis":"SC6-1-u3-X49"},{"t":"양분 말이 뿌리에서 출발하는 것은 뿌리가 양분을 만들기 때문이다","mis":"SC6-1-u3-X19"},{"t":"물 말과 양분 말은 서로 다른 식물을 나타낸다","mis":"SC6-1-u3-X48"}],"explanation":["놀이와 식물을 견줘요.","물은 뿌리에서 출발해요.","줄기를 지나 잎에 가요."],"asset":{"type":"passage","lines":["짝과 물과 양분의 이동 놀이를 했다(물은 뿌리, 양분은 잎에서 출발).","우리 반 식물도감에 토끼풀·소나무·나팔꽃 소개 자료를 올렸다.","조사한 자료마다 출처를 적었다.","꽃가루로 옛날의 식물과 날씨를 알아낸다는 글을 읽었다."],"title":"⑧ 연결 놀이와 식물도감"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_d#23','sci',6,1,'u3','','g6_1_sci_u3_review_d','unit_review','SC6-1-u3-C29',4,'essay','teacher','초록잎반 탐구 일지 ⑧의 놀이를 떠올려, 식물에서 양분이 이동하는 과정과 관련지어 식물의 각 기관이 연결되어 있음을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SC6-1-u3-C29","difficulty":4,"kind":"essay","stem":"초록잎반 탐구 일지 ⑧의 놀이를 떠올려, 식물에서 양분이 이동하는 과정과 관련지어 식물의 각 기관이 연결되어 있음을 쓰세요.","answer_guide":{"answer":"예: 잎에서 광합성으로 만든 양분은 줄기를 통해 식물 전체로 이동해 쓰이고, 남은 양분은 뿌리·줄기·열매 등에 저장된다. 이처럼 식물의 각 기관은 서로 연결되어 있다.","scoring_points":["잎에서 양분을 만든다고 썼는가","줄기를 통해 이동한다고 썼는가","남은 양분이 저장된다고 썼는가"]},"explanation":["양분은 잎에서 출발해요.","줄기를 통해 가요.","기관이 이어져 있어요."],"asset":{"type":"passage","lines":["짝과 물과 양분의 이동 놀이를 했다(물은 뿌리, 양분은 잎에서 출발).","우리 반 식물도감에 토끼풀·소나무·나팔꽃 소개 자료를 올렸다.","조사한 자료마다 출처를 적었다.","꽃가루로 옛날의 식물과 날씨를 알아낸다는 글을 읽었다."],"title":"⑧ 연결 놀이와 식물도감"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_d#24','sci',6,1,'u3','','g6_1_sci_u3_review_d','unit_review','SC6-1-u3-C6',4,'mc','auto','「세포는 모두 너무 작아서 현미경 없이는 절대 볼 수 없다.」라는 말을 바로잡은 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u3-X11','SC6-1-u3-X10']::text[],false,'{"seq":24,"concept":"SC6-1-u3-C6","difficulty":4,"kind":"mc","stem":"「세포는 모두 너무 작아서 현미경 없이는 절대 볼 수 없다.」라는 말을 바로잡은 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"대부분의 세포는 현미경이 필요하지만, 달걀처럼 영양물질을 저장해 맨눈으로 보이는 세포도 있다","correct":true},{"t":"세포는 모두 커서 맨눈으로 잘 보인다","mis":"SC6-1-u3-X11"},{"t":"맞는 말이므로 바로잡을 것이 없다","mis":"SC6-1-u3-X10"},{"t":"달걀은 세포가 아니므로 이 말은 맞다","mis":"SC6-1-u3-X10"}],"explanation":["대부분은 작아요.","달걀은 하나의 세포예요.","맨눈으로 보이는 세포도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_sci_u3_review_d#25','sci',6,1,'u3','','g6_1_sci_u3_review_d','unit_review','SC6-1-u3-C33',4,'mc','auto','이 단원에서 배운 내용을 바르게 정리한 것은 어느 것인가요?',ARRAY['SC6-1-u3-X56','SC6-1-u3-X29','SC6-1-u3-X48']::text[],false,'{"seq":25,"concept":"SC6-1-u3-C33","difficulty":4,"kind":"mc","stem":"이 단원에서 배운 내용을 바르게 정리한 것은 어느 것인가요?","options":[{"t":"생물은 세포로 이루어져 있고, 뿌리·줄기·잎·꽃은 저마다 하는 일이 있으며, 물과 양분으로 서로 연결되어 있다","correct":true},{"t":"식물마다 기관이 전혀 달라 함께 정리할 수 없다","mis":"SC6-1-u3-X56"},{"t":"광합성은 잎에서만, 증산 작용은 줄기에서만 일어난다","mis":"SC6-1-u3-X29"},{"t":"각 기관은 따로 일해서 하나가 다쳐도 괜찮다","mis":"SC6-1-u3-X48"}],"explanation":["세포를 떠올려요.","기관의 일을 떠올려요.","연결을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
